                                ) : (
                                  <>
                                    <footer.FooterColumnId />
                                    {hasFilter && (
                                      <span className="filtered-indicator">
                                        {' '}
                                        ✓
                                      </span>
                                    )}
                                  </>
                                )}
                              </>
                            )}
                          </td>
                        )
                      }}
                    </table.AppFooter>
                  ))}
                </tr>
              ))}
            </tfoot>
          </table>
        </div>

        {/* Pagination using the same pre-bound component */}
        <table.PaginationControls />

        {/* Row count using the same pre-bound component */}
        <table.RowCount />
      </div>
    </table.AppTable>
  )
}

