export function TradingTable() {
  const controller = useTradingShellController()
  const feed = useMarketFeedController()
  const quotes = useSelector(feed.quotes)

  useLayoutEffect(() => feed.completeRender())
  useTableBenchmark(controller)
  const table = useTradingTable({ quotes })
  const layoutRefs = useTradingTableLayout(table)

  return (
    <table.Subscribe
      selector={(state) => ({
        sorting: state.sorting,
        columnFilters: state.columnFilters,
        columnOrder: state.columnOrder,
      })}
    >
      {(coreState) => (
        <TradingTableViewport
          table={table}
          rows={readRows(table, quotes, coreState)}
          sourceRowCount={quotes.length}
          layoutRefs={layoutRefs}
          reportRenderedRowCount={controller.actions.setRenderedRowCount}
        />
      )}
    </table.Subscribe>
  )
}

type TradingTableInstance = ReturnType<typeof useTradingTable>

interface ColumnDragRuntime {
  columnId: string | null
  sourceElement: HTMLTableCellElement | null
  targetElement: HTMLTableCellElement | null
}

function clearColumnDrag(runtime: ColumnDragRuntime): void {
  runtime.sourceElement?.classList.remove('is-column-dragging')
  runtime.targetElement?.classList.remove('is-column-drop-target')
  runtime.columnId = null
  runtime.sourceElement = null
  runtime.targetElement = null
}

function showColumnDropTarget(
  runtime: ColumnDragRuntime,
  targetColumnId: string,
  targetElement: HTMLTableCellElement | null,
): void {
  runtime.targetElement?.classList.remove('is-column-drop-target')
  runtime.targetElement = null
  if (runtime.columnId === targetColumnId || !targetElement) return
  targetElement.classList.add('is-column-drop-target')
  runtime.targetElement = targetElement
}

function useTradingTableLayout(table: TradingTableInstance) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const tableRef = useRef<HTMLTableElement>(null)
  const fitRuntime = useRef({ manuallyResized: false })
  const tableRuntime = useRef(table)
  tableRuntime.current = table

  useLayoutEffect(() => {
    const writeColumnSizes = () => {
      const currentTable = tableRuntime.current
      const tableElement = tableRef.current
      if (!tableElement) return
      for (const header of currentTable.getFlatHeaders()) {
        tableElement.style.setProperty(
          `--header-${header.id}-size`,
          String(header.getSize()),
        )
        tableElement.style.setProperty(
          `--col-${header.column.id}-size`,
          String(header.column.getSize()),
        )
      }
      tableElement.style.width = `${currentTable.getTotalSize()}px`
    }

    writeColumnSizes()
    const sizingSubscription =
      tableRuntime.current.atoms.columnSizing.subscribe(writeColumnSizes)
    const orderSubscription =
      tableRuntime.current.atoms.columnOrder.subscribe(writeColumnSizes)
    const fitAvailableWidth = () => {
      const currentTable = tableRuntime.current
      const scrollElement = scrollRef.current
      if (!scrollElement || fitRuntime.current.manuallyResized) return
      const currentWidth = currentTable.getTotalSize()
      const availableWidth = scrollElement.clientWidth
      if (availableWidth <= currentWidth + 1 || currentWidth <= 0) return

      const ratio = availableWidth / currentWidth
      currentTable.setColumnSizing(
        Object.fromEntries(
          currentTable
            .getVisibleLeafColumns()
            .map((column) => [column.id, column.getSize() * ratio]),
        ),
      )
    }
    const resizeObserver = new ResizeObserver(fitAvailableWidth)
    const resizingSubscription =
      tableRuntime.current.atoms.columnResizing.subscribe((state) => {
        if (state.isResizingColumn !== false) {
          fitRuntime.current.manuallyResized = true
        }
      })
    if (scrollRef.current) resizeObserver.observe(scrollRef.current)
    fitAvailableWidth()

    return () => {
      sizingSubscription.unsubscribe()
      orderSubscription.unsubscribe()
      resizingSubscription.unsubscribe()
      resizeObserver.disconnect()
    }
  }, [])

  return { scrollRef, tableRef }
}

function TradingTableHeader(props: { table: TradingTableInstance }) {
  const dragRuntime = useRef<ColumnDragRuntime>({
    columnId: null,
    sourceElement: null,
    targetElement: null,
  })

  return (
    <props.table.Subscribe
      selector={(state) => ({
        columnOrder: state.columnOrder,
        sorting: state.sorting,
      })}
    >
      {() => (
        <thead>
          {props.table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const isLeaf = header.subHeaders.length === 0
                const sorted = header.column.getIsSorted()
                return (
                  <th
                    key={header.id}
                    colSpan={header.colSpan}
                    style={{
                      width: `calc(var(--header-${header.id}-size) * 1px)`,
                    }}
                    className={getHeaderClassName(header)}
                    aria-sort={isLeaf ? sortAriaValue(sorted) : undefined}
                  >
                    {!header.isPlaceholder &&
                      (isLeaf ? (
                        <>
                          <div
                            className="leaf-header-content"
                            onDragOver={(event) => {
                              event.preventDefault()
                              showColumnDropTarget(
                                dragRuntime.current,
                                header.column.id,
                                event.currentTarget.closest('th'),
                              )
                            }}
                            onDrop={(event) => {
                              event.preventDefault()
                              const dataTransfer = event.dataTransfer
                              const sourceId =
                                dataTransfer?.getData('text/plain') ||
                                dragRuntime.current.columnId
                              if (sourceId) {
                                props.table.setColumnOrder(
                                  reorderColumnIds(
                                    props.table
                                      .getVisibleLeafColumns()
                                      .map((column) => column.id),
                                    sourceId,
                                    header.column.id,
                                  ),
                                )
                              }
                              clearColumnDrag(dragRuntime.current)
                            }}
                          >
                            <button
                              type="button"
                              className="column-drag-handle"
                              draggable
                              aria-label={`Move ${header.column.id} column`}
                              onDragStart={(event) => {
                                const runtime = dragRuntime.current
                                runtime.columnId = header.column.id
                                runtime.sourceElement =
                                  event.currentTarget.closest('th')
                                runtime.sourceElement?.classList.add(
                                  'is-column-dragging',
                                )
                                const dataTransfer = event.dataTransfer
                                if (!dataTransfer) return
                                dataTransfer.effectAllowed = 'move'
                                dataTransfer.setData(
                                  'text/plain',
                                  header.column.id,
                                )
                              }}
                              onDragEnd={() => {
                                clearColumnDrag(dragRuntime.current)
                              }}
                            >
                              ⋮⋮
                            </button>
                            <button
                              type="button"
                              className={`sort-header-button${
                                header.column.getCanSort() ? ' is-sortable' : ''
                              }`}
                              disabled={!header.column.getCanSort()}
                              onClick={header.column.getToggleSortingHandler()}
                            >
                              <span className="header-label">
                                <FlexRender header={header} />
                              </span>
                              {header.column.getCanSort() && (
                                <span
                                  className={`sort-indicator${
                                    sorted ? ' is-active' : ''
                                  }`}
                                  aria-hidden="true"
                                >
                                  {sortIndicator(sorted)}
                                </span>
                              )}
                            </button>
                          </div>
                          {header.column.getCanResize() && (
                            <props.table.Subscribe
                              selector={(state) =>
                                state.columnResizing.isResizingColumn ===
                                header.column.id
                              }
                            >
                              {(isResizing) => (
                                <div
                                  className={`column-resize-handle${
                                    isResizing ? ' is-resizing' : ''
                                  }`}
                                  role="separator"
                                  aria-orientation="vertical"
                                  onDblClick={() => header.column.resetSize()}
                                  onMouseDown={header.getResizeHandler()}
                                  onTouchStart={header.getResizeHandler()}
                                />
                              )}
                            </props.table.Subscribe>
                          )}
                        </>
                      ) : (
                        <FlexRender header={header} />
                      ))}
                  </th>
                )
              })}
            </tr>
          ))}
        </thead>
      )}
    </props.table.Subscribe>
  )
}

function useTradingTable(props: { quotes: Array<MarketQuote> }) {
  return useTable(
    {
      key: 'preact-realtime-trading',
      features: tradingFeatures,
      columns: tradingColumns,
      data: props.quotes,
      getRowId: (row) => row.id,
      columnResizeMode: 'onChange',
      defaultColumn: { minSize: 56, maxSize: 800 },
      autoResetCellSelection: false,
    },
    () => null,
  )
}

function TradingTableViewport(props: {
  table: ReturnType<typeof useTradingTable>
  rows: ReturnType<ReturnType<typeof useTradingTable>['getRowModel']>['rows']
  sourceRowCount: number
  layoutRefs: ReturnType<typeof useTradingTableLayout>
  reportRenderedRowCount: (count: number) => void
}) {
  const renderedRowCount = props.rows.length

  useLayoutEffect(() => {
    props.reportRenderedRowCount(renderedRowCount)
  }, [props.reportRenderedRowCount, renderedRowCount])

  return (
    <div
      ref={props.layoutRefs.scrollRef}
      className="table-scroll"
      data-trading-table
      tabIndex={0}
      onKeyDown={(event) => handleCellNavigation(props.table, event)}
    >
      <table
        ref={props.layoutRefs.tableRef}
        className="trading-data-grid"
        data-testid="trading-table"
        role="grid"
        aria-multiselectable="true"
      >
        <TradingTableHeader table={props.table} />
        <TradingRows
          table={props.table}
          rows={props.rows}
          sourceRowCount={props.sourceRowCount}
        />
      </table>
    </div>
  )
}

function TradingRows(props: {
  table: ReturnType<typeof useTradingTable>
  rows: ReturnType<ReturnType<typeof useTradingTable>['getRowModel']>['rows']
  sourceRowCount: number
}) {
  const { selectSymbol } = useTradingShellController().actions
  const [pointerInteractions] = useState(
    () => new TradingGridPointerController(),
  )

  return (
    <tbody
      data-source-row-count={props.sourceRowCount}
      onMouseDown={(event) =>
        pointerInteractions.handleMouseDown(props.table, event, selectSymbol)
      }
      onPointerOver={(event) =>
        pointerInteractions.handlePointerOver(props.table, event)
      }
      onMouseLeave={() => pointerInteractions.resetPointerCell()}
      onClick={(event) => pointerInteractions.handleClick(props.table, event)}
    >
      {props.rows.map((row) => (
        <TradingRowBoundary key={row.id} table={props.table} row={row} />
      ))}
    </tbody>
  )
}

type TradingTableRow = ReturnType<
  ReturnType<typeof useTradingTable>['getRowModel']
>['rows'][number]

function TradingRowBoundary(props: {
  table: ReturnType<typeof useTradingTable>
  row: TradingTableRow
}) {
  const { row, table } = props

  return (
    <table.Subscribe
      selector={(state) =>
        `${row.id in state.rowSelection ? 1 : 0}:${cellSelectionRowKey(
          state.cellSelection,
          table.getCellSelectionBounds(),
          row.getDisplayIndex(),
          row.id,
        )}`
      }
    >
      {() => (
        <TradingRow quote={row.original} rowSelected={row.getIsSelected()}>
          {row.getVisibleCells().map((cell) => {
            const edges = cell.getSelectionEdges()

            return (
              <td
                key={cell.id}
                style={{
                  width: `calc(var(--col-${cell.column.id}-size) * 1px)`,
                }}
                data-column-id={cell.column.id}
                data-cell-focused={cell.getIsFocused() ? 'true' : undefined}
                data-selection-top={edges.top ? 'true' : undefined}
                data-selection-right={edges.right ? 'true' : undefined}
                data-selection-bottom={edges.bottom ? 'true' : undefined}
                data-selection-left={edges.left ? 'true' : undefined}
                aria-selected={cell.getIsSelected()}
                tabIndex={cell.getTabIndex()}
              >
                <FlexRender cell={cell} />
              </td>
            )
          })}
        </TradingRow>
      )}
    </table.Subscribe>
  )
}

function getHeaderClassName(header: {
  subHeaders: ReadonlyArray<unknown>
  column: { id: string }
}): string | undefined {
  if (header.subHeaders.length > 0) return 'column-group-header'
  return isTextColumn(header.column.id) ? undefined : 'numeric-header'
}

function isTextColumn(columnId: string): boolean {
  return columnId === 'market' || columnId === 'name' || columnId === 'symbol'
}

function readRows(
  table: ReturnType<typeof useTradingTable>,
  quoteSnapshot: Array<MarketQuote>,
  coreState: CoreTableState,
) {
  void quoteSnapshot
  void coreState
  return readMeasuredRows(() => table.getRowModel().rows)
}

function cellSelectionRowKey(
  ranges: CellSelectionState,
  bounds: Array<CellSelectionBounds>,
  rowIndex: number,
  rowId: string,
): string {
  const active = ranges.at(-1)
  const initial =
    active?.anchorRowId === rowId ? `f${active.anchorColumnId}` : ''

  return bounds.reduce((key, bound) => {
    const self = rowIndex >= bound.minRowIndex && rowIndex <= bound.maxRowIndex
    const above =
      rowIndex - 1 >= bound.minRowIndex && rowIndex - 1 <= bound.maxRowIndex
    const below =
      rowIndex + 1 >= bound.minRowIndex && rowIndex + 1 <= bound.maxRowIndex
    if (!self && !above && !below) return key
    return `${key}|${self ? 1 : 0}${above ? 1 : 0}${below ? 1 : 0}:${bound.minColumnIndex}-${bound.maxColumnIndex}`
  }, initial)
}

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import {
  setRangeValue,
  pausedFeedUrl,
} from '../../../../../tests/e2e/helpers/setRangeValue'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []
  page.on('pageerror', (error) => errors.push(error.message))
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })
  return errors
}

test('runs the Preact realtime trading workload', async ({ page }) => {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  try {
    await page.goto(pausedFeedUrl(server.url))

    const table = page.getByTestId('trading-table')
    const instrumentCount = page.getByTestId('instrument-count-select')
    await expect(table).toBeVisible()
    await expect(instrumentCount).toHaveValue('100')
    await expect(page.locator('.brand')).toHaveText('MARKET MONITOR')
    await expect(table.locator('tbody tr')).toHaveCount(100)
    await expect(table.locator('tbody')).toHaveCSS('user-select', 'none')
    await expect(table.locator('tbody tr').first()).toHaveCSS(
      'content-visibility',
      'auto',
    )
    await expect(table.locator('thead tr')).toHaveCount(2)
    await expect(table.locator('thead tr').last().locator('th')).toHaveCount(14)
    await expect(table.locator('thead')).not.toContainText('Identity')
    await expect(table.locator('thead')).not.toContainText('Market Data')
    await expect(table.locator('thead')).toContainText('Market')
    await expect(table.locator('thead')).toContainText('Bid Vol')
    await expect(table.locator('thead')).toContainText('Intraday')
    const selectedRow = table.locator('tbody tr').first()
    const selectedSymbol = await selectedRow.getAttribute('data-symbol')
    await selectedRow.locator('td').nth(1).click()
    await expect(page.getByTestId('selected-instrument')).toContainText(
      selectedSymbol ?? '',
    )
    await expect(page.getByTestId('feed-status')).toHaveText('FEED PAUSED')
    await expect(instrumentCount.locator('option[value="150"]')).toHaveCount(1)
    await expect(instrumentCount.locator('option[value="350"]')).toHaveCount(1)
    await expect(instrumentCount.locator('option[value="750"]')).toHaveCount(1)

    const targetRateSlider = page.getByTestId('target-rate-slider')
    await expect(targetRateSlider).toHaveAttribute('min', '0')
    await expect(targetRateSlider).toHaveAttribute('max', '9')
    await expect(targetRateSlider).toHaveAttribute('step', '1')
    await expect(targetRateSlider).toHaveValue('6')
    await setRangeValue(targetRateSlider, '7')
    await expect(page.getByTestId('target-sample-rate')).toContainText(
      '25K samples/s',
    )
    await setRangeValue(targetRateSlider, '8')
    await expect(page.getByTestId('target-sample-rate')).toContainText(
      '50K samples/s',
    )
    await setRangeValue(targetRateSlider, '6')

    const sparklineInterval = page.getByTestId(
      'sparkline-sample-interval-select',
    )
    await expect(sparklineInterval).toHaveValue('16')
    await sparklineInterval.selectOption('100')
    await expect(sparklineInterval).toHaveValue('100')
    await sparklineInterval.selectOption('16')

    const publishInterval = page.getByTestId('publish-interval-select')
    await expect(publishInterval.locator('option[value="500"]')).toHaveCount(1)
    await expect(publishInterval.locator('option[value="1000"]')).toHaveCount(1)

    expect(
      await page.evaluate(
        () => performance.getEntriesByName('tanstack-row-model').length > 0,
      ),
    ).toBe(true)

    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

