          </tbody>
        </table>
        <div>{table.getRowModel().rows.length.toLocaleString()} Rows</div>
        <div></div>
        {/* Store mode: full state for debugging */}
        <pre data-testid="table-state">
          {JSON.stringify(table.state, null, 2)}
        </pre>
      </>
    </div>
  )
}

