import * as React from 'react'
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import {
  Box,
  Checkbox,
  Input,
  Menu,
  NativeSelect,
  Popover,
  Portal,
  Text,
} from '@chakra-ui/react'
import { IconArrowDown, IconArrowUp, IconArrowsSort } from '@tabler/icons-react'

// ---------------------------------------------------------------------------
