export function DataTableSortList(): React.ReactNode {
  const table = useTableContext()
  const sorting = table.state.sorting

  const labelId = React.useId()
  const descriptionId = React.useId()
  const listId = React.useId()
  const [open, setOpen] = React.useState(false)

  const sortableColumns = React.useMemo(
    () => table.getAllColumns().filter((column) => column.getCanSort()),
    [table],
  )

  const onColumnSelect = React.useCallback(
    (currentSortId: string, newColumnId: string) => {
      const newSorting = sorting.map((s) =>
        s.id === currentSortId ? { ...s, id: newColumnId } : s,
      )
      table.setSorting(newSorting)
    },
    [sorting, table],
  )

  const onSortAdd = React.useCallback(() => {
    const firstAvailableColumn = sortableColumns.find(
      (col) => !sorting.some((s) => s.id === col.id),
    )
    if (firstAvailableColumn) {
      table.setSorting([
        ...sorting,
        { id: firstAvailableColumn.id, desc: false },
      ])
    }
  }, [sorting, sortableColumns, table])

  const onSortUpdate = React.useCallback(
    (sortId: string, updates: Partial<Omit<ColumnSort, 'id'>>) => {
      const newSorting = sorting.map((s) =>
        s.id === sortId ? { ...s, ...updates } : s,
      )
      table.setSorting(newSorting)
    },
    [sorting, table],
  )

  const onSortRemove = React.useCallback(
    (sortId: string) => {
      const newSorting = sorting.filter((s) => s.id !== sortId)
      table.setSorting(newSorting)
    },
    [sorting, table],
  )

  return (
    <Sortable
      value={sorting}
      onValueChange={(value) => table.setSorting(value)}
      getItemValue={(item) => item.id}
    >
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          render={
            <Button
              variant="outline"
              size="sm"
              className="[&_svg]:size-3"
              onClick={(event) => event.currentTarget.focus()}
              onPointerDown={(event) => {
                const target = event.target
                if (!(target instanceof HTMLElement)) return
                if (target.hasPointerCapture(event.pointerId)) {
                  target.releasePointerCapture(event.pointerId)
                }

                if (
                  event.button === 0 &&
                  event.ctrlKey === false &&
                  event.pointerType === 'mouse'
                ) {
                  event.preventDefault()
                }
              }}
            />
          }
        >
          <ArrowDownUp />
          Sort
          {sorting.length > 0 && (
            <Badge
              variant="secondary"
              className="h-[1.14rem] rounded-[0.2rem] px-[0.32rem] font-mono font-normal text-[0.65rem]"
            >
              {sorting.length}
            </Badge>
          )}
        </PopoverTrigger>
        <PopoverContent
          aria-labelledby={labelId}
          aria-describedby={descriptionId}
          align="start"
          collisionPadding={16}
          className="w-[calc(100vw-theme(spacing.20))] origin-(--transform-origin) flex flex-col gap-3 min-w-72 max-w-[25rem] p-4 sm:w-[25rem]"
        >
          <div className="flex flex-col gap-1">
            <h4 id={labelId} className="font-medium leading-none">
              {sorting.length > 0 ? 'Sort by' : 'No sorting applied'}
            </h4>
            <p
              id={descriptionId}
              className={cn(
                'text-muted-foreground text-sm',
                sorting.length > 0 && 'sr-only',
              )}
            >
              {sorting.length > 0
                ? 'Modify sorting to organize your results.'
                : 'Add sorting to organize your results.'}
            </p>
          </div>
          {sorting.length > 0 ? (
            <SortableContent asChild>
              <div
                role="list"
                id={listId}
                aria-labelledby={labelId}
                aria-describedby={descriptionId}
                className="flex max-h-[300px] flex-col gap-2 overflow-y-auto p-0.5"
              >
                {sorting.map((sort, index) => {
                  const columnTitle =
                    sortableColumns.find((col) => col.id === sort.id)?.columnDef
                      .meta?.label ?? sort.id
                  const sortItemId = `${listId}-item-${sort.id}`
                  const triggerId = `${listId}-${index}-trigger`
                  const fieldListboxId = `${sortItemId}-field-listbox`
                  const operatorListboxId = `${sortItemId}-operator-listbox`

                  return (
                    <SortableItem key={sort.id} value={sort.id} asChild>
                      <div
                        role="listitem"
                        id={sortItemId}
                        tabIndex={-1}
                        className="grid items-center grid-cols-[175px_100px_32px_32px] gap-2"
                      >
                        <Popover>
                          <PopoverTrigger
                            render={
                              <Button
                                role="combobox"
                                id={triggerId}
                                aria-controls={fieldListboxId}
                                aria-label={`Select column to sort by. Current: ${columnTitle}`}
                                variant="outline"
                                size="sm"
                                className="h-8 font-normal justify-between gap-2 focus:outline-none focus:ring-1 focus:ring-ring"
                                onPointerDown={(event) => {
                                  const target = event.target
                                  if (!(target instanceof HTMLElement)) return
                                  if (
                                    target.hasPointerCapture(event.pointerId)
                                  ) {
                                    target.releasePointerCapture(
                                      event.pointerId,
                                    )
