import clsx from 'clsx'

import { useEffect, useRef, useState } from 'react'

import { RangeSlider } from '@mantine/core'
import { parseFromValuesOrFunc } from '../../utils/utils'
import classes from './MRT_FilterRangeSlider.module.css'
import type { RangeSliderProps } from '@mantine/core'

import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'

interface Props<TData extends MRT_RowData> extends RangeSliderProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_FilterRangeSlider = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    options: { mantineFilterRangeSliderProps },
    refs: { filterInputRefs },
  } = table
  const { column } = header
  const { columnDef } = column

  const arg = { column, table }
  const rangeSliderProps = {
    ...parseFromValuesOrFunc(mantineFilterRangeSliderProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterRangeSliderProps, arg),
    ...rest,
  } as RangeSliderProps

  let [min, max] =
    rangeSliderProps.min !== undefined && rangeSliderProps.max !== undefined
      ? [rangeSliderProps.min, rangeSliderProps.max]
      : (column.getFacetedMinMaxValues() ?? [0, 1])

  // fix potential TanStack Table bugs where min or max is an array
  if (Array.isArray(min)) min = min[0]
  if (Array.isArray(max)) max = max[0]
  if (min === null) min = 0
  if (max === null) max = 1

  const [filterValues, setFilterValues] = useState<[number, number]>([min, max])
  const columnFilterValue = column.getFilterValue() as
    [number, number] | undefined

  const isMounted = useRef(false)

  useEffect(() => {
    if (isMounted.current) {
      if (columnFilterValue === undefined) {
        setFilterValues([min, max])
      } else if (Array.isArray(columnFilterValue)) {
        setFilterValues(columnFilterValue)
      }
    }
    isMounted.current = true
  }, [columnFilterValue, min, max])

  return (
    <RangeSlider
      className={clsx('mrt-filter-range-slider', classes.root)}
      max={max}
      min={min}
      onChange={(values) => {
        setFilterValues(values)
      }}
      onChangeEnd={(values) => {
        if (Array.isArray(values)) {
          if (values[0] <= min && values[1] >= max) {
            // if the user has selected the entire range, remove the filter
            column.setFilterValue(undefined)
          } else {
            column.setFilterValue(values)
          }
        }
      }}
      value={filterValues}
      {...rangeSliderProps}
      ref={(node) => {
        if (node) {
          // @ts-ignore
          filterInputRefs.current[`${column.id}-0`] = node
          // @ts-ignore
          if (rangeSliderProps?.ref) {
            // @ts-ignore
            rangeSliderProps.ref = node
          }
        }
      }}
    />
  )
}

import clsx from 'clsx'

import { useEffect, useMemo, useRef, useState } from 'react'

import {
  ActionIcon,
  Autocomplete,
  Badge,
  Box,
  MultiSelect,
  Select,
  TextInput,
} from '@mantine/core'
import { DateInput } from '@mantine/dates'
import { useDebouncedValue } from '@mantine/hooks'

import { localizedFilterOption } from '../../fns/filterFns'
import { parseFromValuesOrFunc } from '../../utils/utils'
import classes from './MRT_FilterTextInput.module.css'
import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'
import type { TextInputProps } from '@mantine/core'
import type { MouseEvent } from 'react'

interface Props<TData extends MRT_RowData> extends TextInputProps {
  header: MRT_Header<TData>
  rangeFilterIndex?: number
  table: MRT_TableInstance<TData>
}

export const MRT_FilterTextInput = <TData extends MRT_RowData>({
  header,
  rangeFilterIndex,
  table,
  ...rest
}: Props<TData>) => {
  const {
    options: {
      columnFilterDisplayMode,
      columnFilterModeOptions,
      icons: { IconX },
      localization,
      mantineFilterAutocompleteProps,
      mantineFilterDateInputProps,
      mantineFilterMultiSelectProps = {
        clearable: true,
      },
      mantineFilterSelectProps,
      mantineFilterTextInputProps,
      manualFiltering,
    },
    refs: { filterInputRefs },
    setColumnFilterFns,
  } = table
  const { column } = header
  const { columnDef } = column

  const arg = { column, rangeFilterIndex, table }
  const textInputProps = {
    ...parseFromValuesOrFunc(mantineFilterTextInputProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterTextInputProps, arg),
    ...rest,
  }

  const selectProps = {
    ...parseFromValuesOrFunc(mantineFilterSelectProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterSelectProps, arg),
  }

  const multiSelectProps = {
    ...parseFromValuesOrFunc(mantineFilterMultiSelectProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterMultiSelectProps, arg),
  }

  const dateInputProps = {
    ...parseFromValuesOrFunc(mantineFilterDateInputProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterDateInputProps, arg),
  }

  const autoCompleteProps = {
    ...parseFromValuesOrFunc(mantineFilterAutocompleteProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineFilterAutocompleteProps, arg),
  }

  const isRangeFilter =
    columnDef.filterVariant === 'range' ||
    columnDef.filterVariant === 'date-range' ||
    rangeFilterIndex !== undefined
  const isSelectFilter = columnDef.filterVariant === 'select'
  const isMultiSelectFilter = columnDef.filterVariant === 'multi-select'
  const isDateFilter =
    columnDef.filterVariant === 'date' ||
    columnDef.filterVariant === 'date-range'
  const isAutoCompleteFilter = columnDef.filterVariant === 'autocomplete'
  const allowedColumnFilterOptions =
    columnDef?.columnFilterModeOptions ?? columnFilterModeOptions

  const currentFilterOption = columnDef._filterFn
  const filterChipLabel = ['empty', 'notEmpty'].includes(currentFilterOption)
    ? localizedFilterOption(localization, currentFilterOption)
    : ''
  const filterPlaceholder = !isRangeFilter
    ? (textInputProps?.placeholder ??
      localization.filterByColumn?.replace(
        '{column}',
        String(columnDef.header),
      ))
    : rangeFilterIndex === 0
      ? localization.min
      : rangeFilterIndex === 1
        ? localization.max
        : ''

  const facetedUniqueValues = column.getFacetedUniqueValues()

  const filterSelectOptions = useMemo(
    () =>
      (
        autoCompleteProps?.data ??
        selectProps?.data ??
        multiSelectProps?.data ??
        ((isAutoCompleteFilter || isSelectFilter || isMultiSelectFilter) &&
        facetedUniqueValues
          ? Array.from(facetedUniqueValues.keys())
              .filter((key) => key !== null)
              .sort((a, b) => a.localeCompare(b))
          : [])
      )
        // @ts-ignore
        .filter((o: any) => o !== undefined && o !== null),
    [
      autoCompleteProps?.data,
      facetedUniqueValues,
      isAutoCompleteFilter,
      isMultiSelectFilter,
      isSelectFilter,
      multiSelectProps?.data,
      selectProps?.data,
    ],
  )

  const isMounted = useRef(false)

  const [filterValue, setFilterValue] = useState<any>(() =>
    isMultiSelectFilter
      ? (column.getFilterValue() as Array<string>) || []
      : isRangeFilter
        ? (column.getFilterValue() as [string, string])?.[
            rangeFilterIndex as number
          ] || ''
        : ((column.getFilterValue() as string) ?? ''),
  )

  const [debouncedFilterValue] = useDebouncedValue(
    filterValue,
    manualFiltering ? 400 : 200,
  )

  // send debounced filterValue to table instance
  useEffect(() => {
    if (!isMounted.current) return
    if (isRangeFilter) {
      column.setFilterValue((old: [string, string]) => {
        const newFilterValues = Array.isArray(old) ? old : ['', '']
        newFilterValues[rangeFilterIndex as number] =
          debouncedFilterValue as string
        return newFilterValues
      })
    } else {
      column.setFilterValue(debouncedFilterValue ?? undefined)
    }
  }, [debouncedFilterValue])

  // receive table filter value and set it to local state
  useEffect(() => {
    if (!isMounted.current) {
      isMounted.current = true
      return
    }
    const tableFilterValue = column.getFilterValue()
    if (tableFilterValue === undefined) {
      handleClear()
    } else if (isRangeFilter && rangeFilterIndex !== undefined) {
      setFilterValue(
        ((tableFilterValue ?? ['', '']) as [string, string])[rangeFilterIndex],
      )
    } else {
      setFilterValue(tableFilterValue ?? '')
    }
  }, [column.getFilterValue()])

  const handleClear = () => {
    if (isMultiSelectFilter) {
      setFilterValue([])
      column.setFilterValue([])
    } else if (isRangeFilter) {
      setFilterValue('')
      column.setFilterValue((old: [string | undefined, string | undefined]) => {
        const newFilterValues = Array.isArray(old) ? old : ['', '']
        newFilterValues[rangeFilterIndex as number] = undefined
        return newFilterValues
      })
      // This is from Mantine v6 but it also applies for v7
      // https://github.com/mantinedev/mantine/issues/4716#issuecomment-1702699688
    } else if (isSelectFilter) {
      setFilterValue(null)
      column.setFilterValue(null)
    } else {
      setFilterValue('')
      column.setFilterValue(undefined)
    }
  }

  const handleClearEmptyFilterChip = () => {
    if (isMultiSelectFilter) {
      setFilterValue([])
      column.setFilterValue([])
    } else {
      setFilterValue('')
      column.setFilterValue(undefined)
    }
    setColumnFilterFns((prev) => ({
      ...prev,
      [header.id]: allowedColumnFilterOptions?.[0] ?? 'fuzzy',
    }))
  }

  const { className, ...commonProps } = {
    'aria-label': filterPlaceholder,
    className: clsx(
      'mrt-filter-text-input',
      classes.root,
      isDateFilter
        ? classes['date-filter']
        : isRangeFilter
          ? classes['range-filter']
          : !filterChipLabel && classes['not-filter-chip'],
    ),
    disabled: !!filterChipLabel,
    onChange: setFilterValue,
    onClick: (event: MouseEvent<HTMLInputElement>) => event.stopPropagation(),
    placeholder: filterPlaceholder,
    style: {
      ...(isMultiSelectFilter
        ? multiSelectProps?.style
        : isSelectFilter
          ? selectProps?.style
          : isDateFilter
            ? dateInputProps?.style
            : textInputProps?.style),
    },
    title: filterPlaceholder,
    value:
      isMultiSelectFilter && !Array.isArray(filterValue) ? [] : filterValue,
    variant: 'unstyled',
  } as const

  const ClearButton = filterValue ? (
    <ActionIcon
      aria-label={localization.clearFilter}
      color="var(--mantine-color-gray-7)"
      onClick={handleClear}
      size="sm"
      title={localization.clearFilter ?? ''}
      variant="transparent"
    >
      <IconX />
    </ActionIcon>
  ) : null

  if (columnDef.Filter) {
    return (
      <>{columnDef.Filter?.({ column, header, rangeFilterIndex, table })}</>
    )
  }

  if (filterChipLabel) {
    return (
      <Box style={commonProps.style}>
        <Badge
          className={classes['filter-chip-badge']}
          onClick={handleClearEmptyFilterChip}
          rightSection={ClearButton}
          size="lg"
        >
          {filterChipLabel}
        </Badge>
      </Box>
    )
  }

  if (isMultiSelectFilter) {
    return (
      <MultiSelect
        {...commonProps}
        searchable
        {...multiSelectProps}
        className={clsx(className, multiSelectProps.className)}
        data={filterSelectOptions}
        onChange={(value) => setFilterValue(value)}
        ref={(node) => {
          if (node) {
            filterInputRefs.current[`${column.id}-${rangeFilterIndex ?? 0}`] =
              node
            if (multiSelectProps.ref) {
              multiSelectProps.ref.current = node
            }
          }
        }}
        rightSection={
          filterValue?.toString()?.length && multiSelectProps?.clearable
            ? ClearButton
            : undefined
        }
        style={commonProps.style}
      />
    )
  }

  if (isSelectFilter) {
    return (
      <Select
        {...commonProps}
        clearable
        searchable
        {...selectProps}
        className={clsx(className, selectProps.className)}
        clearButtonProps={{
          size: 'md',
        }}
        data={filterSelectOptions}
        ref={(node) => {
          if (node) {
            filterInputRefs.current[`${column.id}-${rangeFilterIndex ?? 0}`] =
              node
            if (selectProps.ref) {
              selectProps.ref.current = node
            }
          }
        }}
        style={commonProps.style}
      />
    )
  }

  if (isDateFilter) {
    return (
      <DateInput
        {...commonProps}
        allowDeselect
        clearable
        popoverProps={{ withinPortal: columnFilterDisplayMode !== 'popover' }}
        {...dateInputProps}
        className={clsx(className, dateInputProps.className)}
        onChange={(event) => commonProps.onChange(event === null ? '' : event)}
        ref={(node) => {
          if (node) {
            filterInputRefs.current[`${column.id}-${rangeFilterIndex ?? 0}`] =
              node
            if (dateInputProps.ref) {
              dateInputProps.ref.current = node
            }
          }
        }}
        style={commonProps.style}
      />
    )
  }

  if (isAutoCompleteFilter) {
    return (
      <Autocomplete
        {...commonProps}
        onChange={(value) => setFilterValue(value)}
        rightSection={filterValue?.toString()?.length ? ClearButton : undefined}
        {...autoCompleteProps}
        className={clsx(className, autoCompleteProps.className)}
        data={filterSelectOptions}
        ref={(node) => {
          if (node) {
            filterInputRefs.current[`${column.id}-${rangeFilterIndex ?? 0}`] =
              node
            if (autoCompleteProps.ref) {
              autoCompleteProps.ref.current = node
            }
          }
        }}
        style={commonProps.style}
      />
    )
  }

  return (
    <TextInput
      {...commonProps}
      onChange={(e) => setFilterValue(e.target.value)}
      rightSection={filterValue?.toString()?.length ? ClearButton : undefined}
      {...textInputProps}
      className={clsx(className, textInputProps.className)}
      mt={0}
      ref={(node) => {
        if (node) {
          filterInputRefs.current[`${column.id}-${rangeFilterIndex ?? 0}`] =
            node
          if (textInputProps.ref && typeof textInputProps.ref === 'object') {
            textInputProps.ref.current = node
          }
        }
      }}
      style={commonProps.style}
    />
  )
}

import clsx from 'clsx'

import { useEffect, useRef, useState } from 'react'

import { ActionIcon, Collapse, Menu, TextInput, Tooltip } from '@mantine/core'
import { useDebouncedValue } from '@mantine/hooks'

import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_FilterOptionMenu } from '../menus/MRT_FilterOptionMenu'
import classes from './MRT_GlobalFilterTextInput.module.css'
import type { MRT_RowData, MRT_TableInstance } from '../../types'
import type { TextInputProps } from '@mantine/core'

interface Props<TData extends MRT_RowData> extends TextInputProps {
  table: MRT_TableInstance<TData>
}

export const MRT_GlobalFilterTextInput = <TData extends MRT_RowData>({
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: {
      enableGlobalFilterModes,
      icons: { IconSearch, IconX },
      localization,
      mantineSearchTextInputProps,
      manualFiltering,
      positionGlobalFilter,
    },
    refs: { searchInputRef },
    setGlobalFilter,
  } = table
  const { globalFilter, showGlobalFilter } = state

  const textFieldProps = {
    ...parseFromValuesOrFunc(mantineSearchTextInputProps, {
      table,
    }),
    ...rest,
  }

  const isMounted = useRef(false)
  const [searchValue, setSearchValue] = useState(globalFilter ?? '')

  const [debouncedSearchValue] = useDebouncedValue(
    searchValue,
    manualFiltering ? 500 : 250,
  )

  useEffect(() => {
    setGlobalFilter(debouncedSearchValue || undefined)
  }, [debouncedSearchValue])

  const handleClear = () => {
    setSearchValue('')
    setGlobalFilter(undefined)
  }

  useEffect(() => {
    if (isMounted.current) {
      if (globalFilter === undefined) {
        handleClear()
      } else {
        setSearchValue(globalFilter)
      }
    }
    isMounted.current = true
  }, [globalFilter])

  return (
    <Collapse className={classes.collapse} expanded={showGlobalFilter}>
      {enableGlobalFilterModes && (
        <Menu withinPortal>
          <Menu.Target>
            <ActionIcon
              aria-label={localization.changeSearchMode}
              color="gray"
              size="sm"
              variant="transparent"
            >
              <IconSearch />
            </ActionIcon>
          </Menu.Target>
          <MRT_FilterOptionMenu onSelect={handleClear} table={table} />
        </Menu>
      )}
      <TextInput
        leftSection={!enableGlobalFilterModes && <IconSearch />}
        mt={0}
        mx={positionGlobalFilter !== 'left' ? 'mx' : undefined}
        onChange={(event) => setSearchValue(event.target.value)}
        placeholder={localization.search}
        rightSection={
          <ActionIcon
            aria-label={localization.clearSearch}
            color="gray"
            disabled={!searchValue?.length}
            hidden={!searchValue}
            onClick={handleClear}
            size="sm"
            style={{
              visibility: !searchValue ? 'hidden' : undefined,
            }}
            variant="transparent"
          >
            <Tooltip label={localization.clearSearch} withinPortal>
              <IconX />
            </Tooltip>
          </ActionIcon>
        }
        value={searchValue ?? ''}
        variant="filled"
        {...textFieldProps}
        className={clsx(
          'mrt-global-filter-text-input',
          classes.root,
          textFieldProps?.className,
        )}
        ref={(node) => {
          if (node) {
            searchInputRef.current = node
            if (textFieldProps?.ref) {
              // @ts-ignore
              textFieldProps.ref = node
            }
          }
        }}
      />
    </Collapse>
  )
}

import { Checkbox, Radio, Switch, Tooltip } from '@mantine/core'
import {
  getIsRowSelected,
  getMRT_RowSelectionHandler,
  getMRT_SelectAllHandler,
} from '../../utils/row.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import type { MouseEvent } from 'react'

import type { CheckboxProps, RadioProps, SwitchProps } from '@mantine/core'

import type { MRT_Row, MRT_RowData, MRT_TableInstance } from '../../types'

interface Props<TData extends MRT_RowData> extends CheckboxProps {
  renderedRowIndex?: number
  row?: MRT_Row<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_SelectCheckbox = <TData extends MRT_RowData>({
  renderedRowIndex = 0,
  row,
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: {
      enableMultiRowSelection,
      localization,
      mantineSelectAllCheckboxProps,
      mantineSelectCheckboxProps,
      selectAllMode,
      selectDisplayMode,
    },
  } = table
  const { density, isLoading } = state

  const selectAll = !row

  const allRowsSelected = selectAll
    ? selectAllMode === 'page'
      ? table.getIsAllPageRowsSelected()
      : table.getIsAllRowsSelected()
    : undefined

  const isChecked = selectAll
    ? allRowsSelected
    : getIsRowSelected({ row, table })

  const checkboxProps = {
    ...(selectAll
      ? parseFromValuesOrFunc(mantineSelectAllCheckboxProps, { table })
      : parseFromValuesOrFunc(mantineSelectCheckboxProps, {
          row,
          table,
        })),
    ...rest,
  }

  const onSelectionChange = row
    ? getMRT_RowSelectionHandler({
        renderedRowIndex,
        row,
        table,
      })
    : undefined

  const onSelectAllChange = getMRT_SelectAllHandler({ table })

  const commonProps = {
    'aria-label': selectAll
      ? localization.toggleSelectAll
      : localization.toggleSelectRow,
    checked: isChecked,
    disabled:
      isLoading || (row && !row.getCanSelect()) || row?.id === 'mrt-row-create',
    onChange: (event) => {
      event.stopPropagation()
      if (selectAll) {
        onSelectAllChange(event)
      } else {
        onSelectionChange!(event)
      }
    },
    size: density === 'xs' ? 'sm' : 'md',
    ...checkboxProps,
    onClick: (e: MouseEvent<HTMLInputElement>) => {
      e.stopPropagation()
      checkboxProps?.onClick?.(e)
    },
    title: undefined,
  } as CheckboxProps & RadioProps & SwitchProps

  return (
    <Tooltip
      label={
        checkboxProps?.title ??
        (selectAll
          ? localization.toggleSelectAll
          : localization.toggleSelectRow)
      }
      openDelay={1000}
      withinPortal
    >
      <span>
        {selectDisplayMode === 'switch' ? (
          <Switch {...commonProps} />
        ) : selectDisplayMode === 'radio' ||
          enableMultiRowSelection === false ? (
          <Radio {...commonProps} />
        ) : (
          <Checkbox
            indeterminate={
              !isChecked && selectAll
                ? table.getIsSomeRowsSelected()
                : row?.getIsSomeSelected() && row.getCanSelectSubRows()
            }
            {...commonProps}
          />
        )}
      </span>
    </Tooltip>
  )
}

import { ActionIcon, Menu, Tooltip } from '@mantine/core'
import { parseFromValuesOrFunc } from '../../utils/utils'
import classes from './MRT_ColumnActionMenu.module.css'
import type { MenuProps } from '@mantine/core'

import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'

interface Props<TData extends MRT_RowData> extends MenuProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_ColumnActionMenu = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: {
      columnFilterDisplayMode,
      enableColumnFilters,
      enableColumnPinning,
      enableColumnResizing,
      enableGrouping,
      enableHiding,
      enableSorting,
      enableSortingRemoval,
      icons: {
        IconArrowAutofitContent,
        IconBoxMultiple,
        IconClearAll,
        IconColumns,
        IconDotsVertical,
        IconEyeOff,
        IconFilter,
        IconFilterOff,
        IconPinned,
        IconPinnedOff,
        IconSortAscending,
        IconSortDescending,
      },
      localization,
      mantineColumnActionsButtonProps,
      renderColumnActionsMenuItems,
    },
    refs: { filterInputRefs },
    setColumnOrder,
    setColumnResizing,
    setShowColumnFilters,
    toggleAllColumnsVisible,
  } = table
  const { column } = header
  const { columnDef } = column
  const { columnSizing, columnVisibility } = state

  const arg = { column, table }
  const actionIconProps = {
    ...parseFromValuesOrFunc(mantineColumnActionsButtonProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineColumnActionsButtonProps, arg),
  }

  const handleClearSort = () => {
    column.clearSorting()
  }

  const handleSortAsc = () => {
    column.toggleSorting(false)
  }

  const handleSortDesc = () => {
    column.toggleSorting(true)
  }

  const handleResetColumnSize = () => {
    setColumnResizing((old) => ({ ...old, isResizingColumn: false }))
    column.resetSize()
  }

  const handleHideColumn = () => {
    column.toggleVisibility(false)
  }

  const handlePinColumn = (pinDirection: 'start' | 'end' | false) => {
    column.pin(pinDirection)
  }

  const handleGroupByColumn = () => {
    column.toggleGrouping()
    setColumnOrder((old: any) => ['mrt-row-expand', ...old])
  }

  const handleClearFilter = () => {
    column.setFilterValue('')
  }

  const handleFilterByColumn = () => {
    setShowColumnFilters(true)
    setTimeout(() => filterInputRefs.current[`${column.id}-0`]?.focus(), 100)
  }

  const handleShowAllColumns = () => {
    toggleAllColumnsVisible(true)
  }

  const internalColumnMenuItems = (
    <>
      {enableSorting && column.getCanSort() && (
        <>
          {enableSortingRemoval !== false && (
            <Menu.Item
              disabled={!column.getIsSorted()}
              leftSection={<IconClearAll />}
              onClick={handleClearSort}
            >
              {localization.clearSort}
            </Menu.Item>
          )}
          <Menu.Item
            disabled={column.getIsSorted() === 'asc'}
            leftSection={<IconSortAscending />}
            onClick={handleSortAsc}
          >
            {localization.sortByColumnAsc?.replace(
              '{column}',
              String(columnDef.header),
            )}
          </Menu.Item>
          <Menu.Item
            disabled={column.getIsSorted() === 'desc'}
            leftSection={<IconSortDescending />}
            onClick={handleSortDesc}
          >
            {localization.sortByColumnDesc?.replace(
              '{column}',
              String(columnDef.header),
            )}
          </Menu.Item>
          {(enableColumnFilters || enableGrouping || enableHiding) && (
            <Menu.Divider key={3} />
          )}
        </>
      )}
      {enableColumnFilters &&
        columnFilterDisplayMode !== 'popover' &&
        column.getCanFilter() && (
          <>
            <Menu.Item
              disabled={!column.getFilterValue()}
              leftSection={<IconFilterOff />}
              onClick={handleClearFilter}
            >
              {localization.clearFilter}
            </Menu.Item>
            <Menu.Item
              leftSection={<IconFilter />}
              onClick={handleFilterByColumn}
            >
              {localization.filterByColumn?.replace(
                '{column}',
                String(columnDef.header),
              )}
            </Menu.Item>
            {(enableGrouping || enableHiding) && <Menu.Divider key={2} />}
          </>
        )}
      {enableGrouping && column.getCanGroup() && (
        <>
          <Menu.Item
            leftSection={<IconBoxMultiple />}
            onClick={handleGroupByColumn}
          >
            {localization[
              column.getIsGrouped() ? 'ungroupByColumn' : 'groupByColumn'
            ]?.replace('{column}', String(columnDef.header))}
          </Menu.Item>
          {enableColumnPinning && <Menu.Divider />}
        </>
      )}
      {enableColumnPinning && column.getCanPin() && (
        <>
          <Menu.Item
            disabled={column.getIsPinned() === 'start' || !column.getCanPin()}
            leftSection={<IconPinned className={classes.left} />}
            onClick={() => handlePinColumn('start')}
          >
            {localization.pinToLeft}
          </Menu.Item>
          <Menu.Item
            disabled={column.getIsPinned() === 'end' || !column.getCanPin()}
            leftSection={<IconPinned className={classes.right} />}
            onClick={() => handlePinColumn('end')}
          >
            {localization.pinToRight}
          </Menu.Item>
          <Menu.Item
            disabled={!column.getIsPinned()}
            leftSection={<IconPinnedOff />}
            onClick={() => handlePinColumn(false)}
          >
            {localization.unpin}
          </Menu.Item>
          {enableHiding && <Menu.Divider />}
        </>
      )}
      {enableColumnResizing && column.getCanResize() && (
        <Menu.Item
          disabled={!columnSizing[column.id]}
          key={0}
          leftSection={<IconArrowAutofitContent />}
          onClick={handleResetColumnSize}
        >
          {localization.resetColumnSize}
        </Menu.Item>
      )}
      {enableHiding && (
        <>
          <Menu.Item
            disabled={!column.getCanHide()}
            key={0}
            leftSection={<IconEyeOff />}
            onClick={handleHideColumn}
          >
            {localization.hideColumn?.replace(
              '{column}',
              String(columnDef.header),
            )}
          </Menu.Item>
          <Menu.Item
            disabled={
              !Object.values(columnVisibility).filter((visible) => !visible)
                .length
            }
            key={1}
            leftSection={<IconColumns />}
            onClick={handleShowAllColumns}
          >
            {localization.showAllColumns?.replace(
              '{column}',
              String(columnDef.header),
            )}
          </Menu.Item>
        </>
      )}
    </>
  )

  return (
    <Menu closeOnItemClick position="bottom-start" withinPortal {...rest}>
      <Tooltip
        label={actionIconProps?.title ?? localization.columnActions}
        openDelay={1000}
        withinPortal
      >
        <Menu.Target>
          <ActionIcon
            aria-label={localization.columnActions}
            color="gray"
            size="sm"
            variant="subtle"
            {...actionIconProps}
          >
            <IconDotsVertical size="100%" />
          </ActionIcon>
        </Menu.Target>
      </Tooltip>
      <Menu.Dropdown>
        {columnDef.renderColumnActionsMenuItems?.({
          column,
          internalColumnMenuItems,
          table,
        }) ??
          renderColumnActionsMenuItems?.({
            column,
            internalColumnMenuItems,
            table,
          }) ??
          internalColumnMenuItems}
      </Menu.Dropdown>
    </Menu>
  )
}

import { Fragment, useMemo } from 'react'

import { Menu } from '@mantine/core'

import classes from './MRT_FilterOptionMenu.module.css'
import type {
  MRT_FilterOption,
  MRT_Header,
  MRT_InternalFilterOption,
  MRT_Localization,
  MRT_RowData,
  MRT_TableInstance,
} from '../../types'

export const mrtFilterOptions = (
  localization: MRT_Localization,
): Array<MRT_InternalFilterOption> => [
  {
    divider: false,
    label: localization.filterFuzzy,
    option: 'fuzzy',
    symbol: '≈',
  },
  {
    divider: false,
    label: localization.filterContains,
    option: 'contains',
    symbol: '*',
  },
  {
    divider: false,
    label: localization.filterStartsWith,
    option: 'startsWith',
    symbol: 'a',
  },
  {
    divider: true,
    label: localization.filterEndsWith,
    option: 'endsWith',
    symbol: 'z',
  },
  {
    divider: false,
    label: localization.filterEquals,
    option: 'equals',
    symbol: '=',
  },
  {
    divider: true,
    label: localization.filterNotEquals,
    option: 'notEquals',
    symbol: '≠',
  },
  {
    divider: false,
    label: localization.filterBetween,
    option: 'between',
    symbol: '⇿',
  },
  {
    divider: true,
    label: localization.filterBetweenInclusive,
    option: 'betweenInclusive',
    symbol: '⬌',
  },
  {
    divider: false,
    label: localization.filterGreaterThan,
    option: 'greaterThan',
    symbol: '>',
  },
  {
    divider: false,
    label: localization.filterGreaterThanOrEqualTo,
    option: 'greaterThanOrEqualTo',
    symbol: '≥',
  },
  {
    divider: false,
    label: localization.filterLessThan,
    option: 'lessThan',
    symbol: '<',
  },
  {
    divider: true,
    label: localization.filterLessThanOrEqualTo,
    option: 'lessThanOrEqualTo',
    symbol: '≤',
  },
  {
    divider: false,
    label: localization.filterEmpty,
    option: 'empty',
    symbol: '∅',
  },
  {
    divider: false,
    label: localization.filterNotEmpty,
    option: 'notEmpty',
    symbol: '!∅',
  },
]

const rangeModes = ['between', 'betweenInclusive', 'inNumberRange']
const emptyModes = ['empty', 'notEmpty']
const arrModes = ['arrIncludesSome', 'arrIncludesAll', 'arrIncludes']
const rangeVariants = ['range-slider', 'date-range', 'range']

interface Props<TData extends MRT_RowData> {
  header?: MRT_Header<TData>
  onSelect?: () => void
  table: MRT_TableInstance<TData>
}

export const MRT_FilterOptionMenu = <TData extends MRT_RowData>({
  header,
  onSelect,
  table,
}: Props<TData>) => {
  const {
    state,
    options: {
      columnFilterModeOptions,
      globalFilterModeOptions,
      localization,
      renderColumnFilterModeMenuItems,
      renderGlobalFilterModeMenuItems,
    },
    setColumnFilterFns,
    setGlobalFilterFn,
  } = table
  const { globalFilterFn } = state
  const { column } = header ?? {}
  const { columnDef } = column ?? {}
  const currentFilterValue = column?.getFilterValue()

  let allowedColumnFilterOptions =
    columnDef?.columnFilterModeOptions ?? columnFilterModeOptions

  if (rangeVariants.includes(columnDef?.filterVariant as string)) {
    allowedColumnFilterOptions = [
      ...rangeModes,
      ...(allowedColumnFilterOptions ?? []),
    ].filter((option) => rangeModes.includes(option))
  }

  const internalFilterOptions = useMemo(() => {
    const filterOptions = mrtFilterOptions(localization).filter(
      (filterOption) =>
        columnDef
          ? allowedColumnFilterOptions === undefined ||
            allowedColumnFilterOptions?.includes(filterOption.option)
          : (!globalFilterModeOptions ||
              globalFilterModeOptions.includes(filterOption.option)) &&
            ['contains', 'fuzzy', 'startsWith'].includes(filterOption.option),
    )
    if (filterOptions[filterOptions.length - 1].divider) {
      filterOptions[filterOptions.length - 1].divider = false
    }
    return filterOptions
  }, [columnDef, globalFilterModeOptions])

  const handleSelectFilterMode = (option: MRT_FilterOption) => {
    const prevFilterMode = columnDef?._filterFn ?? ''
    if (!header || !column) {
      // global filter mode
      setGlobalFilterFn(option)
    } else if (option !== prevFilterMode) {
      // column filter mode
      setColumnFilterFns((prev: { [key: string]: any }) => ({
        ...prev,
        [header.id]: option,
      }))

      // reset filter value and/or perform new filter render
      if (emptyModes.includes(option)) {
        // will now be empty/notEmpty filter mode
        if (
          currentFilterValue !== ' ' &&
          !emptyModes.includes(prevFilterMode)
        ) {
          column.setFilterValue(' ')
        } else if (currentFilterValue) {
          column.setFilterValue(currentFilterValue) // perform new filter render
        }
      } else if (
        columnDef?.filterVariant === 'multi-select' ||
        arrModes.includes(option)
      ) {
        // will now be array filter mode
        if (
          currentFilterValue instanceof String ||
          (currentFilterValue as Array<any>)?.length
        ) {
          column.setFilterValue([])
        } else if (currentFilterValue) {
          column.setFilterValue(currentFilterValue) // perform new filter render
        }
      } else if (
        rangeVariants.includes(columnDef?.filterVariant as string) ||
        rangeModes.includes(option)
      ) {
        // will now be range filter mode
        if (
          !Array.isArray(currentFilterValue) ||
          (!currentFilterValue?.every((v) => v === '') &&
            !rangeModes.includes(prevFilterMode))
        ) {
          column.setFilterValue(['', ''])
        } else {
          column.setFilterValue(currentFilterValue) // perform new filter render
        }
      } else {
        // will now be single value filter mode
        if (Array.isArray(currentFilterValue)) {
          column.setFilterValue('')
        } else if (
          currentFilterValue === ' ' &&
          emptyModes.includes(prevFilterMode)
        ) {
          column.setFilterValue(undefined)
        } else {
          column.setFilterValue(currentFilterValue) // perform new filter render
        }
      }
    }
    onSelect?.()
  }

  const filterOption =
    !!header && columnDef ? columnDef._filterFn : globalFilterFn

  return (
    <Menu.Dropdown>
      {(header && column && columnDef
        ? (columnDef.renderColumnFilterModeMenuItems?.({
            column: column,
            internalFilterOptions,
            onSelectFilterMode: handleSelectFilterMode,
            table,
          }) ??
          renderColumnFilterModeMenuItems?.({
            column: column,
            internalFilterOptions,
            onSelectFilterMode: handleSelectFilterMode,
            table,
          }))
        : renderGlobalFilterModeMenuItems?.({
            internalFilterOptions,
            onSelectFilterMode: handleSelectFilterMode,
            table,
          })) ??
        internalFilterOptions.map(
          ({ divider, label, option, symbol }, index) => (
            <Fragment key={index}>
              <Menu.Item
                color={option === filterOption ? 'blue' : undefined}
                leftSection={<span className={classes.symbol}>{symbol}</span>}
                onClick={() => handleSelectFilterMode(option)}
                value={option}
              >
                {label}
              </Menu.Item>
              {divider && <Menu.Divider />}
            </Fragment>
          ),
        )}
    </Menu.Dropdown>
  )
}

import { ActionIcon, Menu, Tooltip } from '@mantine/core'
