import type {
  MRT_Column,
  MRT_ColumnDef,
  MRT_ColumnOrderState,
  MRT_DefinedColumnDef,
  MRT_DefinedTableOptions,
  MRT_FilterOption,
  MRT_RowData,
} from '../types'

export const getColumnId = <TData extends MRT_RowData>(
  columnDef: MRT_ColumnDef<TData>,
): string =>
  columnDef.id ?? columnDef.accessorKey?.toString?.() ?? columnDef.header

export const getAllLeafColumnDefs = <TData extends MRT_RowData>(
  columns: Array<MRT_ColumnDef<TData>>,
): Array<MRT_ColumnDef<TData>> => {
  const allLeafColumnDefs: Array<MRT_ColumnDef<TData>> = []
  const getLeafColumns = (cols: Array<MRT_ColumnDef<TData>>) => {
    cols.forEach((col) => {
      if (col.columns) {
        getLeafColumns(col.columns)
      } else {
        allLeafColumnDefs.push(col)
      }
    })
  }
  getLeafColumns(columns)
  return allLeafColumnDefs
}

export const prepareColumns = <TData extends MRT_RowData>({
  columnDefs,
  tableOptions,
}: {
  columnDefs: Array<MRT_ColumnDef<TData>>
  tableOptions: MRT_DefinedTableOptions<TData>
}): Array<MRT_DefinedColumnDef<TData>> => {
  const {
    defaultDisplayColumn,
    filterFns = {},
    sortFns = {},
    state: { columnFilterFns = {} } = {},
  } = tableOptions
  return columnDefs.map((columnDef) => {
    // assign columnId
    if (!columnDef.id) columnDef.id = getColumnId(columnDef)
    // assign columnDefType
    if (!columnDef.columnDefType) columnDef.columnDefType = 'data'
    if (columnDef.columns?.length) {
      columnDef.columnDefType = 'group'
      // recursively prepare columns if this is a group column
      columnDef.columns = prepareColumns({
        columnDefs: columnDef.columns,
        tableOptions,
      })
    } else if (columnDef.columnDefType === 'data') {
      // assign filterFns
      if (Object.keys(filterFns).includes(columnFilterFns[columnDef.id])) {
        columnDef.filterFn =
          filterFns[columnFilterFns[columnDef.id]] ?? filterFns.fuzzy
        ;(columnDef as MRT_DefinedColumnDef<TData>)._filterFn =
          columnFilterFns[columnDef.id]
      }

      // assign sortFns
      if (Object.keys(sortFns).includes(columnDef.sortFn as string)) {
        columnDef.sortFn = sortFns[columnDef.sortFn as string]
      }
    } else if (columnDef.columnDefType === 'display') {
      columnDef = {
        ...(defaultDisplayColumn as MRT_ColumnDef<TData>),
        ...columnDef,
      }
    }
    return columnDef
  }) as Array<MRT_DefinedColumnDef<TData>>
}

export const reorderColumn = <TData extends MRT_RowData>(
  draggedColumn: MRT_Column<TData>,
  targetColumn: MRT_Column<TData>,
  columnOrder: MRT_ColumnOrderState,
): MRT_ColumnOrderState => {
  if (draggedColumn.getCanPin()) {
    draggedColumn.pin(targetColumn.getIsPinned())
  }
  const newColumnOrder = [...columnOrder]
  newColumnOrder.splice(
    newColumnOrder.indexOf(targetColumn.id),
    0,
    newColumnOrder.splice(newColumnOrder.indexOf(draggedColumn.id), 1)[0],
  )
  return newColumnOrder
}

export const getDefaultColumnFilterFn = <TData extends MRT_RowData>(
  columnDef: MRT_ColumnDef<TData>,
): MRT_FilterOption => {
  const { filterVariant } = columnDef
  if (filterVariant === 'multi-select') return 'arrIncludesSome'
  if (filterVariant?.includes('range')) return 'betweenInclusive'
  if (['checkbox', 'date', 'select'].includes(filterVariant || ''))
    return 'equals'
  return 'fuzzy'
}

import { getAllLeafColumnDefs, getColumnId } from './column.utils'
import type {
  MRT_ColumnDef,
  MRT_DefinedTableOptions,
  MRT_DisplayColumnIds,
  MRT_Localization,
  MRT_RowData,
  MRT_StatefulTableOptions,
} from '../types'

export function defaultDisplayColumnProps<TData extends MRT_RowData>({
  header,
  id,
  size,
  tableOptions,
}: {
  header?: keyof MRT_Localization
  id: MRT_DisplayColumnIds
  size: number
  tableOptions: MRT_DefinedTableOptions<TData>
}): MRT_ColumnDef<TData> {
  const { defaultDisplayColumn, displayColumnDefOptions, localization } =
    tableOptions
  return {
    ...defaultDisplayColumn,
    header: header ? localization[header] : '',
    size,
    ...displayColumnDefOptions?.[id],
    id,
  }
}

export const showRowPinningColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const { enableRowPinning, rowPinningDisplayMode } = tableOptions
  return !!(enableRowPinning && !rowPinningDisplayMode?.startsWith('select'))
}

export const showRowDragColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const { enableRowDragging, enableRowOrdering } = tableOptions
  return !!(enableRowDragging || enableRowOrdering)
}

export const showRowExpandColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const {
    enableExpanding,
    enableGrouping,
    renderDetailPanel,
    state: { grouping },
  } = tableOptions
  return !!(
    enableExpanding ||
    (enableGrouping && grouping?.length) ||
    renderDetailPanel
  )
}

export const showRowActionsColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const {
    createDisplayMode,
    editDisplayMode,
    enableEditing,
    enableRowActions,
    state: { creatingRow },
  } = tableOptions
  return !!(
    enableRowActions ||
    (creatingRow && createDisplayMode === 'row') ||
    (enableEditing && ['modal', 'row'].includes(editDisplayMode ?? ''))
  )
}

export const showRowSelectionColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => !!tableOptions.enableRowSelection

export const showRowNumbersColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => !!tableOptions.enableRowNumbers

export const showRowSpacerColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => tableOptions.layoutMode === 'grid-no-grow'

export const getLeadingDisplayColumnIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
) =>
  [
    showRowPinningColumn(tableOptions) && 'mrt-row-pin',
    showRowDragColumn(tableOptions) && 'mrt-row-drag',
    tableOptions.positionActionsColumn === 'first' &&
      showRowActionsColumn(tableOptions) &&
      'mrt-row-actions',
    tableOptions.positionExpandColumn === 'first' &&
      showRowExpandColumn(tableOptions) &&
      'mrt-row-expand',
    showRowSelectionColumn(tableOptions) && 'mrt-row-select',
    showRowNumbersColumn(tableOptions) && 'mrt-row-numbers',
  ].filter(Boolean) as Array<MRT_DisplayColumnIds>

export const getTrailingDisplayColumnIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
) =>
  [
    tableOptions.positionActionsColumn === 'last' &&
      showRowActionsColumn(tableOptions) &&
      'mrt-row-actions',
    tableOptions.positionExpandColumn === 'last' &&
      showRowExpandColumn(tableOptions) &&
      'mrt-row-expand',
    showRowSpacerColumn(tableOptions) && 'mrt-row-spacer',
  ].filter(Boolean) as Array<MRT_DisplayColumnIds>

export const getDefaultColumnOrderIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
  reset = false,
) => {
  const {
    state: { columnOrder: currentColumnOrderIds = [] },
  } = tableOptions

  const leadingDisplayColIds: Array<string> =
    getLeadingDisplayColumnIds(tableOptions)
  const trailingDisplayColIds: Array<string> =
    getTrailingDisplayColumnIds(tableOptions)

  const defaultColumnDefIds = getAllLeafColumnDefs(tableOptions.columns).map(
    (columnDef) => getColumnId(columnDef),
  )

  let allLeafColumnDefIds = reset
    ? defaultColumnDefIds
    : Array.from(new Set([...currentColumnOrderIds, ...defaultColumnDefIds]))

  allLeafColumnDefIds = allLeafColumnDefIds.filter(
    (colId) =>
      !leadingDisplayColIds.includes(colId) &&
      !trailingDisplayColIds.includes(colId),
  )

  return [
    ...leadingDisplayColIds,
    ...allLeafColumnDefIds,
    ...trailingDisplayColIds,
  ]
}

import { rankGlobalFuzzy } from '../fns/sortingFns'
import { parseFromValuesOrFunc } from './utils'
import type { ChangeEvent, MouseEvent } from 'react'

import type { MRT_Row, MRT_RowData, MRT_TableInstance } from '../types'

export const getMRT_Rows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
  all?: boolean,
): Array<MRT_Row<TData>> => {
  const {
    getCenterRows,
    getPrePaginatedRowModel,
    getRowModel,
    state,
    getTopRows,
    options: {
      createDisplayMode,
      enablePagination,
      enableRowPinning,
      manualPagination,
      positionCreatingRow,
      rowPinningDisplayMode,
    },
  } = table
  const { creatingRow, pagination } = state

  const isRankingRows = getIsRankingRows(table)

  let rows: Array<MRT_Row<TData>> = []
  if (!isRankingRows) {
    rows =
      !enableRowPinning || rowPinningDisplayMode?.includes('sticky')
        ? all
          ? getPrePaginatedRowModel().rows
          : getRowModel().rows
        : getCenterRows()
  } else {
    // fuzzy ranking adjustments
    rows = getPrePaginatedRowModel().rows.sort((a, b) => rankGlobalFuzzy(a, b))
    if (enablePagination && !manualPagination && !all) {
      const start = pagination.pageIndex * pagination.pageSize
      rows = rows.slice(start, start + pagination.pageSize)
    }
    if (enableRowPinning && !rowPinningDisplayMode?.includes('sticky')) {
      // "re-center-ize" the rows (no top or bottom pinned rows unless sticky)
      rows = rows.filter((row) => !row.getIsPinned())
    }
  }
  // row pinning adjustments
  if (enableRowPinning && rowPinningDisplayMode?.includes('sticky')) {
    const centerPinnedRowIds = rows
      .filter((row) => row.getIsPinned())
      .map((r) => r.id)

    rows = [
      ...getTopRows().filter((row) => !centerPinnedRowIds.includes(row.id)),
      ...rows,
    ]
  }
  // blank inserted creating row adjustments
  if (
    positionCreatingRow !== undefined &&
    creatingRow &&
    createDisplayMode === 'row'
  ) {
    const creatingRowIndex = !isNaN(+positionCreatingRow)
      ? +positionCreatingRow
      : positionCreatingRow === 'top'
        ? 0
        : rows.length
    rows = [
      ...rows.slice(0, creatingRowIndex),
      creatingRow,
      ...rows.slice(creatingRowIndex),
    ]
  }

  return rows
}

export const getCanRankRows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
) => {
  const {
    state,
    options: {
      enableGlobalFilterRankedResults,
      manualExpanding,
      manualFiltering,
      manualGrouping,
      manualSorting,
    },
  } = table
  const { expanded, globalFilterFn } = state

  return (
    !manualExpanding &&
    !manualFiltering &&
    !manualGrouping &&
    !manualSorting &&
    enableGlobalFilterRankedResults &&
    globalFilterFn === 'fuzzy' &&
    expanded !== true &&
    !Object.values(expanded).some(Boolean)
  )
}

export const getIsRankingRows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
) => {
  const { globalFilter, sorting } = table.state

  return (
    getCanRankRows(table) &&
    globalFilter &&
    !Object.values(sorting).some(Boolean)
  )
}

export const getIsRowSelected = <TData extends MRT_RowData>({
  row,
  table,
}: {
  row: MRT_Row<TData>
  table: MRT_TableInstance<TData>
}) => {
  const {
    options: { enableRowSelection },
  } = table

  return (
    row.getIsSelected() ||
    (parseFromValuesOrFunc(enableRowSelection, row) &&
      row.getCanSelectSubRows() &&
      row.getIsAllSubRowsSelected())
  )
}

export const getMRT_RowSelectionHandler =
  <TData extends MRT_RowData>({
    renderedRowIndex = 0,
    row,
    table,
  }: {
    renderedRowIndex?: number
    row: MRT_Row<TData>
    table: MRT_TableInstance<TData>
  }) =>
  (
    event: ChangeEvent<HTMLInputElement> | MouseEvent<HTMLTableRowElement>,
    value?: boolean,
  ) => {
    const {
      state,
      options: {
        enableBatchRowSelection,
        enableMultiRowSelection,
        enableRowPinning,
        manualPagination,
        rowPinningDisplayMode,
      },
      refs: { lastSelectedRowId: lastSelectedRowId },
    } = table
    const {
      pagination: { pageIndex, pageSize },
    } = state

    const paginationOffset = manualPagination ? 0 : pageSize * pageIndex

    const wasCurrentRowChecked = getIsRowSelected({ row, table })

    // toggle selection of this row
    row.toggleSelected(value ?? !wasCurrentRowChecked)

    const changedRowIds = new Set<string>([row.id])

    // if shift key is pressed, select all rows between last selected and this one
    if (
      enableBatchRowSelection &&
      enableMultiRowSelection &&
      (event as any).nativeEvent.shiftKey &&
      lastSelectedRowId.current !== null
    ) {
      const rows = getMRT_Rows(table, true)

      const lastIndex = rows.findIndex(
        (r) => r.id === lastSelectedRowId.current,
      )

      if (lastIndex !== -1) {
        const isLastIndexChecked = getIsRowSelected({
          row: rows?.[lastIndex],
          table,
        })

        const currentIndex = renderedRowIndex + paginationOffset
        const [start, end] =
          lastIndex < currentIndex
            ? [lastIndex, currentIndex]
            : [currentIndex, lastIndex]

        // toggle selection of all rows between last selected and this one
        // but only if the last selected row is not the same as the current one
        if (wasCurrentRowChecked !== isLastIndexChecked) {
          for (let i = start; i <= end; i++) {
            rows[i].toggleSelected(!wasCurrentRowChecked)
            changedRowIds.add(rows[i].id)
          }
        }
      }
    }

    // record the last selected row id
    lastSelectedRowId.current = row.id

    // if all sub rows were selected, unselect them
    if (row.getCanSelectSubRows() && row.getIsAllSubRowsSelected()) {
      row.subRows?.forEach((r) => r.toggleSelected(false))
    }

    if (enableRowPinning && rowPinningDisplayMode?.includes('select')) {
      changedRowIds.forEach((rowId) => {
        const rowToTogglePin = table.getRow(rowId)
        rowToTogglePin.pin(
          !wasCurrentRowChecked // was not previously pinned or selected
            ? rowPinningDisplayMode?.includes('bottom')
              ? 'bottom'
              : 'top'
            : false,
        )
      })
    }
  }

export const getMRT_SelectAllHandler =
  <TData extends MRT_RowData>({ table }: { table: MRT_TableInstance<TData> }) =>
  (
    event: ChangeEvent<HTMLInputElement> | MouseEvent<HTMLButtonElement>,
    value?: boolean,
    forceAll?: boolean,
  ) => {
    const {
      options: { enableRowPinning, rowPinningDisplayMode, selectAllMode },
      refs: { lastSelectedRowId },
    } = table

    if (selectAllMode === 'all' || forceAll) {
      table.toggleAllRowsSelected(value ?? (event as any).target.checked)
    } else {
      table.toggleAllPageRowsSelected(value ?? (event as any).target.checked)
    }
    if (enableRowPinning && rowPinningDisplayMode?.includes('select')) {
      table.setRowPinning({ bottom: [], top: [] })
    }
    lastSelectedRowId.current = null
  }

import type { MantineTheme } from '@mantine/core'

import type { MantineShade } from '../types'

export const parseCSSVarId = (id: string) => id.replace(/[^a-zA-Z0-9]/g, '_')

export const getPrimaryShade = (theme: MantineTheme): number =>
  typeof theme.primaryShade === 'number'
    ? theme.primaryShade
    : (theme.primaryShade?.dark ?? 7)

export const getPrimaryColor = (
  theme: MantineTheme,
  shade?: MantineShade,
): string => theme.colors[theme.primaryColor][shade ?? getPrimaryShade(theme)]

export function dataVariable(
  name: string,
  value: boolean | number | string | undefined,
) {
  const key = `data-${name}`
  switch (typeof value) {
    case 'boolean':
      return value ? { [key]: '' } : null
    case 'number':
      return { [key]: `${value}` }
    case 'string':
      return { [key]: value }
    default:
      return null
  }
}

export const parseFromValuesOrFunc = <T, U>(
  fn: ((arg: U) => T) | T | undefined,
  arg: U,
): T | undefined => (fn instanceof Function ? fn(arg) : fn)

import { defaultRangeExtractor } from '@tanstack/react-virtual'
import type { Range } from '@tanstack/react-virtual'

export const extraIndexRangeExtractor = (
  range: Range,
  draggingIndex?: number,
) => {
  const newIndexes = defaultRangeExtractor(range)
  if (draggingIndex === undefined) return newIndexes
  if (
    draggingIndex >= 0 &&
    draggingIndex < Math.max(range.startIndex - range.overscan, 0)
  ) {
    newIndexes.unshift(draggingIndex)
  }
  if (draggingIndex >= 0 && draggingIndex > range.endIndex + range.overscan) {
    newIndexes.push(draggingIndex)
  }
  return newIndexes
}

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return { errors, server }
}

async function getFirstEmailText(page: Page) {
  const text = await page.getByText(/@/).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    await expect(
      page.getByRole('heading', { name: /Mantine React Table/i }),
    ).toBeVisible()
    await expect(page.getByText('First Name').first()).toBeVisible()
    await expect(page.getByText('Last Name').first()).toBeVisible()
    await expect(page.getByText('Email').first()).toBeVisible()
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('regenerates table data', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const regenerateButton = page.getByRole('button', {
      name: /^Regenerate Data$/i,
    })

    await expect(regenerateButton).toBeVisible()

    const firstEmailBefore = await getFirstEmailText(page)

    await regenerateButton.click()

    await expect.poll(() => getFirstEmailText(page)).not.toBe(firstEmailBefore)
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('paginates without resetting to the first page', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const firstEmailBefore = await getFirstEmailText(page)

    await page.getByRole('button', { name: /go to next page/i }).click()

    await expect(page.getByText('11-20 of 50')).toBeVisible()
    await expect.poll(() => getFirstEmailText(page)).not.toBe(firstEmailBefore)
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('updates the sort direction indicator', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const firstNameHeader = page
      .locator('thead th')
      .filter({ hasText: 'First Name' })
    const sortTarget = firstNameHeader.locator('.mrt-table-head-cell-labels')
    const sortLabel = firstNameHeader.locator('.mrt-table-head-sort-button')

    await sortTarget.click()
    await expect(sortLabel).toHaveAttribute('data-sorted', 'asc')
    await expect(sortLabel).toHaveAttribute(
      'aria-label',
      'Sorted by First Name ascending',
    )

    await sortTarget.click()
    await expect(sortLabel).toHaveAttribute('data-sorted', 'desc')
    await expect(sortLabel).toHaveAttribute(
      'aria-label',
      'Sorted by First Name descending',
    )
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('opens the edit row modal without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    await page.getByRole('button', { name: 'Row Actions' }).first().click()
    await page.getByRole('menuitem', { name: 'Edit', exact: true }).click()

    await expect(page.getByRole('dialog')).toBeVisible()
    await expect(
      page.getByRole('textbox', { name: 'First Name' }),
    ).toBeVisible()
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('groups and ungroups a column without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const openFirstNameColumnMenu = async () => {
      await page
        .locator('thead th')
        .filter({ hasText: 'First Name' })
        .getByRole('button', { name: 'Column Actions' })
        .click()
    }

    await openFirstNameColumnMenu()
    await page.getByRole('menuitem', { name: 'Group by First Name' }).click()
    await expect(page.getByRole('button', { name: 'Expand all' })).toBeVisible()

    await openFirstNameColumnMenu()
    await page.getByRole('menuitem', { name: 'Ungroup by First Name' }).click()
    await expect(page.getByRole('button', { name: 'Expand all' })).toHaveCount(
      0,
    )
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

import * as React from 'react'
import ReactDOM from 'react-dom/client'
import {
  Box,
  Button,
  CssBaseline,
  Stack,
  ThemeProvider,
  Typography,
  createTheme,
} from '@mui/material'
import {
  MaterialReactTable,
  createMRTColumnHelper,
  useMaterialReactTable,
} from './material-react-table'
import { makeData } from './makeData'
import type { Person } from './makeData'
import type { MRT_ColumnDef } from './material-react-table'
import './index.css'

const columnHelper = createMRTColumnHelper<Person>()

const columns = columnHelper.columns([
  columnHelper.accessor('firstName', {
    header: 'First Name',
    size: 140,
  }),
  columnHelper.accessor('lastName', {
    header: 'Last Name',
    size: 140,
  }),
  columnHelper.accessor('email', {
    header: 'Email',
    size: 220,
    Cell: ({ cell }) => (
      <a href={`mailto:${cell.getValue<string>()}`}>
        {cell.getValue<string>()}
      </a>
    ),
  }),
  columnHelper.accessor('age', {
    header: 'Age',
    size: 80,
    filterVariant: 'range',
  }),
  columnHelper.accessor('jobTitle', {
    header: 'Job Title',
    size: 200,
  }),
  columnHelper.accessor('city', {
    header: 'City',
    size: 140,
  }),
  columnHelper.accessor('state', {
    header: 'State',
    size: 80,
    filterVariant: 'select',
  }),
  columnHelper.accessor('salary', {
    header: 'Salary',
    size: 130,
    filterVariant: 'range',
    Cell: ({ cell }) =>
      cell.getValue<number>().toLocaleString('en-US', {
        style: 'currency',
        currency: 'USD',
        maximumFractionDigits: 0,
      }),
    aggregationFn: ['mean', 'min'],
    AggregatedCell: ({ cell }) => {
      const value = cell.getValue<{ mean: number; min: number }>()
      const format = (amount: number) =>
        amount.toLocaleString('en-US', {
          style: 'currency',
          currency: 'USD',
          maximumFractionDigits: 0,
        })
      return (
        <Box component="span" sx={{ fontStyle: 'italic' }}>
          Avg: {format(value.mean)} · Min: {format(value.min)}
        </Box>
      )
    },
  }),
  columnHelper.accessor('status', {
    header: 'Status',
    size: 110,
    filterVariant: 'select',
    Cell: ({ cell }) => {
      const value = cell.getValue<Person['status']>()
      const color =
        value === 'active'
          ? 'success.main'
          : value === 'inactive'
            ? 'text.disabled'
            : 'warning.main'
      return (
        <Box component="span" sx={{ color, textTransform: 'capitalize' }}>
          {value}
        </Box>
      )
    },
  }),
])

const theme = createTheme({
  colorSchemes: {
    light: true,
    dark: true,
  },
})

function App() {
  const [data, setData] = React.useState(() => makeData(50))

  const table = useMaterialReactTable<Person>({
    columns: columns as Array<MRT_ColumnDef<Person>>,
    data,
    enableColumnFilters: true,
    enableColumnOrdering: true,
    enableColumnPinning: true,
    enableColumnResizing: true,
    enableExpanding: false,
    enableFacetedValues: true,
    enableGlobalFilter: true,
    enableGrouping: true,
    enablePagination: true,
    enableRowActions: true,
    enableRowSelection: true,
    enableEditing: true,
    editDisplayMode: 'modal',
    createDisplayMode: 'modal',
    initialState: {
      pagination: { pageIndex: 0, pageSize: 10 },
    },
    positionToolbarAlertBanner: 'bottom',
    renderRowActionMenuItems: ({ closeMenu }) => [
      <Box
        key="view"
        onClick={closeMenu}
        sx={{ p: '6px 16px', cursor: 'pointer' }}
      >
        View Profile
      </Box>,
      <Box
        key="custom-edit"
        onClick={closeMenu}
        sx={{ p: '6px 16px', cursor: 'pointer' }}
      >
        Edit
      </Box>,
    ],
    renderTopToolbarCustomActions: () => (
      <Stack direction="row" spacing={1}>
        <Button variant="outlined" onClick={() => setData(makeData(50))}>
          Regenerate Data
        </Button>
        <Button variant="outlined" onClick={() => setData(makeData(1_000))}>
          1k rows
        </Button>
      </Stack>
    ),
  })

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ mb: 1 }}>
        Material React Table
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        TanStack Table v9 + Material UI v9 — full feature set
      </Typography>
      <MaterialReactTable table={table} />
    </Box>
  )
}

const rootElement = document.getElementById('root')
if (!rootElement) throw new Error('Failed to find the root element')

ReactDOM.createRoot(rootElement).render(
  <React.StrictMode>
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <App />
    </ThemeProvider>
  </React.StrictMode>,
)

import { useMaterialReactTable } from '../hooks/useMaterialReactTable'
import { MRT_TablePaper } from './table/MRT_TablePaper'
import type {
  MRT_RowData,
  MRT_TableInstance,
  MRT_TableOptions,
  Xor,
} from '../types'

type TableInstanceProp<TData extends MRT_RowData> = {
  table: MRT_TableInstance<TData>
}

export type MaterialReactTableProps<TData extends MRT_RowData> = Xor<
  TableInstanceProp<TData>,
  MRT_TableOptions<TData>
>

const isTableInstanceProp = <TData extends MRT_RowData>(
  props: MaterialReactTableProps<TData>,
): props is TableInstanceProp<TData> =>
  (props as TableInstanceProp<TData>).table !== undefined

export const MaterialReactTable = <TData extends MRT_RowData>(
  props: MaterialReactTableProps<TData>,
) => {
  let table: MRT_TableInstance<TData>

  if (isTableInstanceProp(props)) {
    table = props.table
  } else {
    table = useMaterialReactTable(props)
  }

  // `AppTable` (attached by `useAppTable`) provides the table via React context
  // so MRT components can read it with `useTableContext()` instead of a prop.
  const AppTable = (table as any).AppTable as React.FC<{
    children: React.ReactNode
  }>

  return (
    <AppTable>
      <MRT_TablePaper />
    </AppTable>
  )
}

import { memo, useMemo } from 'react'
import TableBody from '@mui/material/TableBody'
import Typography from '@mui/material/Typography'
import { useMRT_RowVirtualizer } from '../../hooks/useMRT_RowVirtualizer'
import { useMRT_Rows } from '../../hooks/useMRT_Rows'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableBodyRow, Memo_MRT_TableBodyRow } from './MRT_TableBodyRow'
import type { MRT_ColumnVirtualizer, MRT_Row, MRT_RowData } from '../../types'
import type { TableBodyProps } from '@mui/material/TableBody'
import type { VirtualItem } from '@tanstack/react-virtual'

export interface MRT_TableBodyProps extends TableBodyProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
}

export const MRT_TableBody = <TData extends MRT_RowData = MRT_RowData>({
  columnVirtualizer,
  ...rest
}: MRT_TableBodyProps) => {
  const table = useMRTContext<TData>()
  const {
    getBottomRows,
    getIsSomeRowsPinned,
    getRowModel,
    state,
    getTopRows,
    options: {
      enableStickyFooter,
      enableStickyHeader,
      layoutMode,
      localization,
      memoMode,
      muiTableBodyProps,
      renderDetailPanel,
      renderEmptyRowsFallback,
      rowPinningDisplayMode,
    },
    refs: { tableFooterRef, tableHeadRef, tablePaperRef },
  } = table
  const { columnFilters, globalFilter, isFullScreen, rowPinning } = state

  const tableBodyProps = {
    ...parseFromValuesOrFunc(muiTableBodyProps, { table }),
    ...rest,
  }

  const tableHeadHeight =
    ((enableStickyHeader || isFullScreen) &&
      tableHeadRef.current?.clientHeight) ||
    0
  const tableFooterHeight =
    (enableStickyFooter && tableFooterRef.current?.clientHeight) || 0

  const pinnedRowIds = useMemo(() => {
    if (!rowPinning.bottom?.length && !rowPinning.top?.length) return []
    return getRowModel()
      .rows.filter((row) => row.getIsPinned())
      .map((r) => r.id)
  }, [rowPinning, getRowModel().rows])

  const rows = useMRT_Rows(table)

  const rowVirtualizer = useMRT_RowVirtualizer(table, rows)

  const { virtualRows } = rowVirtualizer ?? {}

  const commonRowProps = {
    columnVirtualizer,
    numRows: rows.length,
  }

  return (
    <>
      {!rowPinningDisplayMode?.includes('sticky') &&
        getIsSomeRowsPinned('top') && (
          <TableBody
            {...tableBodyProps}
            sx={(theme) => ({
              display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
              position: 'sticky',
              top: tableHeadHeight - 1,
              zIndex: 1,
              ...(parseFromValuesOrFunc(tableBodyProps?.sx, theme) as any),
            })}
          >
            {getTopRows().map((row, staticRowIndex) => {
              const props = {
                ...commonRowProps,
                row,
                staticRowIndex,
              }
              return memoMode === 'rows' ? (
                <Memo_MRT_TableBodyRow key={row.id} {...props} />
              ) : (
                <MRT_TableBodyRow key={row.id} {...props} />
              )
            })}
          </TableBody>
        )}
      <TableBody
        {...tableBodyProps}
        sx={(theme) => ({
          display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
          height: rowVirtualizer
            ? `${rowVirtualizer.getTotalSize()}px`
            : undefined,
          minHeight: !rows.length ? '100px' : undefined,
          position: 'relative',
          ...(parseFromValuesOrFunc(tableBodyProps?.sx, theme) as any),
        })}
      >
        {tableBodyProps?.children ??
          (!rows.length ? (
            <tr
              style={{
                display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
              }}
            >
              <td
                colSpan={table.getVisibleLeafColumns().length}
                style={{
                  display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
                }}
              >
                {renderEmptyRowsFallback?.({ table }) ?? (
                  <Typography
                    sx={{
                      color: 'text.secondary',
                      fontStyle: 'italic',
                      maxWidth: `min(100vw, ${
                        tablePaperRef.current?.clientWidth
                          ? tablePaperRef.current?.clientWidth + 'px'
                          : '100%'
                      })`,
                      py: '2rem',
                      textAlign: 'center',
                      width: '100%',
                    }}
                  >
                    {globalFilter || columnFilters.length
                      ? localization.noResultsFound
                      : localization.noRecordsToDisplay}
                  </Typography>
                )}
              </td>
            </tr>
          ) : (
            <>
              {(virtualRows ?? rows).map((rowOrVirtualRow, staticRowIndex) => {
                let row = rowOrVirtualRow as MRT_Row<TData>
                if (rowVirtualizer) {
                  if (renderDetailPanel) {
                    if (rowOrVirtualRow.index % 2 === 1) {
                      return null
                    } else {
                      staticRowIndex = rowOrVirtualRow.index / 2
                    }
                  } else {
                    staticRowIndex = rowOrVirtualRow.index
                  }
                  row = rows[staticRowIndex]
                }
                const props = {
                  ...commonRowProps,
                  pinnedRowIds,
                  row,
                  rowVirtualizer,
                  staticRowIndex,
                  virtualRow: rowVirtualizer
                    ? (rowOrVirtualRow as VirtualItem)
                    : undefined,
                }
                const key = `${row.id}-${row.index}`
                return memoMode === 'rows' ? (
                  <Memo_MRT_TableBodyRow key={key} {...props} />
                ) : (
                  <MRT_TableBodyRow key={key} {...props} />
                )
              })}
            </>
          ))}
      </TableBody>
      {!rowPinningDisplayMode?.includes('sticky') &&
        getIsSomeRowsPinned('bottom') && (
          <TableBody
            {...tableBodyProps}
            sx={(theme) => ({
              bottom: tableFooterHeight - 1,
              display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
              position: 'sticky',
              zIndex: 1,
              ...(parseFromValuesOrFunc(tableBodyProps?.sx, theme) as any),
            })}
          >
            {getBottomRows().map((row, staticRowIndex) => {
              const props = {
                ...commonRowProps,
                row,
                staticRowIndex,
              }
              return memoMode === 'rows' ? (
                <Memo_MRT_TableBodyRow key={row.id} {...props} />
              ) : (
                <MRT_TableBodyRow key={row.id} {...props} />
              )
            })}
          </TableBody>
        )}
    </>
  )
}

export const Memo_MRT_TableBody = memo(MRT_TableBody) as typeof MRT_TableBody

import Box from '@mui/material/Box'
import highlightWords from 'highlight-words'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { ReactNode, RefObject } from 'react'
import type { MRT_Cell, MRT_RowData } from '../../types'

const allowedTypes = ['string', 'number']

export interface MRT_TableBodyCellValueProps<TData extends MRT_RowData> {
  cell: MRT_Cell<TData>
  rowRef?: RefObject<HTMLTableRowElement | null>
  staticColumnIndex?: number
  staticRowIndex?: number
}

export const MRT_TableBodyCellValue = <TData extends MRT_RowData>({
  cell,
  rowRef,
  staticColumnIndex,
  staticRowIndex,
}: MRT_TableBodyCellValueProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: {
      enableFilterMatchHighlighting,
      mrtTheme: { matchHighlightColor },
    },
  } = table
  const { column, row } = cell
  const { columnDef } = column
  const { globalFilter, globalFilterFn } = state
  const filterValue = column.getFilterValue()

  let renderedCellValue =
    cell.getIsAggregated() && columnDef.AggregatedCell
      ? columnDef.AggregatedCell({
          cell,
          column,
          row,
          table,
          staticColumnIndex,
          staticRowIndex,
        })
      : row.getIsGrouped() && !cell.getIsGrouped()
        ? null
        : cell.getIsGrouped() && columnDef.GroupedCell
          ? columnDef.GroupedCell({
              cell,
              column,
              row,
              table,
              staticColumnIndex,
              staticRowIndex,
            })
          : undefined

  const isGroupedValue = renderedCellValue !== undefined

  if (!isGroupedValue) {
    renderedCellValue = cell.renderValue() as ReactNode | number | string
  }

  if (
    enableFilterMatchHighlighting &&
    columnDef.enableFilterMatchHighlighting !== false &&
    String(renderedCellValue) &&
    allowedTypes.includes(typeof renderedCellValue) &&
    ((filterValue &&
      allowedTypes.includes(typeof filterValue) &&
      ['autocomplete', 'text'].includes(columnDef.filterVariant!)) ||
      (globalFilter &&
        allowedTypes.includes(typeof globalFilter) &&
        column.getCanGlobalFilter()))
  ) {
    const chunks = highlightWords?.({
      matchExactly:
        (filterValue ? columnDef._filterFn : globalFilterFn) !== 'fuzzy',
      query: (filterValue ?? globalFilter ?? '').toString(),
      text: renderedCellValue?.toString() as string,
    })
    if (chunks?.length > 1 || chunks?.[0]?.match) {
      renderedCellValue = (
        <span aria-label={renderedCellValue as string} role="note">
          {chunks?.map(({ key, match, text }) => (
            <Box
              aria-hidden="true"
              component="span"
              key={key}
              sx={
                match
                  ? {
                      backgroundColor: matchHighlightColor,
                      borderRadius: '2px',
                      color: (theme) =>
                        theme.palette.mode === 'dark'
                          ? theme.palette.common.white
                          : theme.palette.common.black,
                      padding: '2px 1px',
                    }
                  : undefined
              }
            >
              {text}
            </Box>
          )) ?? renderedCellValue}
        </span>
      )
    }
  }

  if (columnDef.Cell && !isGroupedValue) {
    renderedCellValue = columnDef.Cell({
      cell,
      column,
      renderedCellValue,
      row,
      rowRef,
      staticColumnIndex,
      staticRowIndex,
      table,
    })
  }

  return renderedCellValue
}

import { memo, useMemo, useRef } from 'react'
import TableRow from '@mui/material/TableRow'
import { alpha, darken, lighten, useTheme } from '@mui/material/styles'
import { getIsRowSelected } from '../../utils/row.utils'
import {
  commonCellBeforeAfterStyles,
  getCommonPinnedCellStyles,
} from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableDetailPanel } from './MRT_TableDetailPanel'
import { MRT_TableBodyCell, Memo_MRT_TableBodyCell } from './MRT_TableBodyCell'
import type {
  MRT_Cell,
  MRT_ColumnVirtualizer,
  MRT_Row,
  MRT_RowData,
  MRT_RowVirtualizer,
  MRT_VirtualItem,
} from '../../types'
import type { Theme } from '@mui/material/styles'
import type { TableRowProps } from '@mui/material/TableRow'
import type { VirtualItem } from '@tanstack/react-virtual'
import type { DragEvent } from 'react'

export interface MRT_TableBodyRowProps<
  TData extends MRT_RowData,
> extends TableRowProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  numRows?: number
  pinnedRowIds?: Array<string>
  row: MRT_Row<TData>
  rowVirtualizer?: MRT_RowVirtualizer
  staticRowIndex: number
  virtualRow?: VirtualItem
}

export const MRT_TableBodyRow = <TData extends MRT_RowData>({
  columnVirtualizer,
  numRows,
  pinnedRowIds,
  row,
  rowVirtualizer,
  staticRowIndex,
  virtualRow,
  ...rest
}: MRT_TableBodyRowProps<TData>) => {
  const table = useMRTContext<TData>()
  const theme = useTheme()

  const {
    state,
    options: {
      enableRowOrdering,
      enableRowPinning,
      enableStickyFooter,
      enableStickyHeader,
      layoutMode,
      memoMode,
      mrtTheme: {
        baseBackgroundColor,
        pinnedRowBackgroundColor,
        selectedRowBackgroundColor,
      },
      muiTableBodyRowProps,
      renderDetailPanel,
      rowPinningDisplayMode,
    },
    refs: { tableFooterRef, tableHeadRef },
    setHoveredRow,
  } = table
  const {
    density,
    draggingColumn,
    draggingRow,
    editingCell,
    editingRow,
    hoveredRow,
    isFullScreen,
    rowPinning,
  } = state

  const visibleCells = row.getVisibleCells()

  const { virtualColumns, virtualPaddingLeft, virtualPaddingRight } =
    columnVirtualizer ?? {}

  const isRowSelected = getIsRowSelected({ row, table })
  const isRowPinned = enableRowPinning && row.getIsPinned()
  const isDraggingRow = draggingRow?.id === row.id
  const isHoveredRow = hoveredRow?.id === row.id

  const tableRowProps = {
    ...parseFromValuesOrFunc(muiTableBodyRowProps, {
      row,
      staticRowIndex,
      table,
    }),
    ...rest,
  }

  const [bottomPinnedIndex, topPinnedIndex] = useMemo(() => {
    if (
      !enableRowPinning ||
      !rowPinningDisplayMode?.includes('sticky') ||
      !pinnedRowIds ||
      !row.getIsPinned()
    )
      return []
    return [
      [...pinnedRowIds].reverse().indexOf(row.id),
      pinnedRowIds.indexOf(row.id),
    ]
  }, [pinnedRowIds, rowPinning])

  const tableHeadHeight =
    ((enableStickyHeader || isFullScreen) &&
      tableHeadRef.current?.clientHeight) ||
    0
  const tableFooterHeight =
    (enableStickyFooter && tableFooterRef.current?.clientHeight) || 0

  const sx = parseFromValuesOrFunc(tableRowProps?.sx, theme as any)

  const defaultRowHeight =
    density === 'compact' ? 37 : density === 'comfortable' ? 53 : 69

  const customRowHeight =
    // @ts-expect-error
    parseInt(tableRowProps?.style?.height ?? sx?.height, 10) || undefined

  const rowHeight = customRowHeight || defaultRowHeight

  const handleDragEnter = (_e: DragEvent) => {
    if (enableRowOrdering && draggingRow) {
      setHoveredRow(row)
    }
  }

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault()
  }

  const rowRef = useRef<HTMLTableRowElement | null>(null)

  const cellHighlightColor = isRowSelected
    ? selectedRowBackgroundColor
    : isRowPinned
      ? pinnedRowBackgroundColor
      : undefined

  const cellHighlightColorHover =
    tableRowProps?.hover !== false
      ? isRowSelected
        ? cellHighlightColor
        : theme.palette.mode === 'dark'
          ? `${lighten(baseBackgroundColor, 0.3)}`
          : `${darken(baseBackgroundColor, 0.3)}`
      : undefined

  return (
    <>
      <TableRow
        data-index={renderDetailPanel ? staticRowIndex * 2 : staticRowIndex}
        data-pinned={!!isRowPinned || undefined}
        data-selected={isRowSelected || undefined}
        onDragEnter={handleDragEnter}
        onDragOver={handleDragOver}
        ref={(node: HTMLTableRowElement) => {
          if (node) {
            rowRef.current = node
            rowVirtualizer?.measureElement(node)
          }
        }}
        selected={isRowSelected}
        {...tableRowProps}
        style={{
          transform: virtualRow
            ? `translateY(${virtualRow.start}px)`
            : undefined,
          ...tableRowProps?.style,
        }}
        sx={(theme: Theme) => ({
          '&:hover td:after': cellHighlightColorHover
            ? {
                backgroundColor: alpha(cellHighlightColorHover, 0.3),
                ...commonCellBeforeAfterStyles,
              }
            : undefined,
          backgroundColor: `${baseBackgroundColor} !important`,
          bottom:
            !virtualRow && bottomPinnedIndex !== undefined && isRowPinned
              ? `${
                  bottomPinnedIndex * rowHeight +
                  (enableStickyFooter ? tableFooterHeight - 1 : 0)
                }px`
              : undefined,
          boxSizing: 'border-box',
          display: layoutMode?.startsWith('grid') ? 'flex' : undefined,
          opacity: isRowPinned ? 0.97 : isDraggingRow || isHoveredRow ? 0.5 : 1,
          position: virtualRow
            ? 'absolute'
            : rowPinningDisplayMode?.includes('sticky') && isRowPinned
              ? 'sticky'
              : 'relative',
          td: {
            ...getCommonPinnedCellStyles({ table, theme }),
          },
          'td:after': cellHighlightColor
            ? {
                backgroundColor: cellHighlightColor,
                ...commonCellBeforeAfterStyles,
              }
            : undefined,
          top: virtualRow
            ? 0
            : topPinnedIndex !== undefined && isRowPinned
              ? `${
                  topPinnedIndex * rowHeight +
                  (enableStickyHeader || isFullScreen ? tableHeadHeight - 1 : 0)
                }px`
              : undefined,
          transition: virtualRow ? 'none' : 'all 150ms ease-in-out',
          width: '100%',
          zIndex:
            rowPinningDisplayMode?.includes('sticky') && isRowPinned ? 2 : 0,
          ...(sx as any),
        })}
      >
        {virtualPaddingLeft ? (
          <td style={{ display: 'flex', width: virtualPaddingLeft }} />
        ) : null}
        {(virtualColumns ?? visibleCells).map(
          (cellOrVirtualCell, staticColumnIndex) => {
            let cell = cellOrVirtualCell as MRT_Cell<TData>
            if (columnVirtualizer) {
              staticColumnIndex = (cellOrVirtualCell as MRT_VirtualItem).index
              cell = visibleCells[staticColumnIndex]
            }
            const props = {
              cell,
              numRows,
              rowRef,
              staticColumnIndex,
              staticRowIndex,
            }
            const key = `${cell.id}-${staticRowIndex}`
            return cell ? (
              memoMode === 'cells' &&
              cell.column.columnDef.columnDefType === 'data' &&
              !draggingColumn &&
              !draggingRow &&
              editingCell?.id !== cell.id &&
              editingRow?.id !== row.id ? (
                <Memo_MRT_TableBodyCell key={key} {...props} />
              ) : (
                <MRT_TableBodyCell key={key} {...props} />
              )
            ) : null
          },
        )}
        {virtualPaddingRight ? (
          <td style={{ display: 'flex', width: virtualPaddingRight }} />
        ) : null}
      </TableRow>
      {renderDetailPanel && !row.getIsGrouped() && (
        <MRT_TableDetailPanel
          parentRowRef={rowRef}
          row={row}
          rowVirtualizer={rowVirtualizer}
          staticRowIndex={staticRowIndex}
          virtualRow={virtualRow}
        />
      )}
    </>
  )
}

export const Memo_MRT_TableBodyRow = memo(
  MRT_TableBodyRow,
  (prev, next) =>
    prev.row === next.row && prev.staticRowIndex === next.staticRowIndex,
) as typeof MRT_TableBodyRow

import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_GrabHandleButton } from '../buttons/MRT_GrabHandleButton'
import type { DragEvent, RefObject } from 'react'
import type { IconButtonProps } from '@mui/material/IconButton'
import type { MRT_Row, MRT_RowData } from '../../types'

export interface MRT_TableBodyRowGrabHandleProps<
  TData extends MRT_RowData,
> extends IconButtonProps {
  row: MRT_Row<TData>
  rowRef: RefObject<HTMLTableRowElement | null>
}

export const MRT_TableBodyRowGrabHandle = <TData extends MRT_RowData>({
  row,
  rowRef,
  ...rest
}: MRT_TableBodyRowGrabHandleProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: { muiRowDragHandleProps },
  } = table

  const iconButtonProps = {
    ...parseFromValuesOrFunc(muiRowDragHandleProps, {
      row,
      table,
    }),
    ...rest,
  }

  const handleDragStart = (event: DragEvent<HTMLButtonElement>) => {
    iconButtonProps?.onDragStart?.(event)
    try {
      event.dataTransfer.setDragImage(rowRef.current as HTMLElement, 0, 0)
    } catch (e) {
      console.error(e)
    }
    table.setDraggingRow(row)
  }

  const handleDragEnd = (event: DragEvent<HTMLButtonElement>) => {
    iconButtonProps?.onDragEnd?.(event)
    table.setDraggingRow(null)
    table.setHoveredRow(null)
  }

  return (
    <MRT_GrabHandleButton
      {...iconButtonProps}
      location="row"
      onDragEnd={handleDragEnd}
      onDragStart={handleDragStart}
    />
  )
}

import Box from '@mui/material/Box'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_RowPinButton } from '../buttons/MRT_RowPinButton'
import type { IconButtonProps } from '@mui/material/IconButton'
import type { MRT_Row, MRT_RowData } from '../../types'

export interface MRT_TableBodyRowPinButtonProps<
  TData extends MRT_RowData,
> extends IconButtonProps {
  row: MRT_Row<TData>
}

export const MRT_TableBodyRowPinButton = <TData extends MRT_RowData>({
  row,
  ...rest
}: MRT_TableBodyRowPinButtonProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { enableRowPinning, rowPinningDisplayMode },
  } = table
  const { density } = state

  const canPin = parseFromValuesOrFunc(enableRowPinning, row as any)

  if (!canPin) return null

  const rowPinButtonProps = {
    row,
    ...rest,
  }

  if (rowPinningDisplayMode === 'top-and-bottom' && !row.getIsPinned()) {
    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: density === 'compact' ? 'row' : 'column',
        }}
      >
        <MRT_RowPinButton pinningPosition="top" {...rowPinButtonProps} />
        <MRT_RowPinButton pinningPosition="bottom" {...rowPinButtonProps} />
      </Box>
    )
  }

  return (
    <MRT_RowPinButton
      pinningPosition={rowPinningDisplayMode === 'bottom' ? 'bottom' : 'top'}
      {...rowPinButtonProps}
    />
  )
}

import Collapse from '@mui/material/Collapse'
import TableCell from '@mui/material/TableCell'
import TableRow from '@mui/material/TableRow'
