export interface MRT_CopyButtonProps<
  TData extends MRT_RowData,
> extends ButtonProps {
  cell: MRT_Cell<TData>
}

export const MRT_CopyButton = <TData extends MRT_RowData>({
  cell,
  ...rest
}: MRT_CopyButtonProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: { localization, muiCopyButtonProps },
  } = table
  const { column, row } = cell
  const { columnDef } = column

  const [copied, setCopied] = useState(false)

  const handleCopy = (event: MouseEvent, text: unknown) => {
    event.stopPropagation()
    navigator.clipboard.writeText(text as string)
    setCopied(true)
    setTimeout(() => setCopied(false), 4000)
  }

  const buttonProps = {
    ...parseFromValuesOrFunc(muiCopyButtonProps, {
      cell,
      column,
      row,
      table,
    }),
    ...parseFromValuesOrFunc(columnDef.muiCopyButtonProps, {
      cell,
      column,
      row,
      table,
    }),
    ...rest,
  }

  return (
    <Tooltip
      {...getCommonTooltipProps('top')}
      title={
        buttonProps?.title ??
        (copied ? localization.copiedToClipboard : localization.clickToCopy)
      }
    >
      <Button
        onClick={(e) => handleCopy(e, cell.getValue())}
        size="small"
        type="button"
        variant="text"
        {...buttonProps}
        sx={(theme) => ({
          backgroundColor: 'transparent',
          border: 'none',
          color: 'inherit',
          cursor: 'copy',
          fontFamily: 'inherit',
          fontSize: 'inherit',
          letterSpacing: 'inherit',
          m: '-0.25rem',
          minWidth: 'unset',
          py: 0,
          textAlign: 'inherit',
          textTransform: 'inherit',
          ...(parseFromValuesOrFunc(buttonProps?.sx, theme) as any),
        })}
        title={undefined}
      />
    </Tooltip>
  )
}

import Box from '@mui/material/Box'
import Button from '@mui/material/Button'
import CircularProgress from '@mui/material/CircularProgress'
import IconButton from '@mui/material/IconButton'
import Tooltip from '@mui/material/Tooltip'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { parseFromValuesOrFunc } from '../../utils/utils'
import type { MRT_Row, MRT_RowData } from '../../types'
import type { BoxProps } from '@mui/material/Box'

export interface MRT_EditActionButtonsProps<
  TData extends MRT_RowData,
> extends BoxProps {
  row: MRT_Row<TData>
  variant?: 'icon' | 'text'
}

export const MRT_EditActionButtons = <TData extends MRT_RowData>({
  row,
  variant = 'icon',
  ...rest
}: MRT_EditActionButtonsProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: {
      icons: { CancelIcon, SaveIcon },
      localization,
      onCreatingRowCancel,
      onCreatingRowSave,
      onEditingRowCancel,
      onEditingRowSave,
    },
    refs: { editInputRefs },
    setCreatingRow,
    setEditingRow,
  } = table
  const { creatingRow, editingRow, isSaving } = state

  const isCreating = creatingRow?.id === row.id
  const isEditing = editingRow?.id === row.id

  const handleCancel = () => {
    if (isCreating) {
      onCreatingRowCancel?.({ row, table })
      setCreatingRow(null)
    } else if (isEditing) {
      onEditingRowCancel?.({ row, table })
      setEditingRow(null)
    }
    row._valuesCache = {} // reset values cache
  }

  const handleSubmitRow = () => {
    // look for auto-filled input values
    Object.values(editInputRefs.current ?? {})
      .filter((inputRef) => row.id === inputRef?.name?.split('_')?.[0])
      ?.forEach((input) => {
        if (
          input.value !== undefined &&
          Object.hasOwn(row?._valuesCache, input.name)
        ) {
          row._valuesCache[input.name] = input.value
        }
      })
    if (isCreating)
      onCreatingRowSave?.({
        exitCreatingMode: () => setCreatingRow(null),
        row,
        table,
        values: row._valuesCache,
      })
    else if (isEditing) {
      onEditingRowSave?.({
        exitEditingMode: () => setEditingRow(null),
        row,
        table,
        values: row?._valuesCache,
      })
    }
  }

  return (
    <Box
      onClick={(e) => e.stopPropagation()}
      sx={(theme) => ({
        display: 'flex',
        gap: '0.75rem',
        ...(parseFromValuesOrFunc(rest?.sx, theme) as any),
      })}
    >
      {variant === 'icon' ? (
        <>
          <Tooltip title={localization.cancel}>
            <IconButton aria-label={localization.cancel} onClick={handleCancel}>
              <CancelIcon />
            </IconButton>
          </Tooltip>
          {((isCreating && onCreatingRowSave) ||
            (isEditing && onEditingRowSave)) && (
            <Tooltip title={localization.save}>
              <IconButton
                aria-label={localization.save}
                color="info"
                disabled={isSaving}
                onClick={handleSubmitRow}
              >
                {isSaving ? <CircularProgress size={18} /> : <SaveIcon />}
              </IconButton>
            </Tooltip>
          )}
        </>
      ) : (
        <>
          <Button onClick={handleCancel} sx={{ minWidth: '100px' }}>
            {localization.cancel}
          </Button>
          <Button
            disabled={isSaving}
            onClick={handleSubmitRow}
            sx={{ minWidth: '100px' }}
            variant="contained"
          >
            {isSaving && <CircularProgress color="inherit" size={18} />}
            {localization.save}
          </Button>
        </>
      )}
    </Box>
  )
}

