import TableFooter from '@mui/material/TableFooter'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableFooterRow } from './MRT_TableFooterRow'
import type { MRT_ColumnVirtualizer, MRT_RowData } from '../../types'
import type { TableFooterProps } from '@mui/material/TableFooter'

export interface MRT_TableFooterProps extends TableFooterProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
}

export const MRT_TableFooter = <TData extends MRT_RowData>({
  columnVirtualizer,
  ...rest
}: MRT_TableFooterProps) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { enableStickyFooter, layoutMode, muiTableFooterProps },
    refs: { tableFooterRef },
  } = table
  const { isFullScreen } = state

  const tableFooterProps = {
    ...parseFromValuesOrFunc(muiTableFooterProps, {
      table,
    }),
    ...rest,
  }

  const stickFooter =
    (isFullScreen || enableStickyFooter) && enableStickyFooter !== false

  const footerGroups = table.getFooterGroups()

  // if no footer cells at all, skip footer
  if (
    !footerGroups.some((footerGroup) =>
      footerGroup.headers?.some(
        (header) =>
          (typeof header.column.columnDef.footer === 'string' &&
            !!header.column.columnDef.footer) ||
          header.column.columnDef.Footer,
      ),
    )
  ) {
    return null
  }

  return (
    <TableFooter
      {...tableFooterProps}
      ref={(ref: HTMLTableSectionElement) => {
        tableFooterRef.current = ref
        if (tableFooterProps?.ref) {
          // @ts-expect-error
          tableFooterProps.ref.current = ref
        }
      }}
      sx={(theme) => ({
        bottom: stickFooter ? 0 : undefined,
        display: layoutMode?.startsWith('grid') ? 'grid' : undefined,
        opacity: stickFooter ? 0.97 : undefined,
        outline: stickFooter
          ? theme.palette.mode === 'light'
            ? `1px solid ${theme.palette.grey[300]}`
            : `1px solid ${theme.palette.grey[700]}`
          : undefined,
        position: stickFooter ? 'sticky' : 'relative',
        zIndex: stickFooter ? 1 : undefined,
        ...(parseFromValuesOrFunc(tableFooterProps?.sx, theme) as any),
      })}
    >
      {footerGroups.map((footerGroup) => (
        <MRT_TableFooterRow
          columnVirtualizer={columnVirtualizer}
          footerGroup={footerGroup as any}
          key={footerGroup.id}
        />
      ))}
    </TableFooter>
  )
}

import TableCell from '@mui/material/TableCell'
import { useTheme } from '@mui/material/styles'
import { getCommonMRTCellStyles } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { cellKeyboardShortcuts } from '../../utils/cell.utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { MRT_Header, MRT_RowData } from '../../types'
import type { TableCellProps } from '@mui/material/TableCell'

export interface MRT_TableFooterCellProps<
  TData extends MRT_RowData,
> extends TableCellProps {
  footer: MRT_Header<TData>
  staticColumnIndex?: number
}

export const MRT_TableFooterCell = <TData extends MRT_RowData>({
  footer,
  staticColumnIndex,
  ...rest
}: MRT_TableFooterCellProps<TData>) => {
  const table = useMRTContext<TData>()
  const theme = useTheme()
  const {
    state,
    options: {
      enableColumnPinning,
      muiTableFooterCellProps,
      enableKeyboardShortcuts,
    },
  } = table
  const { density } = state
  const { column } = footer
  const { columnDef } = column
  const { columnDefType } = columnDef

  const isColumnPinned =
    enableColumnPinning &&
    columnDef.columnDefType !== 'group' &&
    column.getIsPinned()

  const args = { column, table }
  const tableCellProps = {
    ...parseFromValuesOrFunc(muiTableFooterCellProps, args),
    ...parseFromValuesOrFunc(columnDef.muiTableFooterCellProps, args),
    ...rest,
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLTableCellElement>) => {
    tableCellProps?.onKeyDown?.(event)
    cellKeyboardShortcuts({
      event,
      cellValue: footer.column.columnDef.footer,
      table,
    })
  }

  return (
    <TableCell
      align={
        columnDefType === 'group'
          ? 'center'
          : theme.direction === 'rtl'
            ? 'right'
            : 'left'
      }
      colSpan={footer.colSpan}
      data-index={staticColumnIndex}
      data-pinned={!!isColumnPinned || undefined}
      tabIndex={enableKeyboardShortcuts ? 0 : undefined}
      variant="footer"
      {...tableCellProps}
      onKeyDown={handleKeyDown}
      sx={(theme) => ({
        fontWeight: 'bold',
        p:
          density === 'compact'
            ? '0.5rem'
            : density === 'comfortable'
              ? '1rem'
              : '1.5rem',
        verticalAlign: 'top',
        ...getCommonMRTCellStyles({
          column,
          header: footer,
          table,
          tableCellProps,
          theme,
        }),
        ...(parseFromValuesOrFunc(tableCellProps?.sx, theme) as any),
      })}
    >
      {tableCellProps.children ??
        (footer.isPlaceholder
          ? null
          : (parseFromValuesOrFunc(columnDef.Footer, {
              column,
              footer,
              table,
            }) ??
            columnDef.footer ??
            null))}
    </TableCell>
  )
}

import TableRow from '@mui/material/TableRow'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableFooterCell } from './MRT_TableFooterCell'
import type {
  MRT_ColumnVirtualizer,
  MRT_Header,
  MRT_HeaderGroup,
  MRT_RowData,
  MRT_VirtualItem,
} from '../../types'
import type { TableRowProps } from '@mui/material/TableRow'

export interface MRT_TableFooterRowProps<
  TData extends MRT_RowData,
> extends TableRowProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  footerGroup: MRT_HeaderGroup<TData>
}

export const MRT_TableFooterRow = <TData extends MRT_RowData>({
  columnVirtualizer,
  footerGroup,
  ...rest
}: MRT_TableFooterRowProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: {
      layoutMode,
      mrtTheme: { baseBackgroundColor },
      muiTableFooterRowProps,
    },
  } = table

  const { virtualColumns, virtualPaddingLeft, virtualPaddingRight } =
    columnVirtualizer ?? {}

  // if no content in row, skip row
  if (
    !footerGroup.headers?.some(
      (header) =>
        (typeof header.column.columnDef.footer === 'string' &&
          !!header.column.columnDef.footer) ||
        header.column.columnDef.Footer,
    )
  ) {
    return null
  }

  const tableRowProps = {
    ...parseFromValuesOrFunc(muiTableFooterRowProps, {
      footerGroup,
      table,
    }),
    ...rest,
  }

  return (
    <TableRow
      {...tableRowProps}
      sx={(theme) => ({
        backgroundColor: baseBackgroundColor,
        display: layoutMode?.startsWith('grid') ? 'flex' : undefined,
        position: 'relative',
        width: '100%',
        ...(parseFromValuesOrFunc(tableRowProps?.sx, theme) as any),
      })}
    >
      {virtualPaddingLeft ? (
        <th style={{ display: 'flex', width: virtualPaddingLeft }} />
      ) : null}
      {(virtualColumns ?? footerGroup.headers).map(
        (footerOrVirtualFooter, staticColumnIndex) => {
          let footer = footerOrVirtualFooter as MRT_Header<TData>
          if (columnVirtualizer) {
            staticColumnIndex = (footerOrVirtualFooter as MRT_VirtualItem).index
            footer = footerGroup.headers[staticColumnIndex]
          }

          return footer ? (
            <MRT_TableFooterCell
              footer={footer}
              key={footer.id}
              staticColumnIndex={staticColumnIndex}
            />
          ) : null
        },
      )}
      {virtualPaddingRight ? (
        <th style={{ display: 'flex', width: virtualPaddingRight }} />
      ) : null}
    </TableRow>
  )
}

