import { useState } from 'react'
import Box from '@mui/material/Box'
import Grow from '@mui/material/Grow'
import IconButton from '@mui/material/IconButton'
import Popover from '@mui/material/Popover'
import Tooltip from '@mui/material/Tooltip'
import {
  getColumnFilterInfo,
  useDropdownOptions,
} from '../../utils/column.utils'
import { getValueAndLabel, parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableHeadCellFilterContainer } from './MRT_TableHeadCellFilterContainer'
import type { MRT_Header, MRT_RowData } from '../../types'
import type { IconButtonProps } from '@mui/material/IconButton'
import type { MouseEvent } from 'react'

export interface MRT_TableHeadCellFilterLabelProps<
  TData extends MRT_RowData,
> extends IconButtonProps {
  header: MRT_Header<TData>
}

export const MRT_TableHeadCellFilterLabel = <TData extends MRT_RowData = {}>({
  header,
  ...rest
}: MRT_TableHeadCellFilterLabelProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: {
      columnFilterDisplayMode,
      icons: { FilterAltIcon },
      localization,
    },
    refs: { filterInputRefs },
    setShowColumnFilters,
  } = table
  const { column } = header
  const { columnDef } = column

  const filterValue = column.getFilterValue() as [string, string] | string

  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement | null>(null)

  const {
    currentFilterOption,
    isMultiSelectFilter,
    isRangeFilter,
    isSelectFilter,
  } = getColumnFilterInfo({ header, table })

  const dropdownOptions = useDropdownOptions({ header, table })

  const getSelectLabel = (index?: number) =>
    getValueAndLabel(
      dropdownOptions?.find(
        (option) =>
          getValueAndLabel(option).value ===
          (index !== undefined ? filterValue[index] : filterValue),
      ),
    ).label

  const isFilterActive =
    (Array.isArray(filterValue) && filterValue.some(Boolean)) ||
    (!!filterValue && !Array.isArray(filterValue))

  const filterTooltip =
    columnFilterDisplayMode === 'popover' && !isFilterActive
      ? localization.filterByColumn?.replace(
          '{column}',
          String(columnDef.header),
        )
      : localization.filteringByColumn
          .replace('{column}', String(columnDef.header))
          .replace(
            '{filterType}',
            currentFilterOption
              ? localization[
                  `filter${
                    currentFilterOption.charAt(0).toUpperCase() +
                    currentFilterOption.slice(1)
                  }` as keyof typeof localization
                ]
              : '',
          )
          .replace(
            '{filterValue}',
            `"${
              Array.isArray(filterValue)
                ? filterValue
                    .map((value, index) =>
                      isMultiSelectFilter ? getSelectLabel(index) : value,
                    )
                    .join(
                      `" ${isRangeFilter ? localization.and : localization.or} "`,
                    )
                : isSelectFilter
                  ? getSelectLabel()
                  : filterValue
            }"`,
          )
          .replace('" "', '')

  return (
    <>
      <Grow
        in={
          columnFilterDisplayMode === 'popover' ||
          (!!filterValue && !isRangeFilter) ||
          (isRangeFilter && (!!filterValue?.[0] || !!filterValue?.[1]))
        }
        unmountOnExit
      >
        <Box component="span" sx={{ flex: '0 0' }}>
          <Tooltip placement="top" title={filterTooltip}>
            <IconButton
              disableRipple
              onClick={(event: MouseEvent<HTMLButtonElement>) => {
                if (columnFilterDisplayMode === 'popover') {
                  setAnchorEl(event.currentTarget)
                } else {
                  setShowColumnFilters(true)
                }
                queueMicrotask(() => {
                  filterInputRefs.current?.[`${column.id}-0`]?.focus?.()
                  filterInputRefs.current?.[`${column.id}-0`]?.select?.()
                })
                event.stopPropagation()
              }}
              size="small"
              {...rest}
              sx={(theme) => ({
                height: '16px',
                ml: '4px',
                opacity: isFilterActive ? 1 : 0.3,
                p: '8px',
                transform: 'scale(0.75)',
                transition: 'all 150ms ease-in-out',
                width: '16px',
                ...(parseFromValuesOrFunc(rest?.sx, theme) as any),
              })}
            >
              <FilterAltIcon />
            </IconButton>
          </Tooltip>
        </Box>
      </Grow>
      {columnFilterDisplayMode === 'popover' && (
        <Popover
          anchorEl={anchorEl}
          anchorOrigin={{
            horizontal: 'center',
            vertical: 'top',
          }}
          disableScrollLock
          onClick={(event) => event.stopPropagation()}
          onClose={(event) => {
            // @ts-expect-error
            event.stopPropagation()
            setAnchorEl(null)
          }}
          onKeyDown={(event) => event.key === 'Enter' && setAnchorEl(null)}
          open={!!anchorEl}
          slotProps={{ paper: { sx: { overflow: 'visible' } } }}
          transformOrigin={{
            horizontal: 'center',
            vertical: 'bottom',
          }}
        >
          <Box sx={{ p: '1rem' }}>
            <MRT_TableHeadCellFilterContainer header={header} />
          </Box>
        </Popover>
      )}
    </>
  )
}

import { reorderColumn } from '../../utils/column.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_GrabHandleButton } from '../buttons/MRT_GrabHandleButton'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { DragEvent, RefObject } from 'react'
import type { IconButtonProps } from '@mui/material/IconButton'
import type { MRT_Column, MRT_RowData } from '../../types'

export interface MRT_TableHeadCellGrabHandleProps<
  TData extends MRT_RowData,
> extends IconButtonProps {
  column: MRT_Column<TData>
  tableHeadCellRef: RefObject<HTMLTableCellElement | null>
}

export const MRT_TableHeadCellGrabHandle = <TData extends MRT_RowData>({
  column,
  tableHeadCellRef,
  ...rest
}: MRT_TableHeadCellGrabHandleProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { enableColumnOrdering, muiColumnDragHandleProps },
    setColumnOrder,
    setColumnPinning,
    setDraggingColumn,
    setHoveredColumn,
  } = table
  const { columnDef } = column
  const { columnOrder, draggingColumn, hoveredColumn } = state

  const iconButtonProps = {
    ...parseFromValuesOrFunc(muiColumnDragHandleProps, { column, table }),
    ...parseFromValuesOrFunc(columnDef.muiColumnDragHandleProps, {
      column,
      table,
    }),
    ...rest,
  }

  const handleDragStart = (event: DragEvent<HTMLButtonElement>) => {
    iconButtonProps?.onDragStart?.(event)
    setDraggingColumn(column)
    try {
      event.dataTransfer.setDragImage(
        tableHeadCellRef.current as HTMLElement,
        0,
        0,
      )
    } catch (e) {
      console.error(e)
    }
  }

  const handleDragEnd = (event: DragEvent<HTMLButtonElement>) => {
    iconButtonProps?.onDragEnd?.(event)
    if (hoveredColumn?.id === 'drop-zone') {
      column.toggleGrouping()
    } else if (
      enableColumnOrdering &&
      hoveredColumn &&
      hoveredColumn?.id !== draggingColumn?.id
    ) {
      const reorderedColumns = reorderColumn(
        column,
        hoveredColumn as MRT_Column<TData>,
        columnOrder,
      )
      setColumnOrder(reorderedColumns)
      setColumnPinning(({ start = [], end = [] }) => ({
        start: reorderedColumns.filter((header) => start.includes(header)),
        end: reorderedColumns.filter((header) => end.includes(header)),
      }))
    }
    setDraggingColumn(null)
    setHoveredColumn(null)
  }

  return (
    <MRT_GrabHandleButton
      {...iconButtonProps}
      onDragEnd={handleDragEnd}
      onDragStart={handleDragStart}
    />
  )
}

import Box from '@mui/material/Box'
import Divider from '@mui/material/Divider'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { DividerProps } from '@mui/material/Divider'
import type { MRT_Header, MRT_RowData } from '../../types'

export interface MRT_TableHeadCellResizeHandleProps<
  TData extends MRT_RowData,
> extends DividerProps {
  header: MRT_Header<TData>
}

export const MRT_TableHeadCellResizeHandle = <TData extends MRT_RowData>({
  header,
  ...rest
}: MRT_TableHeadCellResizeHandleProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { columnResizeDirection, columnResizeMode },
    setColumnResizing,
  } = table
  const { density } = state
  const { column } = header

  const handler = header.getResizeHandler()

  const mx =
    density === 'compact'
      ? '-8px'
      : density === 'comfortable'
        ? '-16px'
        : '-24px'

  const lr = column.columnDef.columnDefType === 'display' ? '4px' : '0'

  return (
    <Box
      className="Mui-TableHeadCell-ResizeHandle-Wrapper"
      onDoubleClick={() => {
        setColumnResizing((old) => ({
          ...old,
          isResizingColumn: false,
        }))
        column.resetSize()
      }}
      onMouseDown={handler}
      onTouchStart={handler}
      style={{
        transform:
          column.getIsResizing() && columnResizeMode === 'onEnd'
            ? `translateX(${
                (columnResizeDirection === 'rtl' ? -1 : 1) *
                (state.columnResizing.deltaOffset ?? 0)
              }px)`
            : undefined,
      }}
      sx={(theme) => ({
        '&:active > hr': {
          backgroundColor: theme.palette.info.main,
          opacity:
            header.subHeaders.length || columnResizeMode === 'onEnd' ? 1 : 0,
        },
        cursor: 'col-resize',
        left: columnResizeDirection === 'rtl' ? lr : undefined,
        ml: columnResizeDirection === 'rtl' ? mx : undefined,
        mr: columnResizeDirection === 'ltr' ? mx : undefined,
        position: 'absolute',
        px: '4px',
        right: columnResizeDirection === 'ltr' ? lr : undefined,
      })}
    >
      <Divider
        className="Mui-TableHeadCell-ResizeHandle-Divider"
        flexItem
        orientation="vertical"
        sx={(theme) => ({
          borderRadius: '2px',
          borderWidth: '2px',
          height: '24px',
          touchAction: 'none',
          transform: 'translateX(4px)',
          transition: column.getIsResizing()
            ? undefined
            : 'all 150ms ease-in-out',
          userSelect: 'none',
          zIndex: 4,
          ...(parseFromValuesOrFunc(rest?.sx, theme) as any),
        })}
      />
    </Box>
  )
}

import Badge from '@mui/material/Badge'
import TableSortLabel from '@mui/material/TableSortLabel'
import Tooltip from '@mui/material/Tooltip'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { TableSortLabelProps } from '@mui/material/TableSortLabel'
import type { MRT_Header, MRT_RowData } from '../../types'

export interface MRT_TableHeadCellSortLabelProps<
  TData extends MRT_RowData,
> extends TableSortLabelProps {
  header: MRT_Header<TData>
}

export const MRT_TableHeadCellSortLabel = <TData extends MRT_RowData>({
  header,
  ...rest
}: MRT_TableHeadCellSortLabelProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: {
      icons: { ArrowDownwardIcon, SyncAltIcon },
      localization,
    },
  } = table
  const { column } = header
  const { columnDef } = column
  const { isLoading, showSkeletons } = state

  return (
    <table.Subscribe source={table.atoms.sorting}>
      {(sorting) => {
        const isSorted = !!column.getIsSorted()
        const sortTooltip =
          isLoading || showSkeletons
            ? ''
            : column.getIsSorted()
              ? column.getIsSorted() === 'desc'
                ? localization.sortedByColumnDesc.replace(
                    '{column}',
                    columnDef.header,
                  )
                : localization.sortedByColumnAsc.replace(
                    '{column}',
                    columnDef.header,
                  )
              : column.getNextSortingOrder() === 'desc'
                ? localization.sortByColumnDesc.replace(
                    '{column}',
                    columnDef.header,
                  )
                : localization.sortByColumnAsc.replace(
                    '{column}',
                    columnDef.header,
                  )

        const direction = isSorted
          ? (column.getIsSorted() as 'asc' | 'desc')
          : undefined

        return (
          <Tooltip placement="top" title={sortTooltip}>
            <Badge
              badgeContent={sorting.length > 1 ? column.getSortIndex() + 1 : 0}
              overlap="circular"
            >
              <TableSortLabel
                IconComponent={
                  !isSorted
                    ? (props) => (
                        <SyncAltIcon
                          {...props}
                          direction={direction}
                          style={{
                            transform:
                              'rotate(-90deg) scaleX(0.9) translateX(-1px)',
                          }}
                        />
                      )
                    : ArrowDownwardIcon
                }
                active
                aria-label={sortTooltip}
                direction={direction}
                onClick={(e) => {
                  e.stopPropagation()
                  header.column.getToggleSortingHandler()?.(e)
                }}
                {...rest}
                sx={(theme) => ({
                  '.MuiTableSortLabel-icon': {
                    color: `${
                      theme.palette.mode === 'dark'
                        ? theme.palette.text.primary
                        : theme.palette.text.secondary
                    } !important`,
                  },
                  flex: '0 0',
                  opacity: isSorted ? 1 : 0.3,
                  transition: 'all 150ms ease-in-out',
                  width: '3ch',
                  ...(parseFromValuesOrFunc(rest?.sx, theme) as any),
                })}
              />
            </Badge>
          </Tooltip>
        )
      }}
    </table.Subscribe>
  )
}

import TableRow from '@mui/material/TableRow'
import { alpha } from '@mui/material/styles'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableHeadCell } from './MRT_TableHeadCell'
import type {
  MRT_ColumnVirtualizer,
  MRT_Header,
  MRT_HeaderGroup,
  MRT_RowData,
  MRT_VirtualItem,
} from '../../types'
import type { TableRowProps } from '@mui/material/TableRow'

export interface MRT_TableHeadRowProps<
  TData extends MRT_RowData,
> extends TableRowProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  headerGroup: MRT_HeaderGroup<TData>
}

export const MRT_TableHeadRow = <TData extends MRT_RowData>({
  columnVirtualizer,
  headerGroup,
  ...rest
}: MRT_TableHeadRowProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: {
      enableStickyHeader,
      layoutMode,
      mrtTheme: { baseBackgroundColor },
      muiTableHeadRowProps,
    },
  } = table

  const { virtualColumns, virtualPaddingLeft, virtualPaddingRight } =
    columnVirtualizer ?? {}

  const tableRowProps = {
    ...parseFromValuesOrFunc(muiTableHeadRowProps, {
      headerGroup,
      table,
    }),
    ...rest,
  }

  return (
    <TableRow
      {...tableRowProps}
      sx={(theme) => ({
        backgroundColor: baseBackgroundColor,
        boxShadow: `4px 0 8px ${alpha(theme.palette.common.black, 0.1)}`,
        display: layoutMode?.startsWith('grid') ? 'flex' : undefined,
        position:
          enableStickyHeader && layoutMode === 'semantic'
            ? 'sticky'
            : 'relative',
        top: 0,
        ...(parseFromValuesOrFunc(tableRowProps?.sx, theme) as any),
      })}
    >
      {virtualPaddingLeft ? (
        <th style={{ display: 'flex', width: virtualPaddingLeft }} />
      ) : null}
      {(virtualColumns ?? headerGroup.headers).map(
        (headerOrVirtualHeader, staticColumnIndex) => {
          let header = headerOrVirtualHeader as MRT_Header<TData>
          if (columnVirtualizer) {
            staticColumnIndex = (headerOrVirtualHeader as MRT_VirtualItem).index
            header = headerGroup.headers[staticColumnIndex]
          }

          return header ? (
            <MRT_TableHeadCell
              columnVirtualizer={columnVirtualizer}
              header={header}
              key={header.id}
              staticColumnIndex={staticColumnIndex}
            />
          ) : null
        },
      )}
      {virtualPaddingRight ? (
        <th style={{ display: 'flex', width: virtualPaddingRight }} />
      ) : null}
    </TableRow>
  )
}

import { useState } from 'react'
import MenuItem from '@mui/material/MenuItem'
import TextField from '@mui/material/TextField'
import { getValueAndLabel, parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { ChangeEvent, FocusEvent, KeyboardEvent } from 'react'
import type { TextFieldProps } from '@mui/material/TextField'
import type { MRT_Cell, MRT_RowData } from '../../types'

export interface MRT_EditCellTextFieldProps<
  TData extends MRT_RowData,
> extends TextFieldProps<'standard'> {
  cell: MRT_Cell<TData>
}

export const MRT_EditCellTextField = <TData extends MRT_RowData>({
  cell,
  ...rest
}: MRT_EditCellTextFieldProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { createDisplayMode, editDisplayMode, muiEditTextFieldProps },
    refs: { editInputRefs },
    setCreatingRow,
    setEditingCell,
    setEditingRow,
  } = table
  const { column, row } = cell
  const { columnDef } = column
  const { creatingRow, editingRow } = state
  const { editSelectOptions, editVariant } = columnDef

  const isCreating = creatingRow?.id === row.id
  const isEditing = editingRow?.id === row.id

  const [value, setValue] = useState(() => cell.getValue<string>())
  const [completesComposition, setCompletesComposition] = useState(true)

  const textFieldProps: TextFieldProps = {
    ...parseFromValuesOrFunc(muiEditTextFieldProps, {
      cell,
      column,
      row,
      table,
    }),
    ...parseFromValuesOrFunc(columnDef.muiEditTextFieldProps, {
      cell,
      column,
      row,
      table,
    }),
    ...rest,
  }

  const selectOptions = parseFromValuesOrFunc(editSelectOptions, {
    cell,
    column,
    row,
    table,
  })

  const isSelectEdit = editVariant === 'select' || textFieldProps?.select

  const saveInputValueToRowCache = (newValue: string) => {
    row._valuesCache[column.id] = newValue
    if (isCreating) {
      setCreatingRow(row)
    } else if (isEditing) {
      setEditingRow(row)
    }
  }

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    textFieldProps.onChange?.(event)
    setValue(event.target.value)
    if (isSelectEdit) {
      saveInputValueToRowCache(event.target.value)
    }
  }

  const handleBlur = (event: FocusEvent<HTMLInputElement>) => {
    textFieldProps.onBlur?.(event)
    saveInputValueToRowCache(value)
    setEditingCell(null)
  }

  const handleEnterKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    textFieldProps.onKeyDown?.(event)
    if (event.key === 'Enter' && !event.shiftKey && completesComposition) {
      editInputRefs.current?.[column.id]?.blur()
    }
  }

  if (columnDef.Edit) {
    return <>{columnDef.Edit?.({ cell, column, row, table })}</>
  }

  return (
    <TextField
      disabled={parseFromValuesOrFunc(columnDef.enableEditing, row) === false}
      fullWidth
      inputRef={(inputRef) => {
        if (inputRef) {
          editInputRefs.current![column.id] = isSelectEdit
            ? inputRef.node
            : inputRef
          if (textFieldProps.inputRef) {
            textFieldProps.inputRef = inputRef
          }
        }
      }}
      label={
        ['custom', 'modal'].includes(
          (isCreating ? createDisplayMode : editDisplayMode) as string,
        )
          ? columnDef.header
          : undefined
      }
      margin="none"
      name={column.id}
      placeholder={
        !['custom', 'modal'].includes(
          (isCreating ? createDisplayMode : editDisplayMode) as string,
        )
          ? columnDef.header
          : undefined
      }
      select={isSelectEdit}
      size="small"
      value={value ?? ''}
      variant="standard"
      {...textFieldProps}
      slotProps={{
        ...(textFieldProps.slotProps as any),
        input: {
          ...(textFieldProps.variant !== 'outlined'
            ? { disableUnderline: editDisplayMode === 'table' }
            : {}),
          ...(textFieldProps.slotProps as any)?.input,
          sx: (theme: any) => ({
            mb: 0,
            ...parseFromValuesOrFunc(
              (textFieldProps.slotProps as any)?.input?.sx,
              theme,
            ),
          }),
        },
        select: {
          MenuProps: { disableScrollLock: true },
          ...(textFieldProps.slotProps as any)?.select,
        },
        htmlInput: {
          autoComplete: 'off',
          ...(textFieldProps.slotProps as any)?.htmlInput,
        },
      }}
      onBlur={handleBlur}
      onChange={handleChange}
      onClick={(e) => {
        e.stopPropagation()
        textFieldProps?.onClick?.(e)
      }}
      onKeyDown={handleEnterKeyDown}
      onCompositionStart={() => setCompletesComposition(false)}
      onCompositionEnd={() => setCompletesComposition(true)}
    >
      {textFieldProps.children ??
        selectOptions?.map((option) => {
          const { label, value } = getValueAndLabel(option)
          return (
            <MenuItem
              key={value}
              sx={{
                alignItems: 'center',
                display: 'flex',
                gap: '0.5rem',
                m: 0,
              }}
              value={value}
            >
              {label}
            </MenuItem>
          )
        })}
    </TextField>
  )
}

import Checkbox from '@mui/material/Checkbox'
import FormControlLabel from '@mui/material/FormControlLabel'
import Tooltip from '@mui/material/Tooltip'
import { getCommonTooltipProps } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { MRT_Column, MRT_RowData } from '../../types'
import type { CheckboxProps } from '@mui/material/Checkbox'

export interface MRT_FilterCheckboxProps<
  TData extends MRT_RowData,
> extends CheckboxProps {
  column: MRT_Column<TData>
}

export const MRT_FilterCheckbox = <TData extends MRT_RowData>({
  column,
  ...rest
}: MRT_FilterCheckboxProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: { localization, muiFilterCheckboxProps },
  } = table
  const { density } = state
  const { columnDef } = column

  const checkboxProps = {
    ...parseFromValuesOrFunc(muiFilterCheckboxProps, {
      column,
      table,
    }),
    ...parseFromValuesOrFunc(columnDef.muiFilterCheckboxProps, {
      column,
      table,
    }),
    ...rest,
  }

  const filterLabel = localization.filterByColumn?.replace(
    '{column}',
    columnDef.header,
  )

  return (
    <Tooltip
      {...getCommonTooltipProps()}
      title={checkboxProps?.title ?? filterLabel}
    >
      <FormControlLabel
        control={
          <Checkbox
            checked={column.getFilterValue() === 'true'}
            color={
              column.getFilterValue() === undefined ? 'default' : 'primary'
            }
            indeterminate={column.getFilterValue() === undefined}
            size={density === 'compact' ? 'small' : 'medium'}
            {...checkboxProps}
            onChange={(e, checked) => {
              column.setFilterValue(
                column.getFilterValue() === undefined
                  ? 'true'
                  : column.getFilterValue() === 'true'
                    ? 'false'
                    : undefined,
              )
              checkboxProps?.onChange?.(e, checked)
            }}
            onClick={(e) => {
              e.stopPropagation()
              checkboxProps?.onClick?.(e)
            }}
            sx={(theme) => ({
              height: '2.5rem',
              width: '2.5rem',
              ...(parseFromValuesOrFunc(checkboxProps?.sx, theme) as any),
            })}
          />
        }
        disableTypography
        label={checkboxProps.title ?? filterLabel}
        sx={{ color: 'text.secondary', fontWeight: 'normal', mt: '-4px' }}
        title={undefined}
      />
    </Tooltip>
  )
}

