    await page.getByRole('menuitem', { name: 'Ungroup by First Name' }).click()
    await expect(page.getByRole('button', { name: 'Expand all' })).toHaveCount(
      0,
    )
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

