      <button
        type="button"
        role="menuitem"
        onClick={() => run(interactions.clearSelection)}
      >
        <span>⌫</span> Clear contents
      </button>
      <div className="menu-rule" />
      <button
        type="button"
        role="menuitem"
        onClick={() =>
          run(() => table.setSorting([{ id: column.id, desc: false }]))
        }
      >
        <span>↑</span> Sort ascending
      </button>
      <button
        type="button"
        role="menuitem"
        onClick={() =>
          run(() => table.setSorting([{ id: column.id, desc: true }]))
