import React from 'react'
import { createFileRoute } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'
import { useTable } from '@tanstack/react-table'
import {
  createTableWorker,
  createWorkerRowModel,
} from '@tanstack/react-table/experimental-worker-plugin'
import { makeData } from '../makeData'
import { columnHelper, columns, sharedFeatures } from '../tableConfig'
import type { HTMLProps } from 'react'

// =====================================================================
// Route (SSR entry) — data is generated only on the server (server fn)
// and serialized to the client so hydration sees the same rows. The
// server has no Worker global, so the worker plugin's SSR guard makes
// the server render pre-stage (unprocessed) rows; after hydration the
// client worker takes over and processes them.
// =====================================================================

const getInitialData = createServerFn({ method: 'GET' }).handler(() =>
  makeData(10_000),
)

export const Route = createFileRoute('/')({
  loader: () => getInitialData(),
  component: App,
})

// One handle per table worker; every offloaded stage shares it, so filtering,
// grouping, and sorting cost a single worker and one round trip per change.
// Module scope is safe on the server: the worker is only created lazily on
// the client (and never at all when `Worker` is undefined).
const tableWorker = createTableWorker({
  createWorker: () =>
    new Worker(new URL('../table.worker.ts', import.meta.url), {
      type: 'module',
    }),
})

// Same features as the worker's shadow table, but with the filtered, grouped,
// and sorted stages swapped for worker-backed ones. Expanding and pagination
// stay on the main thread (cheap, downstream); row selection is pure state.
const features: typeof sharedFeatures = {
  ...sharedFeatures,
  filteredRowModel: createWorkerRowModel(tableWorker, 'filtered'),
  groupedRowModel: createWorkerRowModel(tableWorker, 'grouped'),
  sortedRowModel: createWorkerRowModel(tableWorker, 'sorted'),
}

// Row selection lives entirely on the main thread: a display column with no
// accessor never affects processing, so the worker does not need to know
// about it.
const selectionCell = ({ row }: { row: any }) => (
  <IndeterminateCheckbox
    checked={row.getIsSelected()}
    disabled={!row.getCanSelect()}
    indeterminate={row.getIsSomeSelected()}
    onChange={row.getToggleSelectedHandler()}
  />
)

const selectionColumn = columnHelper.display({
  id: 'select',
  header: ({ table }) => (
    <IndeterminateCheckbox
      checked={table.getIsAllRowsSelected()}
      indeterminate={table.getIsSomeRowsSelected()}
      onChange={table.getToggleAllRowsSelectedHandler()}
    />
  ),
  cell: selectionCell,
  // Group rows render this column as an aggregated cell; selecting a group
  // selects all of its leaf rows.
  aggregatedCell: selectionCell,
})

const allColumns = [selectionColumn, ...columns]

function IndeterminateCheckbox({
  indeterminate,
  className = '',
  ...rest
}: { indeterminate?: boolean } & HTMLProps<HTMLInputElement>) {
  const ref = React.useRef<HTMLInputElement>(null!)

  React.useEffect(() => {
    if (typeof indeterminate === 'boolean') {
      ref.current.indeterminate = !rest.checked && indeterminate
    }
  }, [ref, indeterminate])

  return (
    <input
      type="checkbox"
      ref={ref}
      className={className + ' sortable-header'}
      {...rest}
    />
  )
}

/**
 * A requestAnimationFrame-driven dot that freezes if (and only if) the main
 * thread is blocked. Purely for demo purposes.
 */
function JankMeter() {
  const dotRef = React.useRef<HTMLDivElement>(null)
  const stallRef = React.useRef<HTMLSpanElement>(null)

  React.useEffect(() => {
    if (dotRef.current) {
      dotRef.current.dataset.hydrated = 'true'
    }

    let last = performance.now()
    let rafId = 0
    const tick = () => {
      const now = performance.now()
      const gap = now - last
      last = now
      if (gap > 100 && stallRef.current) {
        stallRef.current.textContent = `last main-thread stall: ${Math.round(gap)} ms`
      }
      if (dotRef.current) {
        const x = Math.abs(((now / 6) % 420) - 210)
        dotRef.current.style.transform = `translateX(${x}px)`
      }
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  }, [])

  return (
    <div className="jank-meter">
      <div className="jank-track">
        <div ref={dotRef} className="jank-dot" />
      </div>
      <span ref={stallRef} className="jank-stall">
        no main-thread stalls yet
      </span>
    </div>
  )
}

function App() {
  const initialData = Route.useLoaderData()
  const [data, setData] = React.useState(initialData)
  // Regenerating on the client is fine post-hydration (faker runs in the
  // browser); only the initial dataset must be server-generated so the
  // server HTML and the hydrating client render identical rows.
  const refreshData = () => setData(makeData(10_000))
  const stressTest = () => setData(makeData(1_000_000))

  // A completely normal table: no manual* flags, no postMessage in app code.
  const table = useTable(
    {
      features,
      columns: allColumns,
      data,
      debugTable: true,
    },
    (state) => state, // default selector
  )

  const isPending = table.state.workerRowModels.isPending
  const globalFilter = (table.state.globalFilter as string | undefined) ?? ''
  const selectedCount = table.getSelectedRowIds().length

  return (
    <div className="demo-root">
      <JankMeter />
      <div className="spacer-md" />
      <div className="controls">
        <input
          value={globalFilter}
          onChange={(e) => table.setGlobalFilter(e.target.value)}
          placeholder="Search name or status..."
          className="search-input"
        />
        <button onClick={() => refreshData()} className="demo-button">
          Regenerate Data
        </button>
        <button onClick={() => stressTest()} className="demo-button">
          Stress Test (1M rows)
        </button>
        {isPending ? (
          <span className="pending-label">processing...</span>
        ) : null}
      </div>
      <div className="spacer-sm" />
      <div>
        {table.getFilteredRowModel().rows.length.toLocaleString()} of{' '}
        {data.length.toLocaleString()} rows | {selectedCount.toLocaleString()}{' '}
        selected
      </div>
      <div className="spacer-md" />
      <table className={isPending ? 'table-stale' : undefined}>
        <thead>
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <th key={header.id} colSpan={header.colSpan}>
                  {header.isPlaceholder ? null : (
                    <div>
                      {header.column.getCanGroup() ? (
                        // If the header can be grouped, add a toggle. The
                        // grouping itself happens in the worker.
                        <button
                          onClick={header.column.getToggleGroupingHandler()}
                          className="sortable-header"
                        >
                          {header.column.getIsGrouped()
                            ? `🛑(${header.column.getGroupedIndex()}) `
                            : `👊 `}
                        </button>
                      ) : null}{' '}
                      <span
                        className={
                          header.column.getCanSort() ? 'sortable-header' : ''
                        }
                        onClick={header.column.getToggleSortingHandler()}
                        title={
                          header.column.getCanSort()
                            ? header.column.getNextSortingOrder() === 'asc'
                              ? 'Sort ascending'
                              : header.column.getNextSortingOrder() === 'desc'
                                ? 'Sort descending'
                                : 'Clear sort'
                            : undefined
                        }
                      >
                        <table.FlexRender header={header} />
                        {{
                          asc: ' 🔼',
                          desc: ' 🔽',
                        }[header.column.getIsSorted() as string] ?? null}
                      </span>
                    </div>
                  )}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id}>
              {row.getAllCells().map((cell) => (
                <td
                  key={cell.id}
                  style={{
                    background: cell.getIsGrouped()
                      ? '#0aff0082'
                      : cell.getIsAggregated()
                        ? '#ffa50078'
                        : cell.getIsPlaceholder()
                          ? '#ff000042'
                          : 'white',
                  }}
                >
                  {cell.getIsGrouped() ? (
                    // Grouped cell: expander + group value + leaf count
                    <button
                      onClick={row.getToggleExpandedHandler()}
                      style={{
                        cursor: row.getCanExpand() ? 'pointer' : 'normal',
                      }}
                    >
                      {row.getIsExpanded() ? '👇' : '👉'}{' '}
                      <table.FlexRender cell={cell} /> (
                      {row.subRows.length.toLocaleString()})
                    </button>
                  ) : cell.getIsAggregated() ? (
                    <table.FlexRender cell={cell} />
                  ) : cell.getIsPlaceholder() ? null : (
                    <table.FlexRender cell={cell} />
                  )}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      <div className="spacer-sm" />
      <div className="controls">
        <button
          className="demo-button demo-button-sm"
          onClick={() => table.setPageIndex(0)}
          disabled={!table.getCanPreviousPage()}
        >
          {'<<'}
        </button>
        <button
          className="demo-button demo-button-sm"
          onClick={() => table.previousPage()}
          disabled={!table.getCanPreviousPage()}
        >
          {'<'}
        </button>
        <button
          className="demo-button demo-button-sm"
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
        >
          {'>'}
        </button>
        <button
          className="demo-button demo-button-sm"
          onClick={() => table.lastPage()}
          disabled={!table.getCanLastPage()}
        >
          {'>>'}
        </button>
        <span className="inline-controls">
          <div>Page</div>
          <strong>
            {(table.state.pagination.pageIndex + 1).toLocaleString()} of{' '}
            {table.getPageCount().toLocaleString()}
          </strong>
        </span>
        <select
          value={table.state.pagination.pageSize}
          onChange={(e) => {
            table.setPageSize(Number(e.target.value))
          }}
        >
          {[10, 20, 30, 40, 50].map((pageSize) => (
            <option key={pageSize} value={pageSize}>
              Show {pageSize}
            </option>
          ))}
        </select>
      </div>
    </div>
  )
}

import { initTableWorker } from '@tanstack/react-table/experimental-worker-plugin'
import { columns, sharedFeatures } from './tableConfig'

// The entire worker: a headless shadow table running the real table-core
// row model pipeline off the main thread.
initTableWorker({ features: sharedFeatures, columns })

import {
  aggregationFn_extent,
  aggregationFn_mean,
  aggregationFn_median,
  aggregationFn_sum,
  columnFilteringFeature,
  columnGroupingFeature,
  createColumnHelper,
  createExpandedRowModel,
  createFilteredRowModel,
  createGroupedRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  filterFn_includesString,
  globalFilteringFeature,
  rowAggregationFeature,
  rowExpandingFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_datetime,
  sortFn_text,
  tableFeatures,
} from '@tanstack/react-table'
import { workerRowModelsFeature } from '@tanstack/react-table/experimental-worker-plugin'
import type { SortFn } from '@tanstack/react-table'
import type { Person } from './makeData'

// Shared between the main thread (main.tsx) and the worker (table.worker.ts).
//
// This is where worker-based row models earn their keep: everything here must
// be thread-portable. Columns use accessorKeys or accessors defined in this
// module, headers/cells are only ever rendered on the main thread, and any
// custom sortFn/filterFn/getGroupingValue must be a plain function declared
// here (not a closure over app state) so BOTH threads resolve the same
// implementation.
//
// The sync filtered/grouped/sorted row models registered here are the ones
// that run inside the worker's shadow table; main.tsx swaps them for
// worker-backed versions. Expanding and pagination stay on the main thread
// (both are cheap, downstream stages). Row selection is pure state and never
// crosses threads at all.

export const sharedFeatures = tableFeatures({
  rowAggregationFeature,
  rowSortingFeature,
  columnFilteringFeature,
  globalFilteringFeature,
  columnGroupingFeature,
  rowExpandingFeature,
  rowSelectionFeature,
  rowPaginationFeature,
  workerRowModelsFeature,
  filteredRowModel: createFilteredRowModel(),
  groupedRowModel: createGroupedRowModel(),
  sortedRowModel: createSortedRowModel(),
  expandedRowModel: createExpandedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    datetime: sortFn_datetime,
    text: sortFn_text,
  },
  filterFns: {
    includesString: filterFn_includesString,
  },
  aggregationFns: {
    extent: aggregationFn_extent,
    mean: aggregationFn_mean,
    median: aggregationFn_median,
    sum: aggregationFn_sum,
  },
})

export const columnHelper = createColumnHelper<typeof sharedFeatures, Person>()

// Custom sorting logic for our enum column (single < complicated < relationship).
// Declared here so the worker's shadow table can resolve it by reference.
const sortStatusFn: SortFn<typeof sharedFeatures, Person> = (
  rowA,
  rowB,
  _columnId,
) => {
  const statusOrder = ['single', 'complicated', 'relationship']
  return (
    statusOrder.indexOf(rowA.original.status) -
    statusOrder.indexOf(rowB.original.status)
  )
}

// Multi-aggregation values are keyed objects on grouped rows, so define which
// result controls their order. Leaf rows still sort by their numeric age.
const sortAgeFn: SortFn<typeof sharedFeatures, Person> = (rowA, rowB) => {
  const getAge = (row: typeof rowA) => {
    const value = row.getValue<number | { median: number }>('age')
    return typeof value === 'number' ? value : value.median
  }

  return getAge(rowA) - getAge(rowB)
}

// The sorting example's column defs merged with the grouping example's
// aggregation props, exercising both entirely off the main thread: default
// string/number ordering, a named registry sortFn (alphanumeric),
// sortUndefined, invertSorting, a custom enum sortFn, getGroupingValue
// overrides, and median/sum/mean aggregations with aggregatedCell renderers.
export const columns = columnHelper.columns([
  columnHelper.accessor('firstName', {
    header: 'First Name',
    cell: (info) => info.getValue(),
    // override the value used for row grouping
    getGroupingValue: (row) => `${row.firstName} ${row.lastName}`,
  }),
  columnHelper.accessor((row) => row.lastName, {
    id: 'lastName',
    cell: (info) => info.getValue(),
    header: () => <span>Last Name</span>,
    sortUndefined: 'last', // force undefined values to the end
    sortDescFirst: false, // ascending first (nullable values confuse auto-detect)
  }),
  columnHelper.accessor('email', {
    header: 'Email',
    sortFn: 'alphanumeric',
    enableGrouping: false,
  }),
  columnHelper.accessor('age', {
    header: () => 'Age',
    sortFn: sortAgeFn,
    aggregationFn: ['median', { id: 'range', aggregationFn: 'extent' }],
    aggregatedCell: ({ getValue }) => {
      const value = getValue<{
        median: number
        range: [number | undefined, number | undefined]
      }>()
      return `Median ${Math.round(value.median * 100) / 100}; Range ${value.range[0]}–${value.range[1]}`
    },
  }),
  columnHelper.accessor('visits', {
    header: () => <span>Visits</span>,
    sortUndefined: 'last',
    aggregationFn: 'sum',
    aggregatedCell: ({ getValue }) => {
      const value = getValue<number | undefined>()
      return Number.isFinite(value) ? value!.toLocaleString() : '-'
    },
  }),
  columnHelper.accessor('status', {
    header: 'Status',
    sortFn: sortStatusFn, // custom enum ordering, resolved in the worker
  }),
  columnHelper.accessor('progress', {
    header: 'Profile Progress',
    cell: ({ getValue }) => Math.round(getValue<number>() * 100) / 100 + '%',
    aggregationFn: 'mean',
    aggregatedCell: ({ getValue }) =>
      Math.round(getValue<number>() * 100) / 100 + '%',
  }),
  columnHelper.accessor('rank', {
    header: 'Rank',
    invertSorting: true, // golf-score style: smaller is better
  }),
  columnHelper.accessor('createdAt', {
    header: 'Created At',
    cell: (info) => info.getValue<Date>().toISOString().slice(0, 10),
    enableGrouping: false,
    aggregatedCell: () => null,
  }),
])

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Locator, Page } from '@playwright/test'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)
  await page.waitForTimeout(250)
  if (errors.length) {
    throw new Error(`Page failed during hydration:\n${errors.join('\n')}`)
  }

  // SSR: wait for the jank meter's effect to prove hydration before interacting.
  // Do not depend on requestAnimationFrame, which browsers may throttle.
  try {
    await page.waitForFunction(
      () => {
        const dot = document.querySelector<HTMLElement>('.jank-dot')
        return dot?.dataset.hydrated === 'true'
      },
      undefined,
      { timeout: 5_000 },
    )
  } catch {
    const diagnostics = await page.evaluate(() => ({
      readyState: document.readyState,
      scripts: Array.from(document.scripts).map((script) => ({
        src: script.src,
        type: script.type,
      })),
    }))
    throw new Error(`Hydration diagnostics: ${JSON.stringify(diagnostics)}`)
  }

  return { errors, server }
}

async function getFirstBodyRowText(table: Locator) {
  const text = await table.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders worker-generated rows without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const table = page.locator('table').first()

    await expect(table).toBeVisible()
    await expect(table.locator('thead th').first()).toBeVisible()
    await expect(table.locator('tbody tr').first()).toBeVisible()
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('sorts via the worker when a header is clicked', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const table = page.locator('table').first()
    const bodyRows = table.locator('tbody tr')

    await expect(bodyRows.first()).toBeVisible()

    const firstRowBefore = await getFirstBodyRowText(table)

    await page.getByText('Age', { exact: true }).click()

    await expect.poll(() => getFirstBodyRowText(table)).not.toBe(firstRowBefore)
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('filters via the worker when typing in the search box', async ({
  page,
}) => {
  const { errors, server } = await openExample(page)

  try {
    const table = page.locator('table').first()
    const bodyRows = table.locator('tbody tr')

    await expect(bodyRows.first()).toBeVisible()

    await page.getByPlaceholder('Search name or status...').fill('complicated')

    await expect.poll(() => getFirstBodyRowText(table)).toContain('complicated')
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('groups via the worker when a grouping toggle is clicked', async ({
  page,
}) => {
  const { errors, server } = await openExample(page)

  try {
    const table = page.locator('table').first()
    const bodyRows = table.locator('tbody tr')

    await expect(bodyRows.first()).toBeVisible()

    // Group by Status: first row becomes a collapsed group row with an
    // expander and a leaf count.
    await page.locator('th', { hasText: 'Status' }).getByRole('button').click()

    await expect.poll(() => getFirstBodyRowText(table)).toContain('👉')
    await expect.poll(() => getFirstBodyRowText(table)).toMatch(/\(\d/)
    await expect.poll(() => getFirstBodyRowText(table)).toContain('Median')
    await expect.poll(() => getFirstBodyRowText(table)).toContain('Range')

    // Expand the first group: leaf rows appear beneath it.
    await table.locator('tbody button').first().click()
    await expect.poll(() => getFirstBodyRowText(table)).toContain('👇')

    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('selects rows on the main thread', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const table = page.locator('table').first()
    const bodyRows = table.locator('tbody tr')

    await expect(bodyRows.first()).toBeVisible()

    const firstRowCheckbox = bodyRows.first().locator('input[type="checkbox"]')
    await firstRowCheckbox.check()

    await expect(firstRowCheckbox).toBeChecked()
    await expect(page.getByText(/1 selected/)).toBeVisible()

    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

import { createFormHook, createFormHookContexts } from '@tanstack/react-form'

// Create form and field contexts
export const { fieldContext, useFieldContext, formContext, useFormContext } =
  createFormHookContexts()

function getErrorMessage(error: unknown) {
  if (typeof error === 'string') return error

  if (error && typeof error === 'object' && 'message' in error) {
    const message = error.message
    if (typeof message === 'string') return message
  }

  return String(error)
}

function FieldErrors({
  errors,
  isBlurred,
  isTouched,
}: {
  errors: ReadonlyArray<unknown>
  isBlurred: boolean
  isTouched: boolean
}) {
  if (!isTouched && !isBlurred) return null
  if (errors.length === 0) return null

  return (
    <div className="error-text">{errors.map(getErrorMessage).join(', ')}</div>
  )
}

// TextField component for string inputs
function TextField() {
  const field = useFieldContext<string>()
  const { errors, isBlurred, isTouched } = field.state.meta

  return (
    <div>
      <input
        className="text-input"
        value={field.state.value}
        onChange={(e) => field.handleChange(e.target.value)}
        onBlur={field.handleBlur}
      />
      <FieldErrors
        errors={errors}
        isBlurred={isBlurred}
        isTouched={isTouched}
      />
    </div>
  )
}

// NumberField component for numeric inputs
function NumberField() {
  const field = useFieldContext<number>()
  const { errors, isBlurred, isTouched } = field.state.meta

  return (
    <div>
      <input
        type="number"
        className="number-input"
        value={field.state.value}
        onChange={(e) => field.handleChange(Number(e.target.value))}
        onBlur={field.handleBlur}
      />
      <FieldErrors
        errors={errors}
        isBlurred={isBlurred}
        isTouched={isTouched}
      />
    </div>
  )
}

// SelectField component for status dropdown
const statusOptions = ['relationship', 'complicated', 'single'] as const

function SelectField() {
  const field = useFieldContext<string>()
  const { errors, isBlurred, isTouched } = field.state.meta

  return (
    <div>
      <select
        className="compact-input"
        value={field.state.value}
        onChange={(e) => field.handleChange(e.target.value)}
        onBlur={field.handleBlur}
      >
        {statusOptions.map((status) => (
          <option key={status} value={status}>
            {status}
          </option>
        ))}
      </select>
      <FieldErrors
        errors={errors}
        isBlurred={isBlurred}
        isTouched={isTouched}
      />
    </div>
  )
}

// SubmitButton component that shows form state
function SubmitButton({ label }: { label: string }) {
  const form = useFormContext()
  return (
    <form.Subscribe selector={(state) => [state.isSubmitting, state.canSubmit]}>
      {([isSubmitting, canSubmit]) => (
        <button
          type="submit"
          disabled={!canSubmit || isSubmitting}
          className="demo-button primary-action submit-button"
        >
          {isSubmitting ? 'Submitting...' : label}
        </button>
      )}
    </form.Subscribe>
  )
}

// FormStateIndicator component to show dirty/valid state
function FormStateIndicator() {
  const form = useFormContext()
  return (
    <form.Subscribe
      selector={(state) => ({
        isDirty: state.isDirty,
        isValid: state.isValid,
      })}
    >
      {({ isDirty, isValid }) => (
        <div className="form-status">
          <span className={isDirty ? 'warning-text' : 'muted-text'}>
            {isDirty ? '● Modified' : '○ Pristine'}
          </span>
          <span className={isValid ? 'success-text' : 'error-text'}>
            {isValid ? '✓ Valid' : '✗ Invalid'}
          </span>
        </div>
      )}
    </form.Subscribe>
  )
}

// Create the form hook with all components
export const { useAppForm, withForm } = createFormHook({
  fieldComponents: {
    TextField,
    NumberField,
    SelectField,
  },
  formComponents: {
    SubmitButton,
    FormStateIndicator,
  },
  fieldContext,
  formContext,
})

