export function DebouncedInput({
  value: initialValue,
  onChange,
  debounce = 200,
  devtoolsKey,
  ...props
}: {
  value: string | number
  onChange: (value: string | number) => void
  debounce?: number
  devtoolsKey: string
} & Omit<InputHTMLAttributes<HTMLInputElement>, 'onChange'>) {
  const [value, setValue] = useState<string | number>(initialValue)

  useEffect(() => {
    setValue(initialValue)
  }, [initialValue])

  const debouncedOnChange = useDebouncedCallback(onChange, {
    key: devtoolsKey,
    wait: debounce,
  })

  return (
    <input
      {...props}
      value={value}
      onChange={(e) => {
        const nextValue =
          e.target.value === ''
            ? ''
            : props.type === 'number'
              ? e.target.valueAsNumber
              : e.target.value

        setValue(nextValue)
        debouncedOnChange(nextValue)
      }}
    />
  )
}

import {
  columnFilteringFeature,
  metaHelper,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  tableFeatures,
  useTable,
} from '@tanstack/react-table'
import { useTanStackTableDevtools } from '@tanstack/react-table-devtools'
import { useEffect } from 'react'
import { DebouncedInput } from './debouncedInput'
import type {
  ColumnDef,
  OnChangeFn,
  PaginationState,
  SortingState,
  TableOptions_RowPagination,
} from '@tanstack/react-table'
import type { Filters } from '../api/types'

// allows us to define custom properties for our columns
interface MyColumnMeta {
  filterKey?: string
  filterVariant?: 'text' | 'number'
}

export const features = tableFeatures({
  columnFilteringFeature,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  columnMeta: metaHelper<MyColumnMeta>(),
})

export const DEFAULT_PAGE_INDEX = 0
export const DEFAULT_PAGE_SIZE = 10

type Props<TData extends Record<string, string | number>> = {
  data: Array<TData>
  columns: Array<ColumnDef<typeof features, TData>>
  pagination: PaginationState
  paginationOptions: Pick<
    TableOptions_RowPagination,
    'onPaginationChange' | 'rowCount'
  >
  filters: Filters<TData>
  onFilterChange: (dataFilters: Partial<TData>) => void
  sorting: SortingState
  onSortingChange: OnChangeFn<SortingState>
}

export default function Table<T extends Record<string, string | number>>({
  columns,
  data,
  filters,
  onFilterChange,
  onSortingChange,
  pagination,
  paginationOptions,
  sorting,
}: Props<T>) {
  const table = useTable(
    {
      key: 'with-tanstack-router-users',
      debugTable: true,
      features,
      columns,
      data,
      manualFiltering: true,
      manualPagination: true,
      manualSorting: true,
      onSortingChange,
      ...paginationOptions,
    },
    (state) => state, // default selector
  )

  useTanStackTableDevtools(table)

  // Sync controlled state with per-slice base atoms
  useEffect(() => {
    table.baseAtoms.pagination.set(pagination)
    table.baseAtoms.sorting.set(sorting)
  }, [table, pagination, sorting])

  return (
    <div>
      <table>
        <thead>
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const fieldMeta = header.column.columnDef.meta
                return (
                  <th key={header.id} colSpan={header.colSpan}>
                    {header.isPlaceholder ? null : (
                      <>
                        <div
                          className={
                            header.column.getCanSort() ? 'sortable-header' : ''
                          }
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          <table.FlexRender header={header} />
                          {{
                            asc: ' 🔼',
                            desc: ' 🔽',
                            false: ' 🔃',
                          }[header.column.getIsSorted() as string] ?? null}
                        </div>
                        {header.column.getCanFilter() &&
                        fieldMeta?.filterKey !== undefined ? (
                          <DebouncedInput
                            devtoolsKey={`with-tanstack-router-${fieldMeta.filterKey}`}
                            className="filter-select"
                            onChange={(value) => {
                              onFilterChange({
                                [fieldMeta.filterKey as keyof T]: value,
                              } as Partial<T>)
                            }}
                            placeholder="Search..."
                            type={
                              fieldMeta.filterVariant === 'number'
                                ? 'number'
                                : 'text'
                            }
                            value={filters[fieldMeta.filterKey] ?? ''}
                          />
                        ) : null}
                      </>
                    )}
                  </th>
                )
              })}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => {
            return (
              <tr key={row.id}>
                {row.getAllCells().map((cell) => {
                  return (
                    <td key={cell.id}>
                      <table.FlexRender cell={cell} />
                    </td>
                  )
                })}
              </tr>
            )
          })}
        </tbody>
      </table>
      <div className="controls pagination-controls">
        <button
          className="demo-button demo-button-sm disabled-button"
          onClick={() => table.setPageIndex(0)}
          disabled={!table.getCanPreviousPage()}
        >
          {'<<'}
        </button>
        <button
          className="demo-button demo-button-sm disabled-button"
          onClick={() => table.previousPage()}
          disabled={!table.getCanPreviousPage()}
        >
          {'<'}
        </button>
        <button
          className="demo-button demo-button-sm disabled-button"
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
        >
          {'>'}
        </button>
        <button
          className="demo-button demo-button-sm disabled-button"
          onClick={() => table.lastPage()}
          disabled={!table.getCanLastPage()}
        >
          {'>>'}
        </button>
        <span className="inline-controls">
          <div>Page</div>
          <strong>
            {(table.state.pagination.pageIndex + 1).toLocaleString()} of{' '}
            {table.getPageCount().toLocaleString()}
          </strong>
        </span>
        <span className="inline-controls">
          | Go to page:
          <input
            type="number"
            value={table.state.pagination.pageIndex + 1}
            onChange={(e) => {
              const page = e.target.value ? Number(e.target.value) - 1 : 0
              table.setPageIndex(page)
            }}
            className="page-size-input"
          />
        </span>
        <select
          value={table.state.pagination.pageSize}
          onChange={(e) => {
            table.setPageSize(Number(e.target.value))
          }}
        >
          {[10, 20, 30, 40, 50].map((pageSize) => (
            <option key={pageSize} value={pageSize}>
              Show {pageSize}
            </option>
          ))}
        </select>
      </div>
    </div>
  )
}

import { getRouteApi } from '@tanstack/react-router'
