function pruneFrameTimestamps(timestamps: Array<number>, now: number): void {
  const cutoff = now - frameRateWindowMs
  const firstRetainedIndex = timestamps.findIndex(
    (timestamp) => timestamp >= cutoff,
  )
  if (firstRetainedIndex > 0) timestamps.splice(0, firstRetainedIndex)
  else if (firstRetainedIndex === -1) timestamps.length = 0
}

function calculateFrameRate(
  timestamps: ReadonlyArray<number>,
  trackingStartedAt: number,
  now: number,
): number {
  const observedWindowMs = Math.min(
    frameRateWindowMs,
    Math.max(1, now - trackingStartedAt),
  )
  return (timestamps.length / observedWindowMs) * 1_000
}

export function exposeTradingBenchmarkSnapshot(
  metrics: FeedMetrics,
  extras: { mountedCells: number; liveComponents: number },
): void {
  Object.assign(globalThis, {
    __TANSTACK_TRADING_BENCHMARK__: {
      capturedAt: performance.now(),
      metrics,
      ...extras,
    },
  })
}

import { createMemo, createSignal, onCleanup, onMount } from 'solid-js'
import { TRADING_COLUMN_COUNT } from '../table/table-config/trading-columns'
import {
  FORCED_VIRTUALIZATION_ROW_COUNT,
  resolveVirtualScrollMode,
} from '../table/trading-row-virtualizer'
import {
  BenchmarkMonitor,
  exposeTradingBenchmarkSnapshot,
  initialMetrics,
  longAnimationFramesSupported,
} from './benchmark-monitor'
import type { MarketFeedController } from '../feed/market-feed-controller'
import type { RendererMode } from '../table/table-config/trading-columns'
import type { VirtualScrollPreference } from '../table/trading-row-virtualizer'

export function createTradingBenchmarkController(feed: MarketFeedController) {
  const [rendererMode, setRendererMode] = createSignal<RendererMode>('stable')
  const [requestedVirtualScrollMode, setRequestedVirtualScrollMode] =
    createSignal<VirtualScrollPreference>('auto')
  const [renderedRowCount, setRenderedRowCount] = createSignal(0)
  const [selectedSymbol, setSelectedSymbol] = createSignal<string | null>(null)
  const [metrics, setMetrics] = createSignal(initialMetrics)
  const monitor = new BenchmarkMonitor()
  const runtime = {
    animationFrameId: 0,
    longAnimationFrameObserver: null as PerformanceObserver | null,
    mutationObserver: null as MutationObserver | null,
  }

  const stopObservingFeed = feed.observe({
    messageReceived: () => monitor.recordWorkerMessage(),
    mutationStarted: () => monitor.markCommitPending(),
    batchApplied: ({ tickCount, updateCount, supersededUpdateCount }) =>
      monitor.recordBatch(tickCount, updateCount, supersededUpdateCount),
    renderCommitted: () => monitor.recordDomCommit(),
  })

  const observeTableMutations = (): void => {
    const tableBody = document.querySelector(
      '.market-panel [data-trading-table] tbody',
    )
    if (!tableBody) return

    monitor.resetDomMutations()
    runtime.mutationObserver = new MutationObserver((records) => {
      monitor.recordDomMutations(records.length)
    })
    runtime.mutationObserver.observe(tableBody, {
      attributes: true,
      attributeFilter: ['class', 'style'],
      characterData: true,
      childList: true,
      subtree: true,
    })
  }

  const benchmarkFrame = (now: number): void => {
    monitor.recordAnimationFrame(now)
    if (monitor.shouldPublish(now)) {
      const nextMetrics = monitor.publish(now)
      setMetrics(nextMetrics)
      exposeTradingBenchmarkSnapshot(nextMetrics, {
        mountedCells: renderedRowCount() * TRADING_COLUMN_COUNT,
        liveComponents:
          nextMetrics.componentsCreated - nextMetrics.componentsDestroyed,
      })
    }
    runtime.animationFrameId = requestAnimationFrame(benchmarkFrame)
  }

  onMount(() => {
    observeTableMutations()
    if (longAnimationFramesSupported) {
      runtime.longAnimationFrameObserver = new PerformanceObserver(
        (entries) => {
          for (const entry of entries.getEntries()) {
            monitor.recordLongAnimationFrame(entry.duration, entry.startTime)
          }
        },
      )
      runtime.longAnimationFrameObserver.observe({
        type: 'long-animation-frame',
      })
    }
    runtime.animationFrameId = requestAnimationFrame(benchmarkFrame)
  })

  onCleanup(() => {
    stopObservingFeed()
    cancelAnimationFrame(runtime.animationFrameId)
    runtime.longAnimationFrameObserver?.disconnect()
    runtime.mutationObserver?.disconnect()
  })

  const resetViewState = (): void => {
    setSelectedSymbol(null)
    setRequestedVirtualScrollMode('auto')
  }

  const actions = {
    resetViewState,
    setRendererMode,
    setVirtualScrollEnabled(enabled: boolean): void {
      if (feed.state.instrumentCount() >= FORCED_VIRTUALIZATION_ROW_COUNT)
        return
      setRequestedVirtualScrollMode(enabled ? 'tanstack' : 'none')
    },
    setRenderedRowCount,
    selectSymbol: setSelectedSymbol,
    resetMarket(): void {
      monitor.reset()
      resetViewState()
      setMetrics({ ...initialMetrics })
      feed.actions.reset()
    },
  }

  const virtualScrollForced = createMemo(
    () => feed.state.instrumentCount() >= FORCED_VIRTUALIZATION_ROW_COUNT,
  )
  const virtualScrollMode = createMemo(() =>
    resolveVirtualScrollMode(
      requestedVirtualScrollMode(),
      feed.state.instrumentCount(),
    ),
  )
  const mountedCells = createMemo(
    () => renderedRowCount() * TRADING_COLUMN_COUNT,
  )
  const liveComponents = createMemo(
    () => metrics().componentsCreated - metrics().componentsDestroyed,
  )

  return {
    feed,
    state: {
      rendererMode,
      requestedVirtualScrollMode,
      virtualScrollForced,
      virtualScrollMode,
      renderedRowCount,
      selectedSymbol,
      metrics,
      mountedCells,
      liveComponents,
    },
    actions,
    monitor,
  }
}

export type TradingBenchmarkController = ReturnType<
  typeof createTradingBenchmarkController
>

import { createSignal, onCleanup, onMount } from 'solid-js'
import { normalizeFeedSampleRate } from './feed-sample-rates'
import { initialMarketFeedConfig } from './market-feed-config'
import { applyMarketUpdates, hydrateMarketQuotes } from './market-data'
import type {
  MarketFeedCommand,
  MarketFeedEvent,
} from './worker/market-feed-protocol'
import type { MarketQuote } from './market-data'

export interface MarketFeedBatch {
  tickCount: number
  updateCount: number
  supersededUpdateCount: number
}

export interface MarketFeedObserver {
  messageReceived?: () => void
  mutationStarted?: () => void
  batchApplied?: (batch: MarketFeedBatch) => void
  renderCommitted?: () => void
}

export function createMarketFeedController() {
  const [workerReady, setWorkerReady] = createSignal(false)
  const [running, setRunning] = createSignal(
    !new URLSearchParams(location.search).has('paused'),
  )
  const [instrumentCount, setInstrumentCount] = createSignal(
    initialMarketFeedConfig.instrumentCount,
  )
  const [targetTicksPerSecond, setTargetTicksPerSecond] = createSignal(
    initialMarketFeedConfig.targetSamplesPerSecond,
  )
  const [publishIntervalMs, setPublishIntervalMsState] = createSignal(
    initialMarketFeedConfig.publishIntervalMs,
  )
  const [updateSparklines, setUpdateSparklines] = createSignal(
    initialMarketFeedConfig.updateSparklines,
  )
  const [sparklineSampleIntervalMs, setSparklineSampleIntervalMs] =
    createSignal(initialMarketFeedConfig.sparklineSampleIntervalMs)
  const [quotes, setQuotes] = createSignal<Array<MarketQuote>>([])
  const observers = new Set<MarketFeedObserver>()
  const runtime = {
    worker: null as Worker | null,
    feedSessionId: 0,
    renderPending: false,
    quoteIndexBySymbol: new Map<string, number>(),
  }

  const post = (command: MarketFeedCommand): void =>
    runtime.worker?.postMessage(command)

  const startMutation = (): void => {
    runtime.renderPending = true
    for (const observer of observers) {
      observer.mutationStarted?.()
    }
  }

  const completeRender = (): void => {
    if (!runtime.renderPending) return

    runtime.renderPending = false
    for (const observer of observers) {
      observer.renderCommitted?.()
    }
  }

  const handleWorkerMessage = ({
    data,
  }: MessageEvent<MarketFeedEvent>): void => {
    if (data.type === 'snapshot') {
      runtime.feedSessionId = data.sessionId
      startMutation()
      const nextQuotes = hydrateMarketQuotes(data.quotes)
      runtime.quoteIndexBySymbol = new Map(
        nextQuotes.map((quote, index) => [quote.symbol, index]),
      )
      setQuotes(nextQuotes)
      setWorkerReady(true)
      return
    }

    if (data.sessionId !== runtime.feedSessionId) return

    for (const observer of observers) {
      observer.messageReceived?.()
    }
    startMutation()
    setQuotes((currentQuotes) =>
      applyMarketUpdates(currentQuotes, data.updates),
    )
    const batch = {
      tickCount: data.tickCount,
      updateCount: data.updates.length,
      supersededUpdateCount: data.coalescedUpdateCount,
    }
    for (const observer of observers) {
      observer.batchApplied?.(batch)
    }
  }

  const handleWorkerError = (error: ErrorEvent): void => {
    setWorkerReady(false)
    setRunning(false)
    console.error('Market feed worker failed', error)
  }

  const reset = (): void => {
    setWorkerReady(false)
    post({ type: 'reset', rowCount: instrumentCount() })
  }

  onMount(() => {
    runtime.worker = new Worker(
      new URL('./worker/market-feed.worker.ts', import.meta.url),
      { type: 'module' },
    )
    runtime.worker.addEventListener('message', handleWorkerMessage)
    runtime.worker.addEventListener('error', handleWorkerError)
    post({
      type: 'start',
      rowCount: instrumentCount(),
      running: running(),
      ticksPerSecond: targetTicksPerSecond(),
      publishIntervalMs: publishIntervalMs(),
      updateSparklines: updateSparklines(),
      sparklineSampleIntervalMs: sparklineSampleIntervalMs(),
    })
  })

  onCleanup(() => {
    runtime.worker?.removeEventListener('message', handleWorkerMessage)
    runtime.worker?.removeEventListener('error', handleWorkerError)
    runtime.worker?.terminate()
    runtime.worker = null
    observers.clear()
  })

  const actions = {
    toggle(): void {
      const nextRunning = !running()
      setRunning(nextRunning)
      post({ type: 'set-running', running: nextRunning })
    },
    setInstrumentCount(count: number): void {
      setInstrumentCount(count)
      reset()
    },
    setTargetRate(rate: number): void {
      const sampleRate = normalizeFeedSampleRate(rate)
      setTargetTicksPerSecond(sampleRate)
      post({ type: 'set-rate', ticksPerSecond: sampleRate })
    },
    setPublishInterval(intervalMs: number): void {
      setPublishIntervalMsState(intervalMs)
      post({ type: 'set-publish-interval', intervalMs })
    },
    setSparklineUpdates(enabled: boolean): void {
      setUpdateSparklines(enabled)
      post({ type: 'set-sparklines', enabled })
    },
    setSparklineSampleInterval(intervalMs: number): void {
      setSparklineSampleIntervalMs(intervalMs)
      post({ type: 'set-sparkline-interval', intervalMs })
    },
    runBurst(): void {
      post({ type: 'burst', tickCount: 25_000 })
    },
    reset,
  }

  return {
    state: {
      workerReady,
      running,
      instrumentCount,
      targetTicksPerSecond,
      publishIntervalMs,
      updateSparklines,
      sparklineSampleIntervalMs,
      quotes,
    },
    actions,
    observe(observer: MarketFeedObserver): () => void {
      observers.add(observer)
      return () => observers.delete(observer)
    },
    getQuoteBySymbol(symbol: string | null): MarketQuote | null {
      if (symbol === null) return null

      const index = runtime.quoteIndexBySymbol.get(symbol)
      return index === undefined ? null : (quotes()[index] ?? null)
    },
    completeRender,
  }
}

