import { FlexRender } from '@tanstack/solid-table'
import { For, Show } from 'solid-js'
import { createColumnDrag } from './create-column-drag'
import { sortAriaValue, sortIndicator } from './table-interactions'
import type { JSX } from 'solid-js'
import type { ColumnDrag } from './create-column-drag'
import type {
  TradingHeader,
  TradingTableInstance,
} from './trading-table-features'

export interface TradingTableHeaderProps {
  table: TradingTableInstance
}

export function TradingTableHeader(props: TradingTableHeaderProps) {
  const columnDrag = createColumnDrag(props.table)

  return (
    <thead>
      <For each={props.table.getHeaderGroups()}>
        {(headerGroup) => (
          <tr>
            <For each={headerGroup.headers}>
              {(header) => (
                <TradingHeaderCell header={header} columnDrag={columnDrag} />
              )}
            </For>
          </tr>
        )}
      </For>
    </thead>
  )
}

interface TradingHeaderCellProps {
  header: TradingHeader
  columnDrag: ColumnDrag
}

function TradingHeaderCell(props: TradingHeaderCellProps) {
  const isLeaf = () => props.header.subHeaders.length === 0
  const headerCellProps = createHeaderCellProps(
    () => props.header,
    isLeaf,
    props.columnDrag,
  )

  return (
    <th {...headerCellProps}>
      <Show when={!props.header.isPlaceholder}>
        <Show when={isLeaf()} fallback={<FlexRender header={props.header} />}>
          <TradingLeafHeader
            header={props.header}
            columnDrag={props.columnDrag}
          />
        </Show>
      </Show>
    </th>
  )
}

function TradingLeafHeader(props: TradingHeaderCellProps) {
  const dropZoneProps = props.columnDrag.createDropZoneProps(
    props.header.column.id,
  )
  const dragHandleProps = props.columnDrag.createHandleProps(
    props.header.column.id,
  )
  const sortButtonProps = createSortButtonProps(() => props.header)
  const resizeHandleProps = createResizeHandleProps(() => props.header)

  return (
    <>
      <div class="leaf-header-content" {...dropZoneProps}>
        <button type="button" class="column-drag-handle" {...dragHandleProps}>
          ⋮⋮
        </button>
        <button {...sortButtonProps}>
          <span class="header-label">
            <FlexRender header={props.header} />
          </span>
          <Show when={props.header.column.getCanSort()}>
            <span
              class="sort-indicator"
              classList={{
                'is-active': !!props.header.column.getIsSorted(),
              }}
              aria-hidden="true"
            >
              {sortIndicator(props.header.column.getIsSorted())}
            </span>
          </Show>
        </button>
      </div>
      <Show when={props.header.column.getCanResize()}>
        <div {...resizeHandleProps} />
      </Show>
    </>
  )
}

function createHeaderCellProps(
  header: () => TradingHeader,
  isLeaf: () => boolean,
  columnDrag: ColumnDrag,
): JSX.IntrinsicElements['th'] {
  return {
    get colSpan() {
      return header().colSpan
    },
    get style() {
      return {
        width: `calc(var(--header-${header().id}-size) * 1px)`,
      }
    },
    get ['aria-sort']() {
      return isLeaf() ? sortAriaValue(header().column.getIsSorted()) : undefined
    },
    get classList() {
      const columnId = header().column.id
      return {
        'column-group-header': !isLeaf(),
        'numeric-header': isLeaf() && !isTextColumn(columnId),
        'is-column-dragging': columnDrag.isDragging(columnId),
        'is-column-drop-target': columnDrag.isDropTarget(columnId),
      }
    },
  }
}

function createSortButtonProps(
  header: () => TradingHeader,
): JSX.IntrinsicElements['button'] {
  return {
    type: 'button',
    class: 'sort-header-button',
    get classList() {
      return { 'is-sortable': header().column.getCanSort() }
    },
    get disabled() {
      return !header().column.getCanSort()
    },
    onClick: header().column.getToggleSortingHandler(),
  }
}

function createResizeHandleProps(
  header: () => TradingHeader,
): JSX.IntrinsicElements['div'] {
  return {
    class: 'column-resize-handle',
    get classList() {
      return { 'is-resizing': header().column.getIsResizing() }
    },
    role: 'separator',
    'aria-orientation': 'vertical',
    onDblClick: () => header().column.resetSize(),
    onMouseDown: header().getResizeHandler(),
    onTouchStart: header().getResizeHandler(),
  }
}

function isTextColumn(columnId: string): boolean {
  return columnId === 'market' || columnId === 'name' || columnId === 'symbol'
}

import { FlexRender } from '@tanstack/solid-table'
import { Index, createMemo } from 'solid-js'
import { TradingRowDataProvider } from './trading-row-data-context'
import type { VirtualItem } from '@tanstack/solid-virtual'
import type { TradingColumnSet } from './table-config/trading-columns'
import type { TradingCell, TradingRow } from './trading-table-features'

export interface TradingTableRowProps {
  row: TradingRow
  columnVersion: TradingColumnSet
  selectedSymbol: string | null
  virtualItem?: VirtualItem
}

interface TradingTableCellProps {
  cell: TradingCell
  renderCell: TradingCell
}

export function TradingTableRow(props: TradingTableRowProps) {
  const currentCells = createMemo(() => props.row.getVisibleCells())
  const renderState = createMemo(
    () => ({
      rowId: props.row.id,
      columns: props.columnVersion,
      cells: currentCells(),
    }),
    undefined,
    {
      equals: (previous, next) =>
        previous.rowId === next.rowId &&
        previous.columns === next.columns &&
        haveSameCellOrder(previous.cells, next.cells),
    },
  )

  return (
    <TradingRowDataProvider quote={() => props.row.original}>
      <tr
        classList={{ 'virtual-table-row': props.virtualItem !== undefined }}
        style={
          props.virtualItem
            ? { transform: `translateY(${props.virtualItem.start}px)` }
            : undefined
        }
        data-virtual-index={props.virtualItem?.index}
        data-symbol={props.row.original.symbol}
        data-row-id={props.row.id}
        data-symbol-selected={
          props.selectedSymbol === props.row.original.symbol
            ? 'true'
            : undefined
        }
        title={props.virtualItem ? undefined : props.row.original.company}
        aria-selected={props.row.getIsSelected()}
      >
        <Index each={currentCells()}>
          {(cell, index) => (
            <TradingTableCell
              cell={cell()}
              renderCell={renderState().cells[index]}
            />
          )}
        </Index>
      </tr>
    </TradingRowDataProvider>
  )
}

function TradingTableCell(props: TradingTableCellProps) {
  const selection = createMemo(() => ({
    edges: props.cell.getSelectionEdges(),
    focused: props.cell.getIsFocused(),
    selected: props.cell.getIsSelected(),
    tabIndex: props.cell.getTabIndex(),
  }))

  return (
    <td
      style={{
        width: `calc(var(--col-${props.cell.column.id}-size) * 1px)`,
      }}
      data-column-id={props.cell.column.id}
      data-cell-focused={selection().focused ? 'true' : undefined}
      data-selection-top={selection().edges.top ? 'true' : undefined}
      data-selection-right={selection().edges.right ? 'true' : undefined}
      data-selection-bottom={selection().edges.bottom ? 'true' : undefined}
      data-selection-left={selection().edges.left ? 'true' : undefined}
      aria-selected={selection().selected}
      tabindex={selection().tabIndex}
    >
      <FlexRender cell={props.renderCell} />
    </td>
  )
}

function haveSameCellOrder(
  previous: ReadonlyArray<TradingCell>,
  next: ReadonlyArray<TradingCell>,
): boolean {
  return (
    previous.length === next.length &&
    previous.every((cell, index) => cell.column.id === next[index]?.column.id)
  )
}

import { createSignal } from 'solid-js'
import {
  useMarketFeedController,
  useTradingShellController,
} from '../shell/trading-shell-context'
import { createTradingTableModel } from './create-trading-table-model'
import {
  createTradingGridProps,
  createTradingTableElementProps,
} from './trading-grid-props'
import {
  createFeedCommitTracking,
  createTableAutoFit,
} from './trading-table-effects'
import { createTradingRowVirtualization } from './trading-row-virtualizer'
import { TradingTableBody } from './trading-table-body'
import { TradingTableFooter } from './trading-table-footer'
import { TradingTableHeader } from './trading-table-header'

export function TradingTable() {
  const feed = useMarketFeedController()
  const { state, actions } = useTradingShellController()
  const [scrollElement, setScrollElement] = createSignal<HTMLDivElement | null>(
    null,
  )
  const virtualized = () => state.virtualScrollMode() === 'tanstack'
  const model = createTradingTableModel({
    quotes: feed.state.quotes,
    rendererMode: state.rendererMode,
    onSelectSymbol: actions.selectSymbol,
  })
  const virtualization = createTradingRowVirtualization({
    rows: model.rows,
    scrollElement,
    enabled: virtualized,
    onRenderedRowCount: actions.setRenderedRowCount,
  })
  const elementOptions = { table: model.table, virtualized }
  const gridProps = createTradingGridProps(elementOptions)
  const tableProps = createTradingTableElementProps(
    elementOptions,
    model.tableStyle,
  )

  createFeedCommitTracking(feed.state.quotes, feed.completeRender)
  createTableAutoFit(model.table, scrollElement)

  return (
    <>
      <div
        {...gridProps}
        ref={(element) => {
          setScrollElement(element)
        }}
      >
        <table {...tableProps}>
          <TradingTableHeader table={model.table} />
          <TradingTableBody
            table={model.table}
            rows={model.rows}
            columnVersion={model.columns}
            selectedSymbol={state.selectedSymbol}
            virtualized={virtualized}
            virtualization={virtualization}
            selectSymbol={actions.selectSymbol}
          />
        </table>
      </div>
      <TradingTableFooter
        table={model.table}
        rows={model.rows}
        virtualized={virtualized}
        virtualization={virtualization}
      />
    </>
  )
}

