  getRowCanExpand: (row: Row<TFeatures, TData>) => boolean
}

function TableComponent(props: TableProps<typeof features, Person>) {
  const table = createTable({
    debugTable: true,
    features,
    columns: props.columns,
    get data() {
      return props.data
