import type { PaginationState } from '@tanstack/solid-table'

export type PaginatedData<T> = {
  result: Array<T>
  rowCount: number
}

export type PaginationParams = PaginationState
export type SortParams = { sortBy: `${string}.${'asc' | 'desc'}` }
export type Filters<T> = Partial<T & PaginationParams & SortParams>

import { faker } from '@faker-js/faker'
import type { Filters, PaginatedData } from './types'

const DEFAULT_PAGE = 0
const DEFAULT_PAGE_SIZE = 10

export type User = {
  id: number
  firstName: string
  lastName: string
  age: number
}

export type UserFilters = Filters<User>

function makeData(amount: number): Array<User> {
  return Array(amount)
    .fill(0)
    .map((_, index) => ({
      id: index + 1,
      firstName: faker.person.firstName(),
      lastName: faker.person.lastName(),
      age: faker.number.int(40),
    }))
}

const data = makeData(1000)

export async function fetchUsers(
  filtersAndPagination: UserFilters,
): Promise<PaginatedData<User>> {
  console.log('fetchUsers', filtersAndPagination)
  const {
    pageIndex = DEFAULT_PAGE,
    pageSize = DEFAULT_PAGE_SIZE,
    sortBy,
    ...filters
  } = filtersAndPagination
  const requestedData = data.slice()

  if (sortBy) {
    const [field, order] = sortBy.split('.')
    requestedData.sort((a, b) => {
      const aValue = a[field as keyof User]
      const bValue = b[field as keyof User]
      if (aValue === bValue) return 0
      if (order === 'asc') return aValue > bValue ? 1 : -1
      return aValue < bValue ? 1 : -1
    })
  }

  const filteredData = requestedData.filter((user) => {
    return Object.keys(filters).every((key) => {
      const filter = filters[key as keyof User]
      if (filter === undefined || filter === '') return true
      const value = user[key as keyof User]
      if (typeof value === 'number') return value === +filter
      return value.toLowerCase().includes(`${filter}`.toLowerCase())
    })
  })

  await new Promise((resolve) => setTimeout(resolve, 100))

  return {
    result: filteredData.slice(
      pageIndex * pageSize,
      (pageIndex + 1) * pageSize,
    ),
    rowCount: filteredData.length,
  }
}

import { createDebouncer } from '@tanstack/solid-pacer/debouncer'
import { createEffect, createSignal } from 'solid-js'

type DebouncedInputProps = {
  value: string | number
  onChange: (value: string | number) => void
  debounce?: number
  devtoolsKey: string
  class?: string
  type?: string
  placeholder?: string
}

export function DebouncedInput(props: DebouncedInputProps) {
  const [value, setValue] = createSignal<string | number>(props.value)

  createEffect(() => {
    setValue(() => props.value)
  })

  const onChangeDebouncer = createDebouncer(
    (nextValue: string | number) => props.onChange(nextValue),
    {
      key: props.devtoolsKey,
      wait: () => props.debounce ?? 200,
    },
  )

  createEffect(() => {
    onChangeDebouncer.maybeExecute(value())
  })

  return (
    <input
      type={props.type ?? 'text'}
      value={value()}
      onInput={(e) => {
        if (e.currentTarget.value === '') {
          setValue('')
        } else if (props.type === 'number') {
          setValue(e.currentTarget.valueAsNumber)
        } else {
          setValue(e.currentTarget.value)
        }
      }}
      placeholder={props.placeholder}
      class={props.class}
    />
  )
}

