/** Declared `size` per column, in render order. */
const INITIAL_SIZES: Record<string, number> = {
  firstName: 120,
  lastName: 120,
  age: 100,
  visits: 80,
  status: 200,
  progress: 200,
}

const LEAF_COLUMNS = Object.keys(INITIAL_SIZES)

