  filterFn_equals,
  filterFn_equalsString,
  filterFn_greaterThan,
  filterFn_greaterThanOrEqualTo,
  filterFn_includesString,
  filterFn_lessThan,
  filterFn_lessThanOrEqualTo,
} from '@tanstack/svelte-table'
import { rankItem } from '@tanstack/match-sorter-utils'
