import { ref, shallowRef } from 'vue'
import { TRADING_COLUMN_COUNT } from '../table/trading-table'
import { FORCED_VIRTUALIZATION_ROW_COUNT } from '../table/trading-row-virtualizer'
import {
  BenchmarkMonitor,
  exposeTradingBenchmarkSnapshot,
  initialMetrics,
  longAnimationFramesSupported,
} from './benchmark-monitor'
import type { FeedMetrics } from './benchmark-monitor'
import type { MarketFeedController } from '../feed/market-feed-controller'
import type { RendererMode } from '../table/trading-table'
import type { VirtualScrollPreference } from '../table/trading-row-virtualizer'

export interface TradingBenchmarkActions {
  resetViewState: () => void
  setRendererMode: (mode: RendererMode) => void
  setVirtualScrollEnabled: (enabled: boolean) => void
  setRenderedRowCount: (count: number) => void
  selectSymbol: (symbol: string | null) => void
  resetMarket: () => void
}

export class TradingBenchmarkController {
  readonly requestedVirtualScrollMode = ref<VirtualScrollPreference>('auto')
  readonly metrics = shallowRef<FeedMetrics>(initialMetrics)
  readonly mountedCells = ref(0)
  readonly liveComponents = ref(0)
  readonly selectedSymbol = ref<string | null>(null)
  readonly rendererMode = ref<RendererMode>('stable')
  readonly longAnimationFramesSupported = longAnimationFramesSupported
  readonly monitor = new BenchmarkMonitor()
  readonly feed: MarketFeedController
  readonly actions: TradingBenchmarkActions

  readonly #runtime = {
    animationFrameId: 0,
    longAnimationFrameObserver: null as PerformanceObserver | null,
    stopObservingFeed: null as (() => void) | null,
  }

  constructor(feed: MarketFeedController) {
    this.feed = feed
    this.actions = {
      resetViewState: () => {
        this.selectedSymbol.value = null
        this.requestedVirtualScrollMode.value = 'auto'
      },
      setRendererMode: (mode) => {
        this.rendererMode.value = mode
      },
      setVirtualScrollEnabled: (enabled) => {
        if (
          this.feed.instrumentCount.value >= FORCED_VIRTUALIZATION_ROW_COUNT
        ) {
          return
        }
        this.requestedVirtualScrollMode.value = enabled ? 'tanstack' : 'none'
      },
      setRenderedRowCount: (count) => {
        const mountedCells = count * TRADING_COLUMN_COUNT
        if (mountedCells !== this.mountedCells.value) {
          this.mountedCells.value = mountedCells
        }
      },
      selectSymbol: (symbol) => {
        this.selectedSymbol.value = symbol
      },
      resetMarket: () => {
        this.monitor.reset()
        this.metrics.value = { ...initialMetrics }
        this.mountedCells.value = 0
        this.liveComponents.value = 0
        this.selectedSymbol.value = null
        this.feed.actions.reset()
      },
    }
  }

  start(): () => void {
    const longAnimationFrameObserver = longAnimationFramesSupported
      ? new PerformanceObserver((entries) => {
          for (const entry of entries.getEntries()) {
            this.monitor.recordLongAnimationFrame(
              entry.duration,
              entry.startTime,
            )
          }
        })
      : null

    this.#runtime.longAnimationFrameObserver = longAnimationFrameObserver
    this.#runtime.stopObservingFeed = this.feed.observe({
      messageReceived: () => this.monitor.recordWorkerMessage(),
      mutationStarted: () => this.monitor.markCommitPending(),
      batchApplied: ({ tickCount, updateCount, supersededUpdateCount }) =>
        this.monitor.recordBatch(tickCount, updateCount, supersededUpdateCount),
      renderCommitted: () => this.monitor.recordDomCommit(),
    })
    longAnimationFrameObserver?.observe({
      type: 'long-animation-frame',
    })
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)

    return () => this.stop()
  }

  stop(): void {
    cancelAnimationFrame(this.#runtime.animationFrameId)
    this.#runtime.longAnimationFrameObserver?.disconnect()
    this.#runtime.stopObservingFeed?.()
    this.#runtime.longAnimationFrameObserver = null
    this.#runtime.stopObservingFeed = null
  }

  readonly #benchmarkFrame = (now: number): void => {
    this.monitor.recordAnimationFrame(now)
    if (this.monitor.shouldPublish(now)) {
      this.#publishMetrics(this.monitor.publish(now))
    }
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)
  }

  #publishMetrics(metrics: FeedMetrics): void {
    this.metrics.value = metrics
    this.liveComponents.value =
      metrics.componentsCreated - metrics.componentsDestroyed
    exposeTradingBenchmarkSnapshot(metrics, {
      mountedCells: this.mountedCells.value,
      liveComponents: this.liveComponents.value,
    })
  }
}

import { onBeforeUnmount, onMounted } from 'vue'
import type { TradingBenchmarkController } from './trading-benchmark-controller'

export function useTableBenchmark(
  controller: TradingBenchmarkController,
): void {
  const runtime = { mutationObserver: null as MutationObserver | null }

  onMounted(() => {
    const tableBody = document.querySelector(
      '.market-panel [data-trading-table] tbody',
    )
    if (!tableBody) return

    controller.monitor.resetDomMutations()
    runtime.mutationObserver = new MutationObserver((records) => {
      controller.monitor.recordDomMutations(records.length)
    })
    runtime.mutationObserver.observe(tableBody, {
      attributes: true,
      attributeFilter: ['class', 'style'],
      characterData: true,
      childList: true,
      subtree: true,
    })
  })

  onBeforeUnmount(() => runtime.mutationObserver?.disconnect())
}

import { ref, shallowRef } from 'vue'
import { normalizeFeedSampleRate } from './feed-sample-rates'
import { initialMarketFeedConfig } from './market-feed-config'
import { applyMarketUpdates, hydrateMarketQuotes } from './market-data'
import type {
  MarketFeedCommand,
  MarketFeedEvent,
} from './worker/market-feed-protocol'
import type { MarketQuote } from './market-data'

export interface MarketFeedBatch {
  tickCount: number
  updateCount: number
  supersededUpdateCount: number
}

export interface MarketFeedObserver {
  messageReceived?: () => void
  mutationStarted?: () => void
  batchApplied?: (batch: MarketFeedBatch) => void
  renderCommitted?: () => void
}

export interface MarketFeedActions {
  toggle: () => void
  setInstrumentCount: (count: number) => void
  setTargetRate: (rate: number) => void
  setPublishInterval: (intervalMs: number) => void
  setSparklineUpdates: (enabled: boolean) => void
  setSparklineSampleInterval: (intervalMs: number) => void
  runBurst: () => void
  reset: () => void
}

export class MarketFeedController {
  readonly workerReady = ref(false)
  readonly running = ref(!new URLSearchParams(location.search).has('paused'))
  readonly instrumentCount = ref(initialMarketFeedConfig.instrumentCount)
  readonly targetTicksPerSecond = ref(
    initialMarketFeedConfig.targetSamplesPerSecond,
  )
  readonly publishIntervalMs = ref(initialMarketFeedConfig.publishIntervalMs)
  readonly updateSparklines = ref(initialMarketFeedConfig.updateSparklines)
  readonly sparklineSampleIntervalMs = ref(
    initialMarketFeedConfig.sparklineSampleIntervalMs,
  )
  readonly quotes = shallowRef<Array<MarketQuote>>([])
  readonly actions: MarketFeedActions
  readonly #observers = new Set<MarketFeedObserver>()
  readonly #runtime = {
    worker: null as Worker | null,
    feedSessionId: 0,
    renderPending: false,
    resetWaitingForCommit: false,
    resetSnapshotReady: false,
    quoteIndexBySymbol: new Map<string, number>(),
  }

  constructor() {
    this.actions = {
      toggle: () => {
        const running = !this.running.value
        this.running.value = running
        this.#post({ type: 'set-running', running })
      },
      setInstrumentCount: (count) => {
        this.instrumentCount.value = count
        this.#resetWorker(count)
      },
      setTargetRate: (rate) => {
        const sampleRate = normalizeFeedSampleRate(rate)
        this.targetTicksPerSecond.value = sampleRate
        this.#post({ type: 'set-rate', ticksPerSecond: sampleRate })
      },
      setPublishInterval: (publishIntervalMs) => {
        this.publishIntervalMs.value = publishIntervalMs
        this.#post({
          type: 'set-publish-interval',
          intervalMs: publishIntervalMs,
        })
      },
      setSparklineUpdates: (enabled) => {
        this.updateSparklines.value = enabled
        this.#post({ type: 'set-sparklines', enabled })
      },
      setSparklineSampleInterval: (intervalMs) => {
        this.sparklineSampleIntervalMs.value = intervalMs
        this.#post({ type: 'set-sparkline-interval', intervalMs })
      },
      runBurst: () => this.#post({ type: 'burst', tickCount: 25_000 }),
      reset: () => this.#resetWorker(this.instrumentCount.value),
    }
  }

  start(): () => void {
    const worker = new Worker(
      new URL('./worker/market-feed.worker.ts', import.meta.url),
      { type: 'module' },
    )
    this.#runtime.worker = worker
    worker.addEventListener('message', this.#handleWorkerMessage)
    worker.addEventListener('error', this.#handleWorkerError)
    this.#post({
      type: 'start',
      rowCount: this.instrumentCount.value,
      running: this.running.value,
      ticksPerSecond: this.targetTicksPerSecond.value,
      publishIntervalMs: this.publishIntervalMs.value,
      updateSparklines: this.updateSparklines.value,
      sparklineSampleIntervalMs: this.sparklineSampleIntervalMs.value,
    })
    return () => this.stop()
  }

  stop(): void {
    this.#runtime.worker?.removeEventListener(
      'message',
      this.#handleWorkerMessage,
    )
    this.#runtime.worker?.removeEventListener('error', this.#handleWorkerError)
    this.#runtime.worker?.terminate()
    this.#runtime.worker = null
    this.#observers.clear()
  }

  observe(observer: MarketFeedObserver): () => void {
    this.#observers.add(observer)
    return () => this.#observers.delete(observer)
  }

  getQuoteBySymbol(
    quotes: Array<MarketQuote>,
    symbol: string | null,
  ): MarketQuote | null {
    if (symbol === null) return null

    const index = this.#runtime.quoteIndexBySymbol.get(symbol)
    return index === undefined ? null : (quotes[index] ?? null)
  }

  completeRender(): void {
    if (!this.#runtime.renderPending) return

    this.#runtime.renderPending = false
    for (const observer of this.#observers) {
      observer.renderCommitted?.()
    }
    if (
      this.#runtime.resetWaitingForCommit &&
      this.#runtime.resetSnapshotReady
    ) {
      this.#runtime.resetWaitingForCommit = false
      this.#runtime.resetSnapshotReady = false
      this.#post({ type: 'set-running', running: this.running.value })
    }
  }

  readonly #handleWorkerMessage = ({
    data,
  }: MessageEvent<MarketFeedEvent>): void => {
    if (data.type === 'snapshot') {
      this.#runtime.feedSessionId = data.sessionId
      if (this.#runtime.resetWaitingForCommit) {
        this.#runtime.resetSnapshotReady = true
      }
      this.#startMutation()
      const quotes = hydrateMarketQuotes(data.quotes)
      this.#runtime.quoteIndexBySymbol = new Map(
        quotes.map((quote, index) => [quote.symbol, index]),
      )
      this.quotes.value = quotes
      this.workerReady.value = true
      return
    }

    if (data.sessionId !== this.#runtime.feedSessionId) return

    for (const observer of this.#observers) {
      observer.messageReceived?.()
    }
    this.#startMutation()
    this.quotes.value = applyMarketUpdates(this.quotes.value, data.updates)
    const feedBatch = {
      tickCount: data.tickCount,
      updateCount: data.updates.length,
      supersededUpdateCount: data.coalescedUpdateCount,
    }
    for (const observer of this.#observers) {
      observer.batchApplied?.(feedBatch)
    }
  }

  readonly #handleWorkerError = (error: ErrorEvent): void => {
    this.workerReady.value = false
    this.running.value = false
    console.error('Market feed worker failed', error)
  }

  #resetWorker(rowCount: number): void {
    this.workerReady.value = false
    this.#runtime.resetWaitingForCommit = true
    this.#runtime.resetSnapshotReady = false
    this.#post({ type: 'set-running', running: false })
    this.#post({ type: 'reset', rowCount })
  }

  #startMutation(): void {
    this.#runtime.renderPending = true
    for (const observer of this.#observers) {
      observer.mutationStarted?.()
    }
  }

  #post(command: MarketFeedCommand): void {
    this.#runtime.worker?.postMessage(command)
  }
}

