}

function formatInvocationRates(
  rates: FeedMetrics['cellRendererRates'],
): string {
  const active = rates.filter((entry) => entry.callsPerSecond > 0)
  return active.length === 0
    ? '—'
    : active
        .map((entry) => `${entry.name} ${formatRate(entry.callsPerSecond)}`)
        .join(' · ')
}

