  setup(props) {
    const recordRender = useLifecycleCounter('PercentChangeCell')
    return () => {
      recordRender()
      return (
        <span
          class={[
            'percent-change-cell',
            props.value >= 0 ? 'quote-up' : 'quote-down',
          ]}
        >
          {props.value >= 0 ? '+' : ''}
          {props.value.toFixed(2)}%
        </span>
